INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('afac29e1-ce20-4266-8f23-7bb05390ac64'::uuid, 'card_description', 'Nearly a kilometre through the tuff of Monte Grillo runs the Grotta di Cocceio, a Roman tunnel of 38-36 BC wide enough for two wagons, its Avernus entrance once lined with statues in niches.', 'A nearly 1-kilometre Roman tunnel bored through volcanic tuff in 38–36 BC to connect Lake Avernus to Cumae. It was wide enough for two wagons to pass side by side.', 'teaser-card-s015-rollback:afac29e1-ce20-4266-8f23-7bb05390ac64:card_description', 'rollback of teaser-card-s015: card_description ''A nearly 1-kilometre Roman tunnel bored through volcanic tuff in 38–36 BC to connect Lake Avernus to Cumae. It was wide enough for two wagons to pass side by side.'' restored on Grotta di Cocceio', '189121fd56653c170b43ead5a1298dd3fa25d1019d2b0f6088e605dc9b3ac225|429e75a235ce8f2404aeb20893580014fe4551c90faafb3e7f460dae8a4093c4|429e75a235ce8f2404aeb20893580014fe4551c90faafb3e7f460dae8a4093c4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Nearly a kilometre through the tuff of Monte Grillo runs the Grotta di Cocceio, a Roman tunnel of 38-36 BC wide enough for two wagons, its Avernus entrance once lined with statues in niches."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the tunnel runs nearly a kilometre [S1]; it runs through the tuff of Monte Grillo [S2]; the Grotta di Cocceio is a Roman tunnel [S1]; the tunnel dates from 38-36 BC [S1]; it was wide enough for two wagons [S3]; its Avernus entrance was lined with statues in niches [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Grotta di Cocceio is an ancient Roman tunnel, at Monte Grillo, connecting Lake Avernus with Cumae (Campania, Italy) [SUPPORTED: https://en.wikipedia.org/wiki/Grotta_di_Cocceio]; The tunnel is nearly a kilometre long [SUPPORTED: https://en.wikipedia.org/wiki/Grotta_di_Cocceio]; The tunnel dates from 38-36 BC [SUPPORTED: https://en.wikipedia.org/wiki/Grotta_di_Cocceio]; The tunnel runs through the tuff of Monte Grillo [SUPPORTED: https://en.wikipedia.org/wiki/Grotta_di_Cocceio]; The tunnel was wide enough for two wagons [SUPPORTED: https://en.wikipedia.org/wiki/Grotta_di_Cocceio]; The Avernus entrance was once lined with statues in niches [SUPPORTED: https://en.wikipedia.org/wiki/Grotta_di_Cocceio]"}]'::jsonb),
    ('b048a095-8e3e-41af-a715-e785e3a1a51d'::uuid, 'card_description', 'Drovers, merchants and travellers used the Roman Road from Silchester to Bath, from Calleva Atrebatum to Aquae Sulis. In places it survives; elsewhere no apparent trace remains in view.', '1st–5th century AD. Linked Calleva Atrebatum (Silchester) to Aquae Sulis (Bath) — a military highway later used by medieval drovers. Its earthwork ghost survives as part of the Wansdyke.', 'teaser-card-s015-rollback:b048a095-8e3e-41af-a715-e785e3a1a51d:card_description', 'rollback of teaser-card-s015: card_description ''1st–5th century AD. Linked Calleva Atrebatum (Silchester) to Aquae Sulis (Bath) — a military highway later used by medieval drovers. Its earthwork ghost survives as part of the Wansdyke.'' restored on Roman Road from Silchester to Bath', '9e9655ca9be25b0445aa7002bb844f50ab561c29257365f27291c939edeb12e9|8c1625097069db514ed07641fc6f507392b1624efe026406a564e587e989a2b7|8c1625097069db514ed07641fc6f507392b1624efe026406a564e587e989a2b7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Drovers, merchants and travellers used the Roman Road from Silchester to Bath, from Calleva Atrebatum to Aquae Sulis. In places it survives; elsewhere no apparent trace remains in view."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "drovers used the Roman Road from Silchester to Bath [S4]; merchants used the road [S4]; travellers used the road [S4]; the road ran from Calleva Atrebatum [S1]; the road ran to Aquae Sulis [S1]; in places the road survives [S6]; elsewhere no apparent trace of the road remains in view [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The site is a Roman road in England connecting Silchester with Bath [SUPPORTED: https://en.wikipedia.org/wiki/Roman_road_from_Silchester_to_Bath]; The road started at Calleva Atrebatum (Silchester) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_road_from_Silchester_to_Bath]; The road ended at Aquae Sulis (Bath) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_road_from_Silchester_to_Bath]; Drovers used the road [SUPPORTED: https://en.wikipedia.org/wiki/Roman_road_from_Silchester_to_Bath]; Merchants used the road [SUPPORTED: https://en.wikipedia.org/wiki/Roman_road_from_Silchester_to_Bath]; Travellers used the road [SUPPORTED: https://en.wikipedia.org/wiki/Roman_road_from_Silchester_to_Bath]; In places the road survives [SUPPORTED: https://en.wikipedia.org/wiki/Roman_road_from_Silchester_to_Bath]; Elsewhere no apparent trace of the road remains in view [SUPPORTED: https://en.wikipedia.org/wiki/Roman_road_from_Silchester_to_Bath]"}]'::jsonb),
    ('b04ee52d-6549-4877-8131-2475c9989299'::uuid, 'card_description', 'On the banks of the Garonne, the Roman Villa of Chiragan grew from a modest villa with thermal baths and a peristyle to cover an area equal to one third of the Villa Hadriana in Tivoli.', 'Spanning 16 hectares on the Garonne near Toulouse, this 1st–4th century estate''s walls yielded 70 imperial portrait busts — the largest such collection found outside Rome.', 'teaser-card-s015-rollback:b04ee52d-6549-4877-8131-2475c9989299:card_description', 'rollback of teaser-card-s015: card_description "Spanning 16 hectares on the Garonne near Toulouse, this 1st–4th century estate''s walls yielded 70 imperial portrait busts — the largest such collection found outside Rome." restored on Roman Villa of Chiragan', '575d583de57fe904d39349e8e1dd5bb1d1dc3de55527f878c3b29c828a1ae528|989fa8ad483147b8c6c590bf2a0e6b113009d446055514a41a03b32197800b29|989fa8ad483147b8c6c590bf2a0e6b113009d446055514a41a03b32197800b29', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the banks of the Garonne, the Roman Villa of Chiragan grew from a modest villa with thermal baths and a peristyle to cover an area equal to one third of the Villa Hadriana in Tivoli."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the villa lay on the banks of the Garonne [S2]; the villa began as a modest villa [S4]; that first villa had thermal baths [S5]; that first villa had a peristyle [S5]; the villa grew over time [S3, S6, S7]; at its maximum it covered an area equal to one third of the Villa Hadriana in Tivoli [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Villa of Chiragan is a Roman villa at Martres-Tolosane, France [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Chiragan]; The villa stood on the banks of the Garonne [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Chiragan]; The first villa was of modest dimensions [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Chiragan]; The first villa already had thermal baths and a peristyle [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Chiragan]; The villa grew (was built in several phases) over time [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Chiragan]; At its greatest extent the villa covered an area equal to one third of the Villa Hadriana in Tivoli (only Wikipedia says so; the excavated villa is given as about 16 hectares by Wikipedia and the Saint-Raymond museum, and Hadrian''s Villa as at least a square kilometre, so a third does not fit) [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('b065a36f-0e01-4de3-9100-409a15eeb532'::uuid, 'card_description', 'Dewerstone is a rocky promontory above the River Plym with hill fort ramparts. Dartmoor tradition says the Devil''s phantom black hounds chase the weary or foolish over it to their deaths.', 'Dewerstone is the site of an Iron Age Hill fort on a rocky promontory overlooking the River Plym on the South West edge of Dartmoor to the North of Plympton in Devon.', 'teaser-card-s015-rollback:b065a36f-0e01-4de3-9100-409a15eeb532:card_description', 'rollback of teaser-card-s015: card_description ''Dewerstone is the site of an Iron Age Hill fort on a rocky promontory overlooking the River Plym on the South West edge of Dartmoor to the North of Plympton in Devon.'' restored on Dewerstone', 'a296ca68dddd30c497b5a994fcb22d4d3a8ccb308594a9bfcd8ffcc69750e9c9|bffb8e85bc40d5066d86fa8cf3c858f935fe39e8865802c99cea6997e64e0be6|bffb8e85bc40d5066d86fa8cf3c858f935fe39e8865802c99cea6997e64e0be6', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dewerstone is a rocky promontory above the River Plym with hill fort ramparts. Dartmoor tradition says the Devil''s phantom black hounds chase the weary or foolish over it to their deaths."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dewerstone is a rocky promontory [S1]; it is above the River Plym [S1]; it has hill fort ramparts [S1, S2]; Dartmoor tradition says the Devil leads a phantom pack of black hounds [S3]; the hounds chase the weary or foolish over the Dewerstone to their deaths [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dewerstone is a rocky promontory above the River Plym (central claim: a rocky promontory with a hill fort) [SUPPORTED: https://en.wikipedia.org/wiki/Dewerstone]; The promontory has hill fort ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Dewerstone]; Dartmoor tradition tells of the Devil''s hounds (the Devil leads the pack) [SUPPORTED: https://en.wikipedia.org/wiki/Dewerstone]; The hounds are phantom black hounds [SUPPORTED: https://en.wikipedia.org/wiki/Dewerstone]; The hounds chase the weary or foolish over the Dewerstone to their deaths [SUPPORTED: https://en.wikipedia.org/wiki/Dewerstone]"}]'::jsonb),
    ('b07c4d65-158e-4e9d-9817-f39161b7516d'::uuid, 'card_description', 'Of soft pink sandstone, the Duddo Five Stones look out over the Cheviot and Lammermuir Hills. Known as the Four Stones until 1903, when the fifth was re-erected to improve the skyline.', 'Five weathered stones deeply grooved by millennia of rain. Originally seven, two sockets were found empty in the 1890s — the missing stones never recovered.', 'teaser-card-s015-rollback:b07c4d65-158e-4e9d-9817-f39161b7516d:card_description', 'rollback of teaser-card-s015: card_description ''Five weathered stones deeply grooved by millennia of rain. Originally seven, two sockets were found empty in the 1890s — the missing stones never recovered.'' restored on Duddo Five Stones', '65d84b7360c9303065228d15c02fb56684c1ce667d78dd25c2191a54bc91578f|55780eb8332ccb125b0212f8df6067c1bcabd3a48626258204ca52d2e886a22a|55780eb8332ccb125b0212f8df6067c1bcabd3a48626258204ca52d2e886a22a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Of soft pink sandstone, the Duddo Five Stones look out over the Cheviot and Lammermuir Hills. Known as the Four Stones until 1903, when the fifth was re-erected to improve the skyline."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the stones are of soft pink sandstone [S4]; the site looks out over the Cheviot Hills [S5]; the site looks out over the Lammermuir Hills [S5]; the stones were known as the Four Stones until 1903 [S2]; in 1903 the fifth stone was re-erected [S2]; the fifth stone was re-erected to improve the skyline [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Duddo Five Stones is a stone circle north of Duddo in Northumberland, England (the kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Duddo_Five_Stones]; The stones are of soft pink sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Duddo_Five_Stones]; The site looks out over the Cheviot Hills [SUPPORTED: https://en.wikipedia.org/wiki/Duddo_Five_Stones]; The site looks out over the Lammermuir Hills [SUPPORTED: https://en.wikipedia.org/wiki/Duddo_Five_Stones]; The circle was known as the Four Stones until 1903 [SUPPORTED: https://en.wikipedia.org/wiki/Duddo_Five_Stones]; In 1903 the fifth stone was re-erected [SUPPORTED: https://en.wikipedia.org/wiki/Duddo_Five_Stones]; The fifth stone was re-erected to improve the skyline [SUPPORTED: https://en.wikipedia.org/wiki/Duddo_Five_Stones]"}]'::jsonb),
    ('b0b4e4d6-ef79-4b2d-ad6b-62532b5ba54d'::uuid, 'card_description', 'Near Chan Chan, dragon figures are carved into the adobe walls of the Huaca del Dragón beside reliefs of a rainbow. Ramps climb to a level of pits possibly used to store food.', 'An adobe temple whose walls are carved with dragon and rainbow friezes in relief. Two ramps connect its levels, flanked by figures that gave the temple its name.', 'teaser-card-s015-rollback:b0b4e4d6-ef79-4b2d-ad6b-62532b5ba54d:card_description', 'rollback of teaser-card-s015: card_description ''An adobe temple whose walls are carved with dragon and rainbow friezes in relief. Two ramps connect its levels, flanked by figures that gave the temple its name.'' restored on Huaca del Dragón', '8286b15d402ada5f615cd6e438f3f6da259b5974a9726ec4504fa51c8c503bb2|4beeb477cb9e1e7ee3ca7f7105a036c0899ed9485417eb4cca6120d56f2c9703|4beeb477cb9e1e7ee3ca7f7105a036c0899ed9485417eb4cca6120d56f2c9703', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Chan Chan, dragon figures are carved into the adobe walls of the Huaca del Dragón beside reliefs of a rainbow. Ramps climb to a level of pits possibly used to store food."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Huaca del Dragón is near Chan Chan [S1]; dragon figures are carved on the walls [S5]; the walls are adobe [S3]; there are reliefs representing a rainbow [S3]; ramps lead up to the levels [S4, S6]; one level hosts pits [S7]; the pits were possibly used to store food [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Huaca del Dragón is an archaeological site near Chan Chan, in Peru (central claim: where it is) [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n]; The Huaca del Dragón is a huaca, a religious and ceremonial monument (what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n]; The walls of the Huaca del Dragón are of adobe [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n]; Dragon figures are carved into the walls [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n]; Reliefs of a rainbow decorate the walls [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n]; Ramps climb from level to level (a ramp leads to the second level) [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n]; The upper level holds pits [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n]; The pits were possibly used to store food (function stated as uncertain) [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n]"}]'::jsonb),
    ('b10227e6-8a83-4290-8503-ec037e4bc3c3'::uuid, 'card_description', 'On the South Downs, five large bell barrows stand in a line aligned with sunset on Midsummer Day: the Devil''s Jumps, considered the best preserved Bronze Age barrow group in Sussex.', 'The Devil''s Jumps have been dated to the Bronze Age and they are believed to be between three and four thousand years old.', 'teaser-card-s015-rollback:b10227e6-8a83-4290-8503-ec037e4bc3c3:card_description', 'rollback of teaser-card-s015: card_description "The Devil''s Jumps have been dated to the Bronze Age and they are believed to be between three and four thousand years old." restored on Devil''s Jumps, Treyford', '167adfe2c8b8fb8e05f4ae7a38b025256ebe70add1f3bf18d150fc886fafec8d|64917ecf09fc0eb4cd2a6f01d3caa18e847b8882438b4a37a226c154e4d34846|64917ecf09fc0eb4cd2a6f01d3caa18e847b8882438b4a37a226c154e4d34846', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the South Downs, five large bell barrows stand in a line aligned with sunset on Midsummer Day: the Devil''s Jumps, considered the best preserved Bronze Age barrow group in Sussex."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is on the South Downs [S1]; it consists of five large bell barrows [S1]; the barrows stand in a line [S3]; the line is aligned with sunset on Midsummer Day [S7]; they are the Devil''s Jumps [S1]; they are considered the best preserved Bronze Age barrow group in Sussex [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Devil''s Jumps are a group of barrows (bell barrows) on the South Downs near Treyford, England (central claim: what and where) [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Jumps,_Treyford]; The barrows are Bronze Age in date [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Jumps,_Treyford]; There are five large bell barrows [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Jumps,_Treyford]; The five barrows stand in a line [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Jumps,_Treyford]; The line of barrows is aligned with sunset on Midsummer Day [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Jumps,_Treyford]; They are considered the best preserved Bronze Age barrow group in Sussex [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Jumps,_Treyford]"}]'::jsonb),
    ('b13caf27-5754-44a2-b13d-ec8824ac95f4'::uuid, 'card_description', 'High masonry barriers once closed the gaps between the Doric columns of Temple F, Selinus, perhaps to make a cultic area. In 1823 excavators found two half metopes of Dionysus and Athena.', 'Mid-6th-century BC Doric temple at Selinus with six front columns and fourteen on the flanks, dedicated to Dionysus or Athena. Its cella was screened by a row of small internal columns.', 'teaser-card-s015-rollback:b13caf27-5754-44a2-b13d-ec8824ac95f4:card_description', 'rollback of teaser-card-s015: card_description ''Mid-6th-century BC Doric temple at Selinus with six front columns and fourteen on the flanks, dedicated to Dionysus or Athena. Its cella was screened by a row of small internal columns.'' restored on Temple F, Selinus', '004d14f6ee740297c3ccce7a625ee489904d789e4aeb6b628fa13ea99c1b2f87|dc092eeab113134da621399ec736dd5b95cb03e6724307eedd3156ccfaca6b55|dc092eeab113134da621399ec736dd5b95cb03e6724307eedd3156ccfaca6b55', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "High masonry barriers once closed the gaps between the Doric columns of Temple F, Selinus, perhaps to make a cultic area. In 1823 excavators found two half metopes of Dionysus and Athena."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Temple F at Selinus is Doric [S1]; high masonry barriers closed the gaps between the columns [S6]; the barriers were perhaps built to make a cultic area [S7]; in 1823 excavators found two half metopes [S8]; the half metopes depict Dionysus and Athena [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Temple F at Selinus (Selinunte, Sicily, Italy) is a Greek temple of the Doric order (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_F_(Selinus)]; High masonry barriers closed the gaps between the columns of Temple F [SUPPORTED: https://en.wikipedia.org/wiki/Temple_F_(Selinus)]; The barriers were perhaps built to transform the colonnade into a cultic area (function stated as uncertain) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_F_(Selinus)]; In 1823, during excavations, two half metopes were found [SUPPORTED: https://en.wikipedia.org/wiki/Temple_F_(Selinus)]; The two half metopes depict Dionysus and Athena [SUPPORTED: https://en.wikipedia.org/wiki/Temple_F_(Selinus)]"}]'::jsonb),
    ('b1410fda-e006-411f-a8ce-64513976d158'::uuid, 'card_description', 'On Eyam Moor, with clear views of the River Derwent valley, Wet Withens is the largest embanked stone circle in Derbyshire. Its Chair Stone has a ledge cut out of its face, like a seat.', 'A Bronze Age henge on Eyam Moor in the Peak District with 10 upright orthostats. Its earthen bank exceeds 30 metres in diameter — the largest stone circle of its type in the county.', 'teaser-card-s015-rollback:b1410fda-e006-411f-a8ce-64513976d158:card_description', 'rollback of teaser-card-s015: card_description ''A Bronze Age henge on Eyam Moor in the Peak District with 10 upright orthostats. Its earthen bank exceeds 30 metres in diameter — the largest stone circle of its type in the county.'' restored on Wet Withens', '28904ac0aa5dbb4cd8b880126a04a9fd5ee033a7ab2e97d23dadb77034f0f478|e9ae7206c190e0b9b77ff574c2c5ff58828e8c4cfe9e94e901a9fea6bd5bc2b7|e9ae7206c190e0b9b77ff574c2c5ff58828e8c4cfe9e94e901a9fea6bd5bc2b7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Eyam Moor, with clear views of the River Derwent valley, Wet Withens is the largest embanked stone circle in Derbyshire. Its Chair Stone has a ledge cut out of its face, like a seat."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Wet Withens is on Eyam Moor [S1]; it has clear views of the valley of the River Derwent [S2]; it is the largest embanked stone circle in Derbyshire [S3]; it has a Chair Stone [S4]; the Chair Stone has a ledge cut out of its face [S4]; the ledge appears as a seat [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Wet Withens is a prehistoric embanked stone circle (henge) on Eyam Moor in the Derbyshire Peak District, England (central claim: what and where) [SUPPORTED: https://en.wikipedia.org/wiki/Wet_Withens]; Wet Withens lies on Eyam Moor [SUPPORTED: https://en.wikipedia.org/wiki/Wet_Withens]; The site has clear views of the River Derwent valley [SUPPORTED: https://en.wikipedia.org/wiki/Wet_Withens]; Wet Withens is the largest embanked stone circle in Derbyshire [SUPPORTED: https://en.wikipedia.org/wiki/Wet_Withens]; Its Chair Stone has a ledge cut out of its face [SUPPORTED: https://en.wikipedia.org/wiki/Wet_Withens]; The Chair Stone with its ledge looks like a seat [SUPPORTED: https://en.wikipedia.org/wiki/Wet_Withens]"}]'::jsonb),
    ('b1e4d609-9b3a-4b93-8ad0-e890a880a5dc'::uuid, 'card_description', 'The first substantial villa found south of the Purbeck Hills, Bucknowle Roman Villa began in the late 1st century AD with an aisled hall and grew to three large buildings and a bath house.', 'A Roman villa with an aisled hall and bath house, rebuilt multiple times over four centuries. A new bath complex was added in the 2nd-3rd century as the villa expanded.', 'teaser-card-s015-rollback:b1e4d609-9b3a-4b93-8ad0-e890a880a5dc:card_description', 'rollback of teaser-card-s015: card_description ''A Roman villa with an aisled hall and bath house, rebuilt multiple times over four centuries. A new bath complex was added in the 2nd-3rd century as the villa expanded.'' restored on Bucknowle Roman Villa', '1370970cd47b479ca17767cd70e71a7af26e43e3a67c4185f789495e9c7d1386|40763e5b483acba4f7716e4fe53b13faf81f79aff322ad83ff0cdc10a388bf88|40763e5b483acba4f7716e4fe53b13faf81f79aff322ad83ff0cdc10a388bf88', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The first substantial villa found south of the Purbeck Hills, Bucknowle Roman Villa began in the late 1st century AD with an aisled hall and grew to three large buildings and a bath house."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "it is the first substantial villa found south of the Purbeck Hills [S6]; the villa began in the late 1st century AD [S2]; it began with an aisled hall [S3]; it later had three large buildings [S5]; it later had a bath house [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bucknowle Roman Villa is a Roman villa in Dorset, England, south of the Purbeck Hills (central claim: what and where) [SUPPORTED: https://en.wikipedia.org/wiki/Bucknowle_Roman_villa]; It is the first substantial villa found south of the Purbeck Hills [SUPPORTED: https://en.wikipedia.org/wiki/Bucknowle_Roman_villa]; The villa began in the late 1st century AD [SUPPORTED: https://en.wikipedia.org/wiki/Bucknowle_Roman_villa]; It began with an aisled hall [SUPPORTED: https://en.wikipedia.org/wiki/Bucknowle_Roman_villa]; It grew to three large buildings and a bath house [SUPPORTED: https://en.wikipedia.org/wiki/Bucknowle_Roman_villa]"}]'::jsonb),
    ('b300f71d-88f7-4a2a-bdf0-b9bb33a53c73'::uuid, 'card_description', 'On a low hill in Dorset, a single bank rings Banbury Hill, an Iron Age hillfort entered by a passage at one point down to about 2 metres wide. Inside, there are no traces of remains.', 'Single-bank fort enclosing 1.2 hectares near Okeford Fitzpaine; the rampart reaches 15 metres wide where best preserved, though ploughing has flattened much of the site.', 'teaser-card-s015-rollback:b300f71d-88f7-4a2a-bdf0-b9bb33a53c73:card_description', 'rollback of teaser-card-s015: card_description ''Single-bank fort enclosing 1.2 hectares near Okeford Fitzpaine; the rampart reaches 15 metres wide where best preserved, though ploughing has flattened much of the site.'' restored on Banbury Hill', 'c8f6a90f09017a3f53af3c794c79bad8c02516445aa69c5057db909ef895c400|852c17e69abcdafec9a22f043cd2f5bac0984ceb22159f3e589fa903de40de62|852c17e69abcdafec9a22f043cd2f5bac0984ceb22159f3e589fa903de40de62', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a low hill in Dorset, a single bank rings Banbury Hill, an Iron Age hillfort entered by a passage at one point down to about 2 metres wide. Inside, there are no traces of remains."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies on a low hill [S2]; the site is in Dorset [S1]; a single bank rings the fort [S2]; Banbury Hill is an Iron Age hillfort [S1]; it is entered by a passage that at one point narrows to about 2 metres wide [S6]; there are no traces of remains in the interior [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Banbury Hill is an Iron Age hillfort (the kind of place the text is about). [SUPPORTED: https://en.wikipedia.org/wiki/Banbury_Hill]; Banbury Hill is in Dorset (England). [SUPPORTED: https://en.wikipedia.org/wiki/Banbury_Hill]; The hillfort stands on a low hill. [SUPPORTED: https://en.wikipedia.org/wiki/Banbury_Hill]; A single bank rings (encloses) the hill, i.e. the hillfort has a single bank as its enclosure. [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO4526]; The fort is entered by a passage that at one point narrows to about 2 metres wide. [SUPPORTED: https://en.wikipedia.org/wiki/Banbury_Hill]; Inside the fort there are no traces of remains (nothing survives in the interior). [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO4526]"}]'::jsonb),
    ('b39a1e3a-d7fa-473f-aad8-0aea535c4802'::uuid, 'card_description', 'Under Naples lie the Catacombs of Saint Gaudiosus, paleo-Christian burials of the 4th–5th century AD, where an arcosolium at the entrance guards his tomb with a sixth-century mosaic.', '4th-century AD catacombs built over an older Greco-Roman necropolis. Later artists painted portraits of the dead directly onto skulls mounted in the walls.', 'teaser-card-s015-rollback:b39a1e3a-d7fa-473f-aad8-0aea535c4802:card_description', 'rollback of teaser-card-s015: card_description ''4th-century AD catacombs built over an older Greco-Roman necropolis. Later artists painted portraits of the dead directly onto skulls mounted in the walls.'' restored on Catacombs of Saint Gaudiosus', '06991faa7e988dce42100320f7541c0b2a69fe369d7a197985e7432ae21c987b|2e980e034303dca577d2aac232807963b2661ad2db32b5caf49e63abaa27b04e|2e980e034303dca577d2aac232807963b2661ad2db32b5caf49e63abaa27b04e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Under Naples lie the Catacombs of Saint Gaudiosus, paleo-Christian burials of the 4th–5th century AD, where an arcosolium at the entrance guards his tomb with a sixth-century mosaic."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the catacombs lie under Naples [S1]; they are paleo-Christian burials [S1]; they date to the 4th-5th century AD [S1]; an arcosolium at the entrance guards the tomb of the saint [S5]; the tomb has a sixth-century mosaic decoration [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Catacombs of Saint Gaudiosus are underground burial sites (catacombs) - the kind of place the text is about. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Saint_Gaudiosus]; The catacombs lie under (in) the city of Naples. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Saint_Gaudiosus]; The burials are paleo-Christian. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Saint_Gaudiosus]; The catacombs date to the 4th-5th century AD. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Saint_Gaudiosus]; The catacombs are named for Saint Gaudiosus, whose tomb they hold (traditionally his burial site). [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Saint_Gaudiosus]; An arcosolium at the entrance guards the tomb of (Saint) Gaudiosus. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Saint_Gaudiosus]; The tomb has a sixth-century mosaic. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Saint_Gaudiosus]"}]'::jsonb),
    ('b3aacfb1-87e7-448e-b6a3-1c394670aad3'::uuid, 'card_description', 'About 40 metres above the river Poričnica, the hill fort of Pod yielded the stratified materials that defined the Central Bosnian cultural group of the late Bronze Age.', 'Hill fort at Bugojno, first inhabited 2500-1700 BC, abandoned for four centuries, then reoccupied in the Iron Age until the 3rd century BC. Its strata defined a late Bronze Age cultural group.', 'teaser-card-s015-rollback:b3aacfb1-87e7-448e-b6a3-1c394670aad3:card_description', 'rollback of teaser-card-s015: card_description ''Hill fort at Bugojno, first inhabited 2500-1700 BC, abandoned for four centuries, then reoccupied in the Iron Age until the 3rd century BC. Its strata defined a late Bronze Age cultural group.'' restored on Pod', '7349972560038ae9d4866e6d795a612e5b7bc3353018ead5183a0a6e4b389dce|1ab1928771e5fc61430859d6df789e3d03a66de6ccb091f2f7d1a932ac6cd24e|1ab1928771e5fc61430859d6df789e3d03a66de6ccb091f2f7d1a932ac6cd24e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "About 40 metres above the river Poričnica, the hill fort of Pod yielded the stratified materials that defined the Central Bosnian cultural group of the late Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is about 40 metres above the river Poričnica [S2]; Pod is a hill fort [S2]; stratified materials from Pod defined the Central Bosnian cultural group [S3]; the Central Bosnian cultural group belongs to the late Bronze Age [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Pod is a hill fort (a prehistoric settlement and hill fort) - the kind of place the text is about. [SUPPORTED: https://en.wikipedia.org/wiki/Pod,_Bosnia_and_Herzegovina]; Pod is in Bosnia and Herzegovina (municipality of Bugojno). [SUPPORTED: https://en.wikipedia.org/wiki/Pod,_Bosnia_and_Herzegovina]; Pod lies about 40 metres above the river Poričnica. [SUPPORTED: https://bug.ba/pod-kod-bugojna-prahistorijsko-arheolosko-naselje.html]; Stratified materials from Pod defined the Central Bosnian cultural group of the late Bronze Age. [SUPPORTED: https://en.wikipedia.org/wiki/Pod,_Bosnia_and_Herzegovina]"}]'::jsonb),
    ('b40d492a-193f-422b-bd42-559624dd2079'::uuid, 'card_description', 'On a hill and glade in Turku lies Virnamäki, an Iron Age monument area and dwelling site, where cremation cemeteries rest under level ground and multiple stones bear cup marks.', 'In addition to having been a dwelling site, the area is also known for its cremation cemeteries under level ground and also multiple stones with cup marks.', 'teaser-card-s015-rollback:b40d492a-193f-422b-bd42-559624dd2079:card_description', 'rollback of teaser-card-s015: card_description ''In addition to having been a dwelling site, the area is also known for its cremation cemeteries under level ground and also multiple stones with cup marks.'' restored on Virnamäki', '16d096ff653ba686fba8a2e87c5a269192129147aeca2c030a90c0dd3b8cb409|51c86a4ca860d29e5897e39dfff5f7b60b6201937f3d5063557b3e70cae2789e|51c86a4ca860d29e5897e39dfff5f7b60b6201937f3d5063557b3e70cae2789e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a hill and glade in Turku lies Virnamäki, an Iron Age monument area and dwelling site, where cremation cemeteries rest under level ground and multiple stones bear cup marks."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is a hill and glade in Turku [S1]; it is an Iron Age monument area [S1]; it was a dwelling site [S2]; cremation cemeteries lie under level ground [S2]; multiple stones bear cup marks [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Virnamäki is an ancient monument area (a hill and glade site) in Turku, Finland - the kind of place the text is about. [SUPPORTED: https://en.wikipedia.org/wiki/Virnam%C3%A4ki]; Virnamäki dates to the Iron Age. [SUPPORTED: https://en.wikipedia.org/wiki/Virnam%C3%A4ki]; Virnamäki was a dwelling site. [SUPPORTED: https://en.wikipedia.org/wiki/Virnam%C3%A4ki]; Cremation cemeteries lie under level ground at Virnamäki. [SUPPORTED: https://en.wikipedia.org/wiki/Virnam%C3%A4ki]; Multiple stones at Virnamäki bear cup marks. [SUPPORTED: https://fi.wikipedia.org/wiki/Virnam%C3%A4ki]"}]'::jsonb),
    ('b4990b79-a0d1-45e7-9d03-635362c0b2cf'::uuid, 'card_description', 'Built in the 1st century AD, the Roman Provincial Forum of Emerita Augusta was a large square with a monumental portico and a large temple at its centre, reached through the Arch of Trajan.', 'The Roman Provincial Forum is an archaeological area in Mérida built in the 1st century AD.', 'teaser-card-s015-rollback:b4990b79-a0d1-45e7-9d03-635362c0b2cf:card_description', 'rollback of teaser-card-s015: card_description ''The Roman Provincial Forum is an archaeological area in Mérida built in the 1st century AD.'' restored on Roman Provincial Forum, Mérida', '99fe12b5babbffa2a05bdaad666b7d4ad617edaaf310d313dda0d72af51640d9|abea6670ea58b860e63f1c54e3d286977341375b0761dfad64ccec1ea93a0a2e|abea6670ea58b860e63f1c54e3d286977341375b0761dfad64ccec1ea93a0a2e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Built in the 1st century AD, the Roman Provincial Forum of Emerita Augusta was a large square with a monumental portico and a large temple at its centre, reached through the Arch of Trajan."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the forum was built in the 1st century AD [S1]; it belonged to the Roman city of Emerita Augusta [S2]; it was a large square [S4]; the square had a monumental portico [S4]; a large temple stood at its centre [S4]; it was reached through the Arch of Trajan [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Provincial Forum was a public area (a forum) of the Roman city of Emerita Augusta - the kind of place the text is about. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Provincial_Forum_(M%C3%A9rida)]; The Roman Provincial Forum is in Mérida, Spain (the site of Emerita Augusta). [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Provincial_Forum_(M%C3%A9rida)]; The forum was built in the 1st century AD. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Provincial_Forum_(M%C3%A9rida)]; The forum was a large square. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Provincial_Forum_(M%C3%A9rida)]; The square was framed by a monumental portico. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Provincial_Forum_(M%C3%A9rida)]; A large temple stood at the centre of the forum. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Provincial_Forum_(M%C3%A9rida)]; The forum/temple was reached (accessed) through the Arch of Trajan. [SUPPORTED: https://emerita-lvdica.es/espacios-monumentales/arco-de-trajano/]"}]'::jsonb),
    ('b5541bbe-346c-4b3a-831c-21d6aa994adc'::uuid, 'card_description', 'Aldgate once pierced the defensive wall around the City of London. In 1377, fearing a French attack, it was fortified with portcullises and chains; its defences were tested twice.', 'A 1585 sketch of Aldgate''s north tower reveals an interior room of approximately 16 by 14 foot; its southern sibling probably had similar dimensions.', 'teaser-card-s015-rollback:b5541bbe-346c-4b3a-831c-21d6aa994adc:card_description', 'rollback of teaser-card-s015: card_description "A 1585 sketch of Aldgate''s north tower reveals an interior room of approximately 16 by 14 foot; its southern sibling probably had similar dimensions." restored on Aldgate', 'c2df52bb66b57267602b1523783bc9e055e6743745799ab369c3bd955cf71dd8|8d0f6447cf6c6c9f3a94b8f2092fc4d1139a7e26c4e6e6c71de54a89d885eaaf|8d0f6447cf6c6c9f3a94b8f2092fc4d1139a7e26c4e6e6c71de54a89d885eaaf', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aldgate once pierced the defensive wall around the City of London. In 1377, fearing a French attack, it was fortified with portcullises and chains; its defences were tested twice."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aldgate was a gate through the defensive wall around the City of London [S1]; the wall it pierced is now former (it ''once'' pierced it) [S1]; in 1377 it was fortified [S2]; it was fortified with portcullises and chains [S2]; the fortification was made in fear of a French attack [S2]; its defences were tested twice [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aldgate was a gate in the defensive wall around the City of London (central claim: a city gate) [SUPPORTED: https://en.wikipedia.org/wiki/Aldgate]; The gate stood in the City of London (London, England) [SUPPORTED: https://en.wikipedia.org/wiki/Aldgate]; In 1377 the gate was fortified [SUPPORTED: https://en.wikipedia.org/wiki/Aldgate]; The 1377 fortification was done out of fear of a French attack [SUPPORTED: https://en.wikipedia.org/wiki/Aldgate]; It was fortified with portcullises [SUPPORTED: https://en.wikipedia.org/wiki/Aldgate]; It was fortified with chains [SUPPORTED: https://en.wikipedia.org/wiki/Aldgate]; Its defences were tested twice [SUPPORTED: https://en.wikipedia.org/wiki/Aldgate]"}]'::jsonb),
    ('b587a652-f222-47e6-adc9-b6ba1fa62722'::uuid, 'card_description', 'Above the Avon Valley, on the edge of the New Forest, Frankenbury Camp encloses approximately 11 acres: an Iron Age hillfort held by steep slopes to west and south and a rampart and ditch.', 'A 4.4-hectare univallate hillfort in the New Forest with steep natural slopes on the west and south sides. Its rampart was extended to enclose a natural spring that has reportedly never run dry.', 'teaser-card-s015-rollback:b587a652-f222-47e6-adc9-b6ba1fa62722:card_description', 'rollback of teaser-card-s015: card_description ''A 4.4-hectare univallate hillfort in the New Forest with steep natural slopes on the west and south sides. Its rampart was extended to enclose a natural spring that has reportedly never run dry.'' restored on Frankenbury Camp', 'dedc504aab4d5e7929b76b9eca12123cbb7f49e3c06f225d61e49a8b879ee7cd|7535907a241a4b95d8fe50354ccbc83f506ca5c45ffae988972b10a4f22ab112|7535907a241a4b95d8fe50354ccbc83f506ca5c45ffae988972b10a4f22ab112', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the Avon Valley, on the edge of the New Forest, Frankenbury Camp encloses approximately 11 acres: an Iron Age hillfort held by steep slopes to west and south and a rampart and ditch."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies above the Avon Valley [S2]; the site is on the edge of the New Forest [S2]; Frankenbury Camp encloses approximately 11 acres [S3]; it is an Iron Age hillfort [S1]; it is defended by steep slopes to the west and south [S4]; it is defended by a rampart and ditch [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Frankenbury Camp is an Iron Age hillfort (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Frankenbury_Camp]; It lies in Hampshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Frankenbury_Camp]; It lies above the Avon Valley [SUPPORTED: https://en.wikipedia.org/wiki/Frankenbury_Camp]; It lies on the edge of the New Forest [SUPPORTED: https://en.wikipedia.org/wiki/Frankenbury_Camp]; It encloses approximately 11 acres [SUPPORTED: https://en.wikipedia.org/wiki/Frankenbury_Camp]; It is held by steep slopes to the west and south [SUPPORTED: https://en.wikipedia.org/wiki/Frankenbury_Camp]; It is defended by a rampart and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Frankenbury_Camp]"}]'::jsonb),
    ('b5e251e7-b1d1-46d4-8bba-b02956ff13c9'::uuid, 'card_description', 'Five friends slipped through a narrow sinkhole into the Caves of Nerja, whose walls bear Paleolithic paintings and where humans and cave hyenas took seasonal turns from about 25,000 BC.', 'A cave system stretching nearly 5 km, inhabited from 25,000 BC to the Bronze Age. One chamber forms a natural amphitheatre still used for concerts today.', 'teaser-card-s015-rollback:b5e251e7-b1d1-46d4-8bba-b02956ff13c9:card_description', 'rollback of teaser-card-s015: card_description ''A cave system stretching nearly 5 km, inhabited from 25,000 BC to the Bronze Age. One chamber forms a natural amphitheatre still used for concerts today.'' restored on Caves of Nerja', 'c7ca580ac7652ed417f6e8404bd324bff38c7b25c88772530c7f9b2cf0cc908b|8d241d65294abba2359e177f854b57d73ad3e6af5effe7ae7b32e934e2579357|8d241d65294abba2359e177f854b57d73ad3e6af5effe7ae7b32e934e2579357', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Five friends slipped through a narrow sinkhole into the Caves of Nerja, whose walls bear Paleolithic paintings and where humans and cave hyenas took seasonal turns from about 25,000 BC."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "five friends entered the caves [S2]; they entered through a narrow sinkhole [S2]; the cave walls bear Paleolithic paintings [S5]; humans used the caves seasonally [S6]; cave hyenas occupied the caves in turn, while the humans were absent [S6]; this seasonal alternation began about 25,000 BC [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Caves of Nerja are a cave system (central claim: caves) [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Nerja]; Five friends entered the caves [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Nerja]; They entered through a narrow sinkhole [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Nerja]; The cave walls bear Paleolithic paintings [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Nerja]; Humans used the caves seasonally [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Nerja]; Cave hyenas occupied the caves while the humans were absent [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Nerja]; The seasonal use began about 25,000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Nerja]"}]'::jsonb),
    ('b622ebae-c26d-4aef-a028-15edc1596f02'::uuid, 'card_description', 'By the lower Motagua River, Quirigua raised the tallest stele in the Maya world, among unusually large stelae carved from single blocks of red sandstone hauled from 5 kilometres away.', 'Quiriguá''s rapid expansion in the 8th century was tied to king K''ak'' Tiliw Chan Yopaat''s military victory over Copán in 738.', 'teaser-card-s015-rollback:b622ebae-c26d-4aef-a028-15edc1596f02:card_description', 'rollback of teaser-card-s015: card_description "Quiriguá''s rapid expansion in the 8th century was tied to king K''ak'' Tiliw Chan Yopaat''s military victory over Copán in 738." restored on Quirigua (Parque Arqueológico y Ruinas de Quiriguá)', 'a1805bbe9936a23f0ae6f669bf1021f6b78ca4c8e0fe3e70d85c809e11935421|64cf497872d1d7dbe0a9308af5ffc2a3cb71fe17923b0b89c0022d813f8e8af8|64cf497872d1d7dbe0a9308af5ffc2a3cb71fe17923b0b89c0022d813f8e8af8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "By the lower Motagua River, Quirigua raised the tallest stele in the Maya world, among unusually large stelae carved from single blocks of red sandstone hauled from 5 kilometres away."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies by the lower Motagua River [S2]; Quirigua raised the tallest stele in the Maya world [S5]; its stelae are unusually large [S6]; the stelae are carved from single blocks [S6]; the stone is red sandstone [S6]; the blocks were brought from quarries 5 kilometres away [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Quirigua is an ancient Maya archaeological site in Guatemala (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Quirigu%C3%A1]; It lies by the lower Motagua River [SUPPORTED: https://en.wikipedia.org/wiki/Quirigu%C3%A1]; It has the tallest stele in the Maya world [SUPPORTED: https://en.wikipedia.org/wiki/Quirigu%C3%A1]; Its stelae are unusually large [SUPPORTED: https://en.wikipedia.org/wiki/Quirigu%C3%A1]; The stelae are carved from single blocks [SUPPORTED: https://en.wikipedia.org/wiki/Quirigu%C3%A1]; The stone is red sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Quirigu%C3%A1]; The blocks were brought from quarries 5 kilometres away [SUPPORTED: https://en.wikipedia.org/wiki/Quirigu%C3%A1]"}]'::jsonb),
    ('b6945bd6-a99e-4034-b451-2f6c7faec322'::uuid, 'card_description', 'On Akeman Street, the trade route linking London to South West England, Aylesbury grew into a market town where pilgrims sought the shrine of Saint Osgyth. In 1086 it was a royal manor.', 'A 4th-century BC hillfort beneath what is now Aylesbury town centre — later fortified by Anglo-Saxons as a burh to hold off Viking raids, layering Iron Age defences with early medieval walls.', 'teaser-card-s015-rollback:b6945bd6-a99e-4034-b451-2f6c7faec322:card_description', 'rollback of teaser-card-s015: card_description ''A 4th-century BC hillfort beneath what is now Aylesbury town centre — later fortified by Anglo-Saxons as a burh to hold off Viking raids, layering Iron Age defences with early medieval walls.'' restored on Aylesbury', 'a243a1185abd3fc4bcd35f701c8bbade9e8cd4b3fe4e5d18b3877750f706d956|b5896d054ba771af6042ad7de1a98061bf1f56416456f3aab2b7a49146ceb2ff|b5896d054ba771af6042ad7de1a98061bf1f56416456f3aab2b7a49146ceb2ff', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Akeman Street, the trade route linking London to South West England, Aylesbury grew into a market town where pilgrims sought the shrine of Saint Osgyth. In 1086 it was a royal manor."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aylesbury lies on Akeman Street [S5]; Akeman Street is a trade route linking London to South West England [S5]; Aylesbury grew into a market town [S2, S4]; pilgrims came to the shrine of Saint Osgyth at Aylesbury [S2]; in 1086 the town was a royal manor [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aylesbury is a town in England (central claim: a market town in Buckinghamshire) [SUPPORTED: https://en.wikipedia.org/wiki/Aylesbury]; Aylesbury lies on Akeman Street [SUPPORTED: https://en.wikipedia.org/wiki/Akeman_Street]; Akeman Street became a trade route linking London to South West England [SUPPORTED: https://en.wikipedia.org/wiki/Aylesbury]; Aylesbury grew into a market town [SUPPORTED: https://en.wikipedia.org/wiki/Aylesbury]; Pilgrims sought the shrine of Saint Osgyth at Aylesbury [SUPPORTED: https://en.wikipedia.org/wiki/Aylesbury]; In 1086 Aylesbury was a royal manor [SUPPORTED: https://en.wikipedia.org/wiki/Aylesbury]"}]'::jsonb),
    ('b719c2bb-3424-4eab-8648-9e72bf83bdac'::uuid, 'card_description', 'On Bratton Down, the two ramparts of Bratton Castle, an Iron Age hill fort, enclose a pentagon of 9.3 hectares, dug before 1775 in what is thought one of Wiltshire''s earliest excavations.', 'Bratton Castle is a bivallate Iron Age built hill fort on Bratton Down, at the western edge of the Salisbury Plain escarpment.', 'teaser-card-s015-rollback:b719c2bb-3424-4eab-8648-9e72bf83bdac:card_description', 'rollback of teaser-card-s015: card_description ''Bratton Castle is a bivallate Iron Age built hill fort on Bratton Down, at the western edge of the Salisbury Plain escarpment.'' restored on Bratton Castle', 'cd5b388ab02453446a8e6ff978450fbc0507e5a62f407677791b44fad70d5676|85721246f3ada01c8827004b8eab52c084b1acb3aa2f76f91c3d1ee87c7d4cb6|85721246f3ada01c8827004b8eab52c084b1acb3aa2f76f91c3d1ee87c7d4cb6', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Bratton Down, the two ramparts of Bratton Castle, an Iron Age hill fort, enclose a pentagon of 9.3 hectares, dug before 1775 in what is thought one of Wiltshire''s earliest excavations."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bratton Castle is on Bratton Down [S1]; it has two ramparts [S1]; it is an Iron Age hill fort [S1]; the ramparts enclose a pentagonal area of 9.3 hectares [S2]; it was excavated before 1775 [S3]; this is thought to be one of the earliest excavations in Wiltshire [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bratton Castle is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]; Bratton Castle is of the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]; It stands on Bratton Down [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]; It is in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]; The fort has two ramparts (two circuits of ditch and bank) [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]; The ramparts enclose a pentagon (pentagonal area) [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]; The enclosed area is 9.3 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]; The hill fort was excavated before 1775 [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]; That excavation is thought to be one of the earliest archaeological excavations in Wiltshire [SUPPORTED: https://en.wikipedia.org/wiki/Bratton_Castle]"}]'::jsonb),
    ('b7f23683-db44-409d-8326-78af49f5b8a1'::uuid, 'card_description', 'On a low gravel-capped plateau east of Lockerley, the ploughed-down earthworks of Lockerley Camp, an Iron Age hillfort of approximately 5 acres, still show in a small coppice to the north.', 'Iron Age, 1st millennium BC. A univallate hillfort covering 2 hectares on a low gravel plateau in Hampshire — much reduced by ploughing, but earthworks survive in a small northern coppice.', 'teaser-card-s015-rollback:b7f23683-db44-409d-8326-78af49f5b8a1:card_description', 'rollback of teaser-card-s015: card_description ''Iron Age, 1st millennium BC. A univallate hillfort covering 2 hectares on a low gravel plateau in Hampshire — much reduced by ploughing, but earthworks survive in a small northern coppice.'' restored on Lockerley Camp', '462b5ccf8e468da5605957a8409e4e0bf890283c538c3d2a6ba9967b7308700f|b928345d12ee107da94d05196f61225872fd9f0d3258cd595af8767df3da004c|b928345d12ee107da94d05196f61225872fd9f0d3258cd595af8767df3da004c', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a low gravel-capped plateau east of Lockerley, the ploughed-down earthworks of Lockerley Camp, an Iron Age hillfort of approximately 5 acres, still show in a small coppice to the north."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site stands on a low gravel-capped plateau [S2]; it lies east of Lockerley [S3]; the earthworks are much reduced by ploughing [S2]; Lockerley Camp is an Iron Age hillfort [S1]; it covers approximately 5 acres [S2]; the earthworks still show (are more discernible) in a small coppice to the north [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Lockerley Camp is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Lockerley_Camp]; It lies east of Lockerley [SUPPORTED: https://en.wikipedia.org/wiki/Lockerley_Camp]; It sits on a low gravel-capped plateau [SUPPORTED: https://en.wikipedia.org/wiki/Lockerley_Camp]; It covers approximately 5 acres [SUPPORTED: https://en.wikipedia.org/wiki/Lockerley_Camp]; The earthworks are ploughed down [SUPPORTED: https://en.wikipedia.org/wiki/Lockerley_Camp]; The earthworks still show in a small coppice to the north [SUPPORTED: https://en.wikipedia.org/wiki/Lockerley_Camp]; Lockerley is in England [SUPPORTED: https://en.wikipedia.org/wiki/Lockerley]"}]'::jsonb),
    ('b96aa592-779d-4d93-a16f-7b09496b1139'::uuid, 'card_description', 'In Riclones, the small Cave of Chufín holds subtle engravings and schematic paintings of red deer, goats and cattle, and many symbols. Its oldest occupation level is around 20000 years old.', 'In Chufín were found different levels of occupation, the oldest being around 20000 years old.', 'teaser-card-s015-rollback:b96aa592-779d-4d93-a16f-7b09496b1139:card_description', 'rollback of teaser-card-s015: card_description ''In Chufín were found different levels of occupation, the oldest being around 20000 years old.'' restored on Cave of Chufín', 'a181a6ca3a90a00ab5bd1a2085090e1ad27432d5a7dbdc4ef197beed3997ebcb|cd675f0aad145f135a0f75dbc7dacf3ae0c52bcb875fda16923d5e90e0944192|cd675f0aad145f135a0f75dbc7dacf3ae0c52bcb875fda16923d5e90e0944192', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In Riclones, the small Cave of Chufín holds subtle engravings and schematic paintings of red deer, goats and cattle, and many symbols. Its oldest occupation level is around 20000 years old."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the cave is in Riclones [S1]; it is a small cave [S3]; it holds subtle engravings and paintings of red deer, goats and cattle [S3]; the paintings are schematic [S3]; many symbols were found in it [S4]; its oldest occupation level is around 20000 years old [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Cave of Chufín is a cave in Riclones (Cantabria, Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Chuf%C3%ADn]; The cave is small [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Chuf%C3%ADn]; The cave holds subtle engravings [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Chuf%C3%ADn]; The cave holds paintings of red deer, goats and cattle, all schematic [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Chuf%C3%ADn]; The cave holds many symbols [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Chuf%C3%ADn]; Its oldest occupation level is around 20000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Chuf%C3%ADn]"}]'::jsonb),
    ('b97f1e4c-09df-4190-aed5-22bfeb4a45cc'::uuid, 'card_description', 'Near Ballinagree in County Cork, Carrigagulla gathers a circle of 16 standing stones around a central slab, and a stone row where four of five stones have been moved and now serve as gates.', 'Carrigagulla is a megalithic complex 2.9 km north-east of Ballinagree, County Cork. Carrigagulla A is an 8-metre-diameter stone circle consisting of 16 standing stones circling a central slab.', 'teaser-card-s015-rollback:b97f1e4c-09df-4190-aed5-22bfeb4a45cc:card_description', 'rollback of teaser-card-s015: card_description ''Carrigagulla is a megalithic complex 2.9 km north-east of Ballinagree, County Cork. Carrigagulla A is an 8-metre-diameter stone circle consisting of 16 standing stones circling a central slab.'' restored on Carrigagulla', '4f68e7572a83e240a96eb18605fa1273e55381e889d1544df833ea377096d0c7|d6c826805668557e28ee2447130167be74cc2413c058b7ba489495950e695154|d6c826805668557e28ee2447130167be74cc2413c058b7ba489495950e695154', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Ballinagree in County Cork, Carrigagulla gathers a circle of 16 standing stones around a central slab, and a stone row where four of five stones have been moved and now serve as gates."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Carrigagulla is near Ballinagree [S1]; it is in County Cork [S1]; there is a circle of 16 standing stones [S2]; the circle surrounds a central slab [S2]; there is a stone row of five stones [S3]; four of the five stones have been moved [S3]; the moved stones now serve as gates [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Carrigagulla is a megalithic complex of a stone circle and stone rows [SUPPORTED: https://en.wikipedia.org/wiki/Carrigagulla]; Carrigagulla lies near Ballinagree [SUPPORTED: https://en.wikipedia.org/wiki/Carrigagulla]; Carrigagulla is in County Cork [SUPPORTED: https://en.wikipedia.org/wiki/Carrigagulla]; Carrigagulla has a stone circle of 16 standing stones [SUPPORTED: https://en.wikipedia.org/wiki/Carrigagulla]; The circle has 16 stones (independent count) [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=744]; The 16 stones surround a central slab [SUPPORTED: https://en.wikipedia.org/wiki/Carrigagulla]; There is a stone row of five stones [SUPPORTED: https://en.wikipedia.org/wiki/Carrigagulla]; Four of the five stones of the row have been moved [SUPPORTED: https://en.wikipedia.org/wiki/Carrigagulla]; The moved stones now serve as gates [SUPPORTED: https://en.wikipedia.org/wiki/Carrigagulla]"}]'::jsonb),
    ('ba0ce1ee-9848-4de1-9884-0e0bb37e2abd'::uuid, 'card_description', 'Near Niederstotzingen, a Celtic four-sided earthwork and a Roman villa rustica were found. In 1962, construction uncovered an Alamannian cemetery of nobles with their animals and valuables.', 'Mammoth ivory carvings from nearby caves date to 35,000 BC — placing this area among the earliest sites of artistic expression in Europe. The figurines were cut from mammoth tusks.', 'teaser-card-s015-rollback:ba0ce1ee-9848-4de1-9884-0e0bb37e2abd:card_description', 'rollback of teaser-card-s015: card_description ''Mammoth ivory carvings from nearby caves date to 35,000 BC — placing this area among the earliest sites of artistic expression in Europe. The figurines were cut from mammoth tusks.'' restored on Niederstotzingen', 'f0bb559a5495c7a8613693bae8deecf50075b679e89fee069442b8758221b48d|0c641e16ba6587edfe65de7ef45cf780f7af84bf1c033ff9f85b32711d6e523c|0c641e16ba6587edfe65de7ef45cf780f7af84bf1c033ff9f85b32711d6e523c', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Niederstotzingen, a Celtic four-sided earthwork and a Roman villa rustica were found. In 1962, construction uncovered an Alamannian cemetery of nobles with their animals and valuables."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "a Celtic four-sided earthwork was found near Niederstotzingen [S2]; a Roman villa rustica was found near Niederstotzingen [S3]; in 1962 construction uncovered a cemetery [S4]; the cemetery is Alamannian [S5]; the cemetery held nobles with their animals and valuables [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Niederstotzingen is a small city in the district of Heidenheim in southern Germany, near which the finds lie (the place the text is about) [SUPPORTED: https://en.wikipedia.org/wiki/Niederstotzingen]; A Celtic four-sided earthwork (Viereckschanze) was found near Niederstotzingen [SUPPORTED: https://en.wikipedia.org/wiki/Niederstotzingen]; A Roman villa rustica was found near Niederstotzingen [SUPPORTED: https://en.wikipedia.org/wiki/Niederstotzingen]; In 1962, during construction, a cemetery was uncovered at Niederstotzingen [SUPPORTED: https://en.wikipedia.org/wiki/Niederstotzingen]; The cemetery is Alamannian and held nobles with their animals and valuables [SUPPORTED: https://en.wikipedia.org/wiki/Niederstotzingen]"}]'::jsonb),
    ('ba1d0bf4-260a-467e-adaa-2a53d13745aa'::uuid, 'card_description', 'Near the temple of Apollo at Delphi lay the Halos, a round open space whose name means threshing floor, where once every eight years the Septerion re-enacted Apollo''s killing of Python.', '4th-century BC circular ritual space near Apollo''s temple at Delphi, where ceremonies re-enacted the killing of the Python — the mythological shift from chthonic to Olympian religion.', 'teaser-card-s015-rollback:ba1d0bf4-260a-467e-adaa-2a53d13745aa:card_description', 'rollback of teaser-card-s015: card_description "4th-century BC circular ritual space near Apollo''s temple at Delphi, where ceremonies re-enacted the killing of the Python — the mythological shift from chthonic to Olympian religion." restored on Halos, Delphi', '2bd4093ddd824b94d29f0ea5e2b7e1695a809e37a0db4b11fb84911706d3aef4|776424c560de570257fd9dd4106d45e67d67c3622ef8e512384d4d180bc0c6a7|776424c560de570257fd9dd4106d45e67d67c3622ef8e512384d4d180bc0c6a7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near the temple of Apollo at Delphi lay the Halos, a round open space whose name means threshing floor, where once every eight years the Septerion re-enacted Apollo''s killing of Python."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Halos lay near the temple of Apollo at Delphi [S1]; it was a round open space [S1, S3]; the name Halos means threshing floor [S3]; the Septerion was held there once every eight years [S3, S4]; the Septerion re-enacted Apollo''s killing of Python [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Halos was a round open space close to the temple of Apollo at Delphi (central claim: what and where the site is). [SUPPORTED: https://en.wikipedia.org/wiki/Halos_(Delphi)]; The Halos was a place where ancient rituals were performed. [SUPPORTED: https://en.wikipedia.org/wiki/Halos_(Delphi)]; The name Halos means threshing floor. [SUPPORTED: https://en.wikipedia.org/wiki/Halos_(Delphi)]; The Septerion was one of the rituals held at the Halos. [SUPPORTED: https://en.wikipedia.org/wiki/Halos_(Delphi)]; The Septerion re-enacted Apollo''s killing of Python. [SUPPORTED: https://en.wikipedia.org/wiki/Halos_(Delphi)]; The Septerion took place once every eight years. [SUPPORTED: https://en.wikipedia.org/wiki/Halos_(Delphi)]"}]'::jsonb),
    ('ba33abc5-f266-4b9c-85f1-cd691699b271'::uuid, 'card_description', 'Near Aylesford in Kent, three stones still carry the capstone of Kit''s Coty House, a long barrow built circa 4000 BCE, its mound largely ploughed flat yet visible from aerial photographs.', 'A Neolithic chambered long barrow from around 4000 BC. Three uprights support a capstone in an H-shaped formation -- hallmark of the Medway Megaliths.', 'teaser-card-s015-rollback:ba33abc5-f266-4b9c-85f1-cd691699b271:card_description', 'rollback of teaser-card-s015: card_description ''A Neolithic chambered long barrow from around 4000 BC. Three uprights support a capstone in an H-shaped formation -- hallmark of the Medway Megaliths.'' restored on Kit''s Coty House', '25bbde481e7fd616b3ed84be149fa79c91695ff025c73384e7796f5cd78a748a|1b29dca10e81a8324d5f3f71009c8b7b3b6e12536f127c995ca6d659310b480e|1b29dca10e81a8324d5f3f71009c8b7b3b6e12536f127c995ca6d659310b480e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Aylesford in Kent, three stones still carry the capstone of Kit''s Coty House, a long barrow built circa 4000 BCE, its mound largely ploughed flat yet visible from aerial photographs."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is near Aylesford in Kent [S1]; Kit''s Coty House is a long barrow [S1]; it was built circa 4000 BCE [S2]; three stones still stand carrying a capstone [S6]; the mound has largely been ploughed flat [S7]; the mound is still visible from aerial photographs [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kit''s Coty House is a chambered long barrow (central claim: what kind of place the site is). [SUPPORTED: https://en.wikipedia.org/wiki/Kit%27s_Coty_House]; It lies near Aylesford in the county of Kent, England. [SUPPORTED: https://en.wikipedia.org/wiki/Kit%27s_Coty_House]; Three stones still carry the capstone of Kit''s Coty House. [SUPPORTED: https://en.wikipedia.org/wiki/Kit%27s_Coty_House]; The long barrow was built circa 4000 BCE. [SUPPORTED: https://en.wikipedia.org/wiki/Kit%27s_Coty_House]; The mound has largely been ploughed flat. [SUPPORTED: https://en.wikipedia.org/wiki/Kit%27s_Coty_House]; The ploughed-flat mound remains visible from aerial photographs. [SUPPORTED: https://en.wikipedia.org/wiki/Kit%27s_Coty_House]"}]'::jsonb),
    ('baf89ae1-61ca-47d4-a5ee-9e4a02362803'::uuid, 'card_description', 'West of Apollo''s sacred precinct at Delphi, the Portico of the Aetolians runs 72.60 metres behind a double colonnade, 29 columns outside and 15 within, one of Delphi''s largest buildings.', 'A 72.6-metre portico with a double colonnade of 29 exterior and 15 interior columns. It was associated with the Aetolian League during their control of Delphi in the 3rd century BC.', 'teaser-card-s015-rollback:baf89ae1-61ca-47d4-a5ee-9e4a02362803:card_description', 'rollback of teaser-card-s015: card_description ''A 72.6-metre portico with a double colonnade of 29 exterior and 15 interior columns. It was associated with the Aetolian League during their control of Delphi in the 3rd century BC.'' restored on Portico of the Aetolians', '1d0f57b3c52b624ae325cee5b187b9a79a220cc54590739a25b62e3622cf8812|5703b22db0856efe45040a83bcf6ee6b9c6f018aebd67f8329c9e918fec04e55|5703b22db0856efe45040a83bcf6ee6b9c6f018aebd67f8329c9e918fec04e55', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "West of Apollo''s sacred precinct at Delphi, the Portico of the Aetolians runs 72.60 metres behind a double colonnade, 29 columns outside and 15 within, one of Delphi''s largest buildings."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Portico of the Aetolians lies west of Apollo''s sacred precinct at Delphi [S1, S2]; it is 72.60 metres long [S3]; it has a double colonnade [S4]; the exterior colonnade has 29 columns [S4]; the interior colonnade has 15 columns [S4]; it is one of Delphi''s largest buildings [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Portico of the Aetolians is a large portico (stoa) at Delphi (central claim: what and where the site is). [SUPPORTED: https://en.wikipedia.org/wiki/Portico_of_the_Aetolians]; It lies west of Apollo''s sacred precinct at Delphi. [SUPPORTED: https://en.wikipedia.org/wiki/Portico_of_the_Aetolians]; The portico measures 72.60 metres in length. [SUPPORTED: https://en.wikipedia.org/wiki/Portico_of_the_Aetolians]; The portico had a double colonnade. [SUPPORTED: https://en.wikipedia.org/wiki/Portico_of_the_Aetolians]; The outer colonnade had 29 columns. [SUPPORTED: https://en.wikipedia.org/wiki/Portico_of_the_Aetolians]; The inner colonnade had 15 columns. [SUPPORTED: https://en.wikipedia.org/wiki/Portico_of_the_Aetolians]; The portico is one of Delphi''s largest buildings. [SUPPORTED: https://en.wikipedia.org/wiki/Portico_of_the_Aetolians]"}]'::jsonb),
    ('bc4228ff-3afd-4efa-a458-65d0636135df'::uuid, 'card_description', 'Among the oldest structures in Scotland, the Grey Cairns of Camster date to around 3,000 BC: a horned long cairn 60 m long and a round one, each hiding burial chambers down narrow passages.', 'Two Neolithic chambered cairns about 5,000 years old — among the oldest standing structures in the Highlands. Narrow passages lead to central burial chambers.', 'teaser-card-s015-rollback:bc4228ff-3afd-4efa-a458-65d0636135df:card_description', 'rollback of teaser-card-s015: card_description ''Two Neolithic chambered cairns about 5,000 years old — among the oldest standing structures in the Highlands. Narrow passages lead to central burial chambers.'' restored on Grey Cairns of Camster', 'dd2b402f9f037af3c39c93b316eac89ec316244774c431e3a773acb17a31413c|31d1546392a8a5fa76f2ed128ba8db3958959449d57cc3435d40a552c3559871|31d1546392a8a5fa76f2ed128ba8db3958959449d57cc3435d40a552c3559871', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Among the oldest structures in Scotland, the Grey Cairns of Camster date to around 3,000 BC: a horned long cairn 60 m long and a round one, each hiding burial chambers down narrow passages."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Grey Cairns of Camster are among the oldest structures in Scotland [S2]; they date to around 3,000 BC [S2]; one cairn is a long cairn with horns, 60 m long [S4]; the other cairn is round [S5]; each cairn has burial chambers reached by narrow passages [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Grey Cairns of Camster are two large Neolithic chambered cairns in Caithness, Scotland (central claim: what and where the site is). [SUPPORTED: https://en.wikipedia.org/wiki/Grey_Cairns_of_Camster]; They are among the oldest structures in Scotland. [SUPPORTED: https://en.wikipedia.org/wiki/Grey_Cairns_of_Camster]; They date to around 3,000 BC. [SUPPORTED: https://en.wikipedia.org/wiki/Grey_Cairns_of_Camster]; One of the two cairns is a horned long cairn 60 m long (Camster Long). [SUPPORTED: https://en.wikipedia.org/wiki/Grey_Cairns_of_Camster]; The other cairn is a round one (Camster Round). [SUPPORTED: https://en.wikipedia.org/wiki/Grey_Cairns_of_Camster]; The cairns hide burial chambers reached down narrow passages. [SUPPORTED: https://en.wikipedia.org/wiki/Grey_Cairns_of_Camster]"}]'::jsonb),
    ('bc55dd6f-a972-4caa-af6a-e4e96f65d0f5'::uuid, 'card_description', 'Opened in 1837, the Rillaton Barrow on Bodmin Moor hid a burial in a stone cist, laid with a bronze dagger, beads and a gold cup around 9 cm high, its handle fixed with rivets.', 'Rillaton Barrow was excavated in 1837 and found to contain a centrally-placed inhumation beneath the 34-metre wide barrow.', 'teaser-card-s015-rollback:bc55dd6f-a972-4caa-af6a-e4e96f65d0f5:card_description', 'rollback of teaser-card-s015: card_description ''Rillaton Barrow was excavated in 1837 and found to contain a centrally-placed inhumation beneath the 34-metre wide barrow.'' restored on Rillaton Barrow', '554c51825e9f50494f9a46df33fb05511fea622ddf9af41def70fea550761bdb|aaad566e3d8d57c521b27b3cb618501b5b009f141ec64295757ecbea337a36c7|aaad566e3d8d57c521b27b3cb618501b5b009f141ec64295757ecbea337a36c7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Opened in 1837, the Rillaton Barrow on Bodmin Moor hid a burial in a stone cist, laid with a bronze dagger, beads and a gold cup around 9 cm high, its handle fixed with rivets."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the barrow was opened (excavated) in 1837 [S3]; the Rillaton Barrow is on Bodmin Moor [S2]; it held a burial in a stone cist [S3, S4]; the burial was accompanied by a bronze dagger [S5]; the burial was accompanied by beads [S5]; it contained a gold cup [S5, S6]; the cup is around 9 cm high [S6]; the cup''s handle is attached with rivets [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Rillaton Barrow is a Bronze Age round barrow (burial mound) (central claim: what kind of place the site is). [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]; The barrow is on Bodmin Moor. [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]; The barrow was opened (excavated) in 1837. [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]; It contained a burial placed in a stone cist. [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]; The grave goods included a bronze dagger. [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]; The grave goods included beads. [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]; The burial contained a gold cup (the Rillaton Gold Cup). [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]; The gold cup is around 9 cm high. [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]; The cup''s handle is attached with rivets. [SUPPORTED: https://en.wikipedia.org/wiki/Rillaton_Barrow]"}]'::jsonb),
    ('bdba33af-64d6-4a74-90f3-4ecf9e512c83'::uuid, 'card_description', 'In the upper reaches of Gleann Beag stands Dun Grugaig, a D-shaped fort of a type commonly regarded as a prototype broch, sharing its valley with the brochs of Dun Telve and Dun Troddan.', 'A D-shaped semi-broch sharing a valley with two full brochs, Dun Telve and Dun Troddan. Its half-circular design suggests a transitional building form between duns and brochs.', 'teaser-card-s015-rollback:bdba33af-64d6-4a74-90f3-4ecf9e512c83:card_description', 'rollback of teaser-card-s015: card_description ''A D-shaped semi-broch sharing a valley with two full brochs, Dun Telve and Dun Troddan. Its half-circular design suggests a transitional building form between duns and brochs.'' restored on Dun Grugaig', '8fc6403cedecc5854f58fa0f6397a7fc57e3aa3cc7023eba81c6336a5aa72f4e|4fcd60d3672f9807383cf9a76243d8179a2fe0d1f90faab2bc71bca96f9c2fd6|4fcd60d3672f9807383cf9a76243d8179a2fe0d1f90faab2bc71bca96f9c2fd6', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the upper reaches of Gleann Beag stands Dun Grugaig, a D-shaped fort of a type commonly regarded as a prototype broch, sharing its valley with the brochs of Dun Telve and Dun Troddan."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dun Grugaig stands in the upper reaches of Gleann Beag [S2]; Dun Grugaig is a D-shaped fort [S1, S4]; it is of a type commonly regarded as a prototype broch [S4]; it shares its valley with the brochs of Dun Telve and Dun Troddan [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dun Grugaig is a D-shaped fort (a dun) in Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Grugaig]; Dun Grugaig is of a type commonly regarded as a prototype broch [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Grugaig]; Dun Grugaig stands in the upper reaches of Gleann Beag [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Grugaig]; Dun Grugaig shares its valley with the brochs of Dun Telve and Dun Troddan [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Grugaig]"}]'::jsonb),
    ('bdd92d68-2715-4dfe-a956-e2f3a5b77465'::uuid, 'card_description', 'Amid farming terraces in northwest Belize lies La Milpa, a Maya city whose Main Plaza alone covers 18,000 square meters. In the mid-8th century, its monuments and stelae multiplied.', 'Third-largest Maya site in the Three River region, La Milpa was active 400 BC-850 AD. Pyramid-centred and positioned where two major borders converge, it was a key hub in the regional trade network.', 'teaser-card-s015-rollback:bdd92d68-2715-4dfe-a956-e2f3a5b77465:card_description', 'rollback of teaser-card-s015: card_description ''Third-largest Maya site in the Three River region, La Milpa was active 400 BC-850 AD. Pyramid-centred and positioned where two major borders converge, it was a key hub in the regional trade network.'' restored on La Milpa', '0206b6a5981e2dae6ff47c1b0628097da8f2f326ed44d2f31105d28071a3191a|b0f6a433c1ec3c6973e38b50d08ad4fca838e86cadb570134d575985d178ae3d|b0f6a433c1ec3c6973e38b50d08ad4fca838e86cadb570134d575985d178ae3d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Amid farming terraces in northwest Belize lies La Milpa, a Maya city whose Main Plaza alone covers 18,000 square meters. In the mid-8th century, its monuments and stelae multiplied."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "La Milpa lies in northwest Belize [S1]; La Milpa is a Maya city [S1]; the site has farming terraces around it (extensive terraces indicating intensive agriculture) [S6]; the Main Plaza alone covers 18,000 square meters [S3]; in the mid-8th century construction of monumental architecture and dedication of stelae rose steeply (monuments and stelae multiplied) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "La Milpa is an ancient Maya city [SUPPORTED: https://en.wikipedia.org/wiki/La_Milpa]; La Milpa lies in northwest Belize [SUPPORTED: https://en.wikipedia.org/wiki/La_Milpa]; La Milpa lay amid farming terraces (intensive agriculture shown by extensive terraces) [SUPPORTED: https://en.wikipedia.org/wiki/La_Milpa]; La Milpa''s Main Plaza alone covers 18,000 square meters [SUPPORTED: https://en.wikipedia.org/wiki/La_Milpa]; In the mid-8th century La Milpa''s monuments and stelae multiplied [SUPPORTED: https://en.wikipedia.org/wiki/La_Milpa]"}]'::jsonb),
    ('be53cb70-c063-415a-a127-4997d12c405e'::uuid, 'card_description', 'First seen in aerial photos in 1930, Nakbe is one of the largest early Maya sites, linked by a causeway to El Mirador, its limestone quarries a key to building large temples.', 'Settled by 1400 BC in the Mirador Basin, Nakbe predates most Maya cities. Structure 1, its largest pyramid, towers over 45 metres — built before the Classic period even began.', 'teaser-card-s015-rollback:be53cb70-c063-415a-a127-4997d12c405e:card_description', 'rollback of teaser-card-s015: card_description ''Settled by 1400 BC in the Mirador Basin, Nakbe predates most Maya cities. Structure 1, its largest pyramid, towers over 45 metres — built before the Classic period even began.'' restored on Nakbe', '5ab8ab63386876aefb8470305a9d0dc7e73e9f5f620896c9d28bb49c5cab0697|3b87ba80bc24ecc7fe55f039a52654b15fed46aad26e0a915ed661bc35b1f6cc|3b87ba80bc24ecc7fe55f039a52654b15fed46aad26e0a915ed661bc35b1f6cc', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "First seen in aerial photos in 1930, Nakbe is one of the largest early Maya sites, linked by a causeway to El Mirador, its limestone quarries a key to building large temples."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Nakbe was first seen (discovered) in aerial photos in 1930 [S3]; Nakbe is one of the largest early Maya sites [S1]; Nakbe was linked by a causeway to El Mirador [S8]; its limestone quarries were a key to building large temples [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Nakbe is an early Maya archaeological site in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Nakbe]; Nakbe is one of the largest early Maya sites [SUPPORTED: https://en.wikipedia.org/wiki/Nakbe]; Nakbe was first seen in aerial photos in 1930 [SUPPORTED: https://en.wikipedia.org/wiki/Nakbe]; A causeway links Nakbe to El Mirador [SUPPORTED: https://en.wikipedia.org/wiki/Nakbe]; Nakbe''s limestone quarries were a key to building large temples [SUPPORTED: https://en.wikipedia.org/wiki/Nakbe]"}]'::jsonb),
    ('bf30fac5-d015-46c4-b340-74e5614ce274'::uuid, 'card_description', 'Beside a pyramid-hill in Veracruz, El Azuzul kept two pairs of Olmec sculptures intact and apparently undisturbed since Pre-Classic times, among them two nearly identical seated figures.', 'An Olmec site from 1100–800 BC famous for two pairs of monumental sculptures found intact and undisturbed. Twin figures sit between crouching jaguars.', 'teaser-card-s015-rollback:bf30fac5-d015-46c4-b340-74e5614ce274:card_description', 'rollback of teaser-card-s015: card_description ''An Olmec site from 1100–800 BC famous for two pairs of monumental sculptures found intact and undisturbed. Twin figures sit between crouching jaguars.'' restored on El Azuzul', '22edb3111a33e4b353993e5ef165709bc1ed880a640e5341d84240e7f509a322|6ff234fcc2acd02752d18bae53f0797d666799c5c98412e545d45f5819ea3063|6ff234fcc2acd02752d18bae53f0797d666799c5c98412e545d45f5819ea3063', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Beside a pyramid-hill in Veracruz, El Azuzul kept two pairs of Olmec sculptures intact and apparently undisturbed since Pre-Classic times, among them two nearly identical seated figures."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "El Azuzul is beside a large pyramid-hill (the statues were found on its south side) [S6]; El Azuzul is in Veracruz [S1]; El Azuzul is Olmec [S1]; the site had two pairs of monumental sculptures [S5]; the sculptures were found intact and apparently undisturbed since Pre-Classic times [S6]; among the sculptures are two nearly identical seated figures [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "El Azuzul is an Olmec archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/El_Azuzul]; El Azuzul is in Veracruz (Mexico) [SUPPORTED: https://en.wikipedia.org/wiki/El_Azuzul]; El Azuzul lies beside a large pyramid-hill, on whose south side the sculptures were found [SUPPORTED: https://en.wikipedia.org/wiki/El_Azuzul]; El Azuzul has two pairs of Olmec (monumental) sculptures [SUPPORTED: https://en.wikipedia.org/wiki/El_Azuzul]; The sculptures were found intact [SUPPORTED: https://en.wikipedia.org/wiki/El_Azuzul]; The sculptures were apparently undisturbed since Pre-Classic times [SUPPORTED: https://en.wikipedia.org/wiki/El_Azuzul]; Among the sculptures are two nearly identical seated figures [SUPPORTED: https://en.wikipedia.org/wiki/El_Azuzul]"}]'::jsonb),
    ('bf538bd9-912c-471a-964a-f94842e17491'::uuid, 'card_description', 'At Cyrene rose the Temple of Zeus, one of the largest Greek temples ever built, ringed by fluted columns. Damaged in 115 AD and partly rebuilt, it fell to an earthquake in 365 AD.', 'The original Doric octastyle peripteral temple was constructed around 500–480 BC, and heavily damaged in 115 AD.', 'teaser-card-s015-rollback:bf538bd9-912c-471a-964a-f94842e17491:card_description', 'rollback of teaser-card-s015: card_description ''The original Doric octastyle peripteral temple was constructed around 500–480 BC, and heavily damaged in 115 AD.'' restored on Temple of Zeus', '1e8a802df3eb6d8c8542507be33e9e7be35cc86b4115b40fa7602b0a08810bb4|d060f6af3212be2b9b938335836cff77eeedc5694be453b43bfc05683539163d|d060f6af3212be2b9b938335836cff77eeedc5694be453b43bfc05683539163d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At Cyrene rose the Temple of Zeus, one of the largest Greek temples ever built, ringed by fluted columns. Damaged in 115 AD and partly rebuilt, it fell to an earthquake in 365 AD."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Temple of Zeus is at Cyrene [S1]; it is one of the largest Greek temples ever built [S1]; it is ringed by fluted columns (external colonnade of fluted columns, peripteral) [S2, S5]; it was damaged in 115 AD [S2]; it was partly rebuilt [S3]; it fell to an earthquake in 365 AD [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Temple of Zeus stood at Cyrene, Libya [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus,_Cyrene]; The temple is one of the largest Greek temples ever built [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus,_Cyrene]; The temple was ringed by fluted columns [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus,_Cyrene]; The temple was damaged in 115 AD [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus,_Cyrene]; The temple was partly rebuilt after the damage [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus,_Cyrene]; The temple fell to an earthquake in 365 AD [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Zeus,_Cyrene]"}]'::jsonb),
    ('c078b659-9020-4254-84f5-bd19690dea97'::uuid, 'card_description', 'On a knoll near where the Rivers Eamont and Lowther meet, the circular bank of Mayburgh Henge, up to 15 feet high and possibly of river cobbles, encloses a single monolith 9 feet high.', 'A henge built from river cobbles rather than dug earth — unique among all known henge monuments. A single massive standing stone remains inside, where once there were several.', 'teaser-card-s015-rollback:c078b659-9020-4254-84f5-bd19690dea97:card_description', 'rollback of teaser-card-s015: card_description ''A henge built from river cobbles rather than dug earth — unique among all known henge monuments. A single massive standing stone remains inside, where once there were several.'' restored on Mayburgh Henge', '6d2de194fc084c7b93c3e3a1b6c33871956f06ed68723c8004809dd32e8099a2|b97284805cf86ee5e0631a1d87eae4fa72b8088324be653dd89e2879ae283e73|b97284805cf86ee5e0631a1d87eae4fa72b8088324be653dd89e2879ae283e73', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a knoll near where the Rivers Eamont and Lowther meet, the circular bank of Mayburgh Henge, up to 15 feet high and possibly of river cobbles, encloses a single monolith 9 feet high."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Mayburgh Henge is on a knoll [S4]; it is near the confluence of the Rivers Eamont and Lowther [S4]; it has a circular bank [S5]; the bank is up to 15 feet high [S6]; the bank is possibly built of river cobbles [S5]; it encloses a single monolith 9 feet high [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Mayburgh Henge is a henge, a large prehistoric monument, in England (Cumbria) [SUPPORTED: https://en.wikipedia.org/wiki/Mayburgh_Henge]; It stands on a knoll near where the Rivers Eamont and Lowther meet [SUPPORTED: https://en.wikipedia.org/wiki/Mayburgh_Henge]; The henge is a circular bank [SUPPORTED: https://en.wikipedia.org/wiki/Mayburgh_Henge]; The bank is possibly made of river cobbles [SUPPORTED: https://en.wikipedia.org/wiki/Mayburgh_Henge]; The bank is up to 15 feet high [SUPPORTED: https://en.wikipedia.org/wiki/Mayburgh_Henge]; The bank encloses a single monolith 9 feet high [SUPPORTED: https://en.wikipedia.org/wiki/Mayburgh_Henge]"}]'::jsonb),
    ('c0d65355-96d2-407f-bda3-b4e63897266d'::uuid, 'card_description', 'Found in 1973 as irrigation water ate into it, Bandurria was an early coastal fishing settlement with a sunken circular plaza and the first evidence of ceremonial stone architecture.', 'Settled by 4000 BC on a coastal river plain, Bandurria combined a fishing economy with monumental stone terraces — the first ceremonial architecture yet found in the Americas.', 'teaser-card-s015-rollback:c0d65355-96d2-407f-bda3-b4e63897266d:card_description', 'rollback of teaser-card-s015: card_description ''Settled by 4000 BC on a coastal river plain, Bandurria combined a fishing economy with monumental stone terraces — the first ceremonial architecture yet found in the Americas.'' restored on Bandurria, Peru', '6cd30440c2fd58a262b22f7b34ec896c0de2a752080b985d0cf1233f71ce4a33|6daaf1a831bdc580c1dbe5d568eff640b3daf86395e11cd4e5b35081767776b7|6daaf1a831bdc580c1dbe5d568eff640b3daf86395e11cd4e5b35081767776b7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Found in 1973 as irrigation water ate into it, Bandurria was an early coastal fishing settlement with a sunken circular plaza and the first evidence of ceremonial stone architecture."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bandurria was found (discovered) in 1973 [S2, S3]; irrigation water infiltration ate into (destroyed part of) the site when the irrigation project started [S2]; Bandurria was an early coastal fishing settlement [S7]; it has a sunken circular plaza [S8]; it has the first evidence of ceremonial stone architecture [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bandurria is an archaeological settlement site in Peru, an early coastal fishing settlement [SUPPORTED: https://en.wikipedia.org/wiki/Bandurria,_Peru]; Bandurria was found (discovered) in 1973 [SUPPORTED: https://en.wikipedia.org/wiki/Bandurria,_Peru]; It was found as irrigation water ate into it (water infiltration from the irrigation project destroyed part of the site when it was discovered) [SUPPORTED: https://en.wikipedia.org/wiki/Bandurria,_Peru]; The site has a sunken circular plaza [SUPPORTED: https://en.wikipedia.org/wiki/Bandurria,_Peru]; It gave the first evidence of ceremonial stone architecture [SUPPORTED: https://en.wikipedia.org/wiki/Bandurria,_Peru]"}]'::jsonb),
    ('c17fcb7a-b41f-406c-9799-e42fa9443371'::uuid, 'card_description', 'On high land above the cliff over Manorbier bay, King''s Quoit rests a capstone 4 metres by 2.5 metres on two upright stones and the rising ground, its Neolithic chamber partly below ground.', 'A Neolithic burial chamber with a 4-metre capstone on two upright stones at a cliff edge. A third upright has fallen over the millennia.', 'teaser-card-s015-rollback:c17fcb7a-b41f-406c-9799-e42fa9443371:card_description', 'rollback of teaser-card-s015: card_description ''A Neolithic burial chamber with a 4-metre capstone on two upright stones at a cliff edge. A third upright has fallen over the millennia.'' restored on King''s Quoit', '5572922615ae76d575e7f1ded8351c8cd94eb9d369599ed25c9f14812ec46d91|11840613111511209993f5d77c971f2cf50efbaaf797d6910e5926615c659b1d|11840613111511209993f5d77c971f2cf50efbaaf797d6910e5926615c659b1d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On high land above the cliff over Manorbier bay, King''s Quoit rests a capstone 4 metres by 2.5 metres on two upright stones and the rising ground, its Neolithic chamber partly below ground."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "King''s Quoit is on high land above the cliff over Manorbier bay [S4]; its capstone measures 4 metres by 2.5 metres [S5]; the capstone rests on two upright stones and the rising ground [S5]; the chamber is Neolithic [S1]; the chamber is partly below ground [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "King''s Quoit is a Neolithic burial chamber (chambered tomb) at Manorbier, Wales [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Quoit]; It stands on high land above the cliff over Manorbier bay [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Quoit]; The capstone measures 4 metres by 2.5 metres [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Quoit]; The capstone rests on two upright stones and the rising ground [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Quoit]; The chamber is partly below ground [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Quoit]; The chamber is Neolithic in date [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Quoit]"}]'::jsonb),
    ('c22fa6c5-6691-4f76-a6fe-83ee0b7e0dbf'::uuid, 'card_description', 'Near Penzance, Boskednan Stone Circle, the Nine Maidens, may once have held as many as 22 stones. Ten survive, and nearby lay a cist and a funerary urn from the early Bronze Age.', 'Stone circles such as that at Boskednan, were erected in the late Neolithic or in the early Bronze Age by representatives of a Megalithic culture.', 'teaser-card-s015-rollback:c22fa6c5-6691-4f76-a6fe-83ee0b7e0dbf:card_description', 'rollback of teaser-card-s015: card_description ''Stone circles such as that at Boskednan, were erected in the late Neolithic or in the early Bronze Age by representatives of a Megalithic culture.'' restored on Boskednan Stone Circle', '1097f771b4946fb2dd4a361a836de2b1f4482447e0acb9552f71b5b5295c172b|6ff6074ce18dcb3ec08f44827b1b8e37ad190218a4d38e0332b4cfdfe373749a|6ff6074ce18dcb3ec08f44827b1b8e37ad190218a4d38e0332b4cfdfe373749a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Penzance, Boskednan Stone Circle, the Nine Maidens, may once have held as many as 22 stones. Ten survive, and nearby lay a cist and a funerary urn from the early Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Boskednan Stone Circle is near Penzance [S1]; it is known as the Nine Maidens [S2]; it may once have held as many as 22 stones (hedged) [S2, S4]; ten stones survive [S5]; a cist and a funerary urn lay near the circle [S8]; the cist and urn date from the early Bronze Age [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Boskednan Stone Circle is a prehistoric stone circle in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Boskednan_stone_circle]; It lies near Penzance [SUPPORTED: https://en.wikipedia.org/wiki/Boskednan_stone_circle]; It is known as the Nine Maidens [SUPPORTED: https://en.wikipedia.org/wiki/Boskednan_stone_circle]; The circle may once have held as many as 22 stones [SUPPORTED: https://en.wikipedia.org/wiki/Boskednan_stone_circle]; Ten stones survive [SUPPORTED: https://en.wikipedia.org/wiki/Boskednan_stone_circle]; A cist and a funerary urn were found near the circle [SUPPORTED: https://en.wikipedia.org/wiki/Boskednan_stone_circle]; The cist and urn date from the early Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Boskednan_stone_circle]"}]'::jsonb),
    ('c30712db-a675-4203-a442-cb3f9b1c5848'::uuid, 'card_description', 'At 2100 m above sea level, near a pass south of the Caucasus range, Tsona Cave is one of the highest archaeological cave sites in Georgia, where Lower and Middle Paleolithic remains lay.', 'Tsona Cave was discovered by A. Kalandadze in 1958. Excavations at the site revealed Lower and Middle Paleolithic archaeological remains.', 'teaser-card-s015-rollback:c30712db-a675-4203-a442-cb3f9b1c5848:card_description', 'rollback of teaser-card-s015: card_description ''Tsona Cave was discovered by A. Kalandadze in 1958. Excavations at the site revealed Lower and Middle Paleolithic archaeological remains.'' restored on Tsona Cave', 'b3c781ca5707d2c60b9c82752bdf3ecb0e4669daf4fece509a9f83dc812e3c26|cbc1225f5d27fe88172762792068ee0e61857217cabad40164a3a094a3fa1b65|cbc1225f5d27fe88172762792068ee0e61857217cabad40164a3a094a3fa1b65', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At 2100 m above sea level, near a pass south of the Caucasus range, Tsona Cave is one of the highest archaeological cave sites in Georgia, where Lower and Middle Paleolithic remains lay."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Tsona Cave lies at 2100 m above sea level [S5]; it is near a pass south of the Caucasus range [S2]; it is one of the highest archaeological cave sites in Georgia [S1, S5]; Lower and Middle Paleolithic remains were found there [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Tsona Cave is an archaeological cave site in Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Tsona_Cave]; The cave is in the country of Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Tsona_Cave]; The cave lies at 2100 m above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Tsona_Cave]; It is near a pass south of the Caucasus range [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Tsona_Cave]; It is one of the highest archaeological cave sites in Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Tsona_Cave]; Lower and Middle Paleolithic remains were found there [SUPPORTED: https://en.wikipedia.org/wiki/Tsona_Cave]"}]'::jsonb),
    ('c3517388-2457-42fd-9cf8-f6a043021b1e'::uuid, 'card_description', 'Petrovaradin''s region fell to Celts in the 4th century BC and to Romans in the 1st century BC. Under Roman administration a fortress named Cusum rose here, part of Roman Pannonia.', 'Founded by Celts, ruled by Rome, then home to Scordisci warriors. The Petrovaradin Fortress, built over these layers, became the historical anchor of a modern city.', 'teaser-card-s015-rollback:c3517388-2457-42fd-9cf8-f6a043021b1e:card_description', 'rollback of teaser-card-s015: card_description ''Founded by Celts, ruled by Rome, then home to Scordisci warriors. The Petrovaradin Fortress, built over these layers, became the historical anchor of a modern city.'' restored on Petrovaradin', 'db2cc5efcb3877cb77fca6123a70bd133e00359853e432a8454bd15d07b7d4d9|82bc86482ae9bfcc1bf97b2c1f6585118c9bc0d76dfaf6580036e46ee5cdb4d8|82bc86482ae9bfcc1bf97b2c1f6585118c9bc0d76dfaf6580036e46ee5cdb4d8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Petrovaradin''s region fell to Celts in the 4th century BC and to Romans in the 1st century BC. Under Roman administration a fortress named Cusum rose here, part of Roman Pannonia."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Petrovaradin region was conquered by Celts in the 4th century BC [S2]; the region was conquered by Romans in the 1st century BC [S2]; under Roman administration a fortress was built here [S5]; the fortress was named Cusum [S5]; the fortress was part of Roman Pannonia [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Petrovaradin is a historic town (now part of Novi Sad, Serbia) built around a fortress, the place the text is about [SUPPORTED: https://en.wikipedia.org/wiki/Petrovaradin]; The Petrovaradin region was conquered by Celts in the 4th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Petrovaradin]; The Petrovaradin region was conquered by Romans in the 1st century BC [SUPPORTED: https://en.wikipedia.org/wiki/Petrovaradin]; Under Roman administration a fortress named Cusum was built here [SUPPORTED: https://en.wikipedia.org/wiki/Petrovaradin]; The Cusum fortress was part of Roman Pannonia [SUPPORTED: https://en.wikipedia.org/wiki/Petrovaradin]"}]'::jsonb),
    ('c3b60256-57d1-4b74-80f0-1a2536795a20'::uuid, 'card_description', 'The oldest known village in the Bannu region, Sheri Khan Tarakai was home to perhaps a few hundred people in mud-walled houses, some on stone foundations under flat roofs of wattle and daub.', 'Neolithic village of mud-walled houses occupied 5000–2500 BC in the Bannu District. Stone foundations and wattle-and-daub roofs sheltered a few hundred people over two and a half thousand years.', 'teaser-card-s015-rollback:c3b60256-57d1-4b74-80f0-1a2536795a20:card_description', 'rollback of teaser-card-s015: card_description ''Neolithic village of mud-walled houses occupied 5000–2500 BC in the Bannu District. Stone foundations and wattle-and-daub roofs sheltered a few hundred people over two and a half thousand years.'' restored on Sheri Khan Tarakai', 'f0bc0ed74abe1b8e0e545e96688c297c4e17a6ccfc1576c267203ebb46b68a9c|abab38fedc77be15870bf39a873f907b7271e2d534522591d58fb9541dc7c8d6|abab38fedc77be15870bf39a873f907b7271e2d534522591d58fb9541dc7c8d6', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The oldest known village in the Bannu region, Sheri Khan Tarakai was home to perhaps a few hundred people in mud-walled houses, some on stone foundations under flat roofs of wattle and daub."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sheri Khan Tarakai is the oldest known village in the Bannu region [S4]; it was home to perhaps a few hundred people [S2]; the people lived in mud-walled houses [S2]; some houses had stone foundations [S2]; some houses had flat roofs of wattle and daub [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sheri Khan Tarakai is an ancient village settlement site in the Bannu region (Bannu District, Khyber-Pakhtunkhwa), Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Sheri_Khan_Tarakai]; It is the oldest known village in the Bannu region [SUPPORTED: https://en.wikipedia.org/wiki/Sheri_Khan_Tarakai]; The village was home to perhaps a few hundred people [SUPPORTED: https://en.wikipedia.org/wiki/Sheri_Khan_Tarakai]; The people lived in mud-walled houses [SUPPORTED: https://en.wikipedia.org/wiki/Sheri_Khan_Tarakai]; Some of the houses stood on stone foundations [SUPPORTED: https://en.wikipedia.org/wiki/Sheri_Khan_Tarakai]; The houses had flat roofs of wattle and daub [SUPPORTED: https://en.wikipedia.org/wiki/Sheri_Khan_Tarakai]"}]'::jsonb),
    ('c4bfc499-08d9-4cd2-ac3f-91ddaa743710'::uuid, 'card_description', 'In the chalk of Norfolk, the Neolithic miners of Grime''s Graves sank at least 433 shafts, digging with red deer antler picks through topstone and wallstone toward the floorstone flint.', 'Grime''s Graves was first extensively explored by the archaeologist William Greenwell in 1868.', 'teaser-card-s015-rollback:c4bfc499-08d9-4cd2-ac3f-91ddaa743710:card_description', 'rollback of teaser-card-s015: card_description "Grime''s Graves was first extensively explored by the archaeologist William Greenwell in 1868." restored on Grime''s Graves', '13f7a8d4994170789b82d7b98f0169f0bbb091729de766c9d633ea77aedbb651|60f0dc1ffe84a111e7e5a52857fcc81bbc985a408ed32256c749912d9c4a1357|60f0dc1ffe84a111e7e5a52857fcc81bbc985a408ed32256c749912d9c4a1357', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the chalk of Norfolk, the Neolithic miners of Grime''s Graves sank at least 433 shafts, digging with red deer antler picks through topstone and wallstone toward the floorstone flint."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Grime''s Graves is in Norfolk [S1]; the shafts were dug into the natural chalk [S4]; the miners were Neolithic [S1]; at least 433 shafts were sunk [S4]; the miners dug with red deer antler picks [S7]; they dug through topstone and wallstone seams [S6]; they were heading toward the floorstone flint [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Grime''s Graves is a Neolithic flint mining complex (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]; Grime''s Graves is in Norfolk [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]; The shafts were dug into chalk [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]; The site has at least 433 shafts [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]; The miners were Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]; The miners dug with red deer antler picks [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]; The miners dug through the topstone flint seam [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]; The miners dug through the wallstone flint seam [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]; The miners were heading toward the floorstone flint seam [SUPPORTED: https://en.wikipedia.org/wiki/Grime%27s_Graves]"}]'::jsonb),
    ('c5761cbc-32e4-48b1-97de-a33bca256831'::uuid, 'card_description', 'On a peak of the Sierra de Tepoztlan, the small temple of El Tepozteco honoured Tepoztecatl, the Aztec god of pulque, and drew pilgrims from as far away as Guatemala.', 'A 15th-century temple to Tepoztēcatl, the Aztec god of pulque — a fermented agave drink. Pilgrims traveled from as far as Guatemala to worship here.', 'teaser-card-s015-rollback:c5761cbc-32e4-48b1-97de-a33bca256831:card_description', 'rollback of teaser-card-s015: card_description ''A 15th-century temple to Tepoztēcatl, the Aztec god of pulque — a fermented agave drink. Pilgrims traveled from as far as Guatemala to worship here.'' restored on El Tepozteco', '41e8fb6000f752a821ad57d688850996a89134956db7163f7b3aa05345073ed1|0fc86c1d7033c1f7f96cc38efc18b6c089a6cb66e035674c02efb88a60cc8718|0fc86c1d7033c1f7f96cc38efc18b6c089a6cb66e035674c02efb88a60cc8718', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a peak of the Sierra de Tepoztlan, the small temple of El Tepozteco honoured Tepoztecatl, the Aztec god of pulque, and drew pilgrims from as far away as Guatemala."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "El Tepozteco is on a peak of the Sierra de Tepoztlan [S3]; it has a small temple [S2]; the temple honoured Tepoztecatl (a temple to Tepoztecatl) [S2]; Tepoztecatl is the Aztec god of pulque [S2]; the temple drew pilgrims from as far away as Guatemala [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "El Tepozteco is an archaeological site (a temple) in the Mexican state of Morelos, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/El_Tepozteco]; The temple is small [SUPPORTED: https://en.wikipedia.org/wiki/El_Tepozteco]; The temple stands on a peak of the Sierra de Tepoztlan [SUPPORTED: https://en.wikipedia.org/wiki/El_Tepozteco]; The temple honoured Tepoztecatl [SUPPORTED: https://en.wikipedia.org/wiki/El_Tepozteco]; Tepoztecatl is the Aztec god of pulque [SUPPORTED: https://en.wikipedia.org/wiki/El_Tepozteco]; The temple drew pilgrims from as far away as Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/El_Tepozteco]"}]'::jsonb),
    ('c5f853ae-ee16-4da1-9f17-f3ff66205f61'::uuid, 'card_description', 'At the eastern end of the Dundry Down ridge, south of Bristol, stands Maes Knoll, an Iron Age hill fort whose name joins a Brythonic word for flat top with an Old English word for hill.', 'Dating to around 250 BC, Maes Knoll covers 8 hectares with a rampart rising 14 metres. The Wansdyke — a post-Roman frontier bank — meets the fort at its eastern edge.', 'teaser-card-s015-rollback:c5f853ae-ee16-4da1-9f17-f3ff66205f61:card_description', 'rollback of teaser-card-s015: card_description ''Dating to around 250 BC, Maes Knoll covers 8 hectares with a rampart rising 14 metres. The Wansdyke — a post-Roman frontier bank — meets the fort at its eastern edge.'' restored on Maes Knoll', '60fce693fce3f7a4ea7588acea26ff89cc9c66d0199f51edf1733a374cf3a9f8|ffc5e49c718c9b8e5c863b5876612873b457253782f4a4b639bd81043ad13f79|ffc5e49c718c9b8e5c863b5876612873b457253782f4a4b639bd81043ad13f79', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At the eastern end of the Dundry Down ridge, south of Bristol, stands Maes Knoll, an Iron Age hill fort whose name joins a Brythonic word for flat top with an Old English word for hill."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Maes Knoll is at the eastern end of the Dundry Down ridge [S1]; it is south of Bristol [S1]; it is an Iron Age hill fort [S1]; its name joins a Brythonic word for flat top [S4]; its name joins an Old English word for hill [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Maes Knoll is an Iron Age hill fort [SUPPORTED: http://www.wansdyke21.org.uk/wansdyke/wanwesteast/wanwest1.htm]; It stands at the eastern end of the Dundry Down ridge [SUPPORTED: https://en.wikipedia.org/wiki/Maes_Knoll]; It lies south of Bristol [SUPPORTED: https://en.wikipedia.org/wiki/Maes_Knoll]; The first part of the name, Maes, is a Brythonic word for flat top (sources conflict: Wikipedia says so, but the Wansdyke Project 21 page it cites derives the name from Maerc- ''boundary'') [UNVERIFIABLE, no proving quote: None]; The second part of the name, Knoll, is an Old English word for hill [SUPPORTED: https://en.wikipedia.org/wiki/Maes_Knoll]"}]'::jsonb),
    ('c5f8bd3a-c334-453c-b99b-9509aac6ea90'::uuid, 'card_description', 'In a hillside cave by the Meuse, Scladina yielded the nearly complete jaw of a Neanderthal child, dated to around 127,000 years, its DNA one of the oldest drawn from a Neanderthal fossil.', 'After the initial clearing of the entrance, the excavations uncovered two strata of Neanderthal occupation, the oldest dating back 130,000 years.', 'teaser-card-s015-rollback:c5f8bd3a-c334-453c-b99b-9509aac6ea90:card_description', 'rollback of teaser-card-s015: card_description ''After the initial clearing of the entrance, the excavations uncovered two strata of Neanderthal occupation, the oldest dating back 130,000 years.'' restored on Scladina', 'a6dbcd2e14b8e18629ba68563235838d98dc807750a95140b5f41d2e5191eeef|7dd9b39cbb7e478f023ccf102a08ec9829ca00d49305027e0611fb497f0dbc98|7dd9b39cbb7e478f023ccf102a08ec9829ca00d49305027e0611fb497f0dbc98', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In a hillside cave by the Meuse, Scladina yielded the nearly complete jaw of a Neanderthal child, dated to around 127,000 years, its DNA one of the oldest drawn from a Neanderthal fossil."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Scladina is a cave on a hillside [S2]; the cave lies by the Meuse river [S2]; the site yielded a nearly complete jaw (mandible) [S4]; the jaw belongs to a Neanderthal child [S1, S5]; the jaw is dated to around 127,000 years [S4]; the child''s DNA is one of the oldest extracted from a Neanderthal fossil [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Scladina is a cave (an archaeological site) in Belgium [SUPPORTED: https://en.wikipedia.org/wiki/Scladina]; The cave lies on a hillside by the Meuse [SUPPORTED: https://en.wikipedia.org/wiki/Scladina]; The cave yielded a nearly complete jaw (mandible) [SUPPORTED: https://en.wikipedia.org/wiki/Scladina]; The jaw belonged to a Neanderthal child (the Scladina child) [SUPPORTED: https://en.wikipedia.org/wiki/Scladina]; The child''s fossil is dated to around 127,000 years [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Scladina]; DNA was drawn from the Neanderthal child''s fossil (a molar) [SUPPORTED: https://en.wikipedia.org/wiki/Scladina]; The child''s DNA is one of the oldest drawn from a Neanderthal fossil [SUPPORTED: https://en.wikipedia.org/wiki/Scladina]"}]'::jsonb),
    ('c68b5a7f-8fb5-426e-b73e-7743264afc87'::uuid, 'card_description', 'An ancient village lies amid modern Umm el-Jimal: 150 houses still standing, 15 churches from a sixth-century building boom, all deserted under the Abbasid Caliphs in the ninth century.', 'The Nabataean peoples were the first to build permanent homesteads in the area in the first century AD.', 'teaser-card-s015-rollback:c68b5a7f-8fb5-426e-b73e-7743264afc87:card_description', 'rollback of teaser-card-s015: card_description ''The Nabataean peoples were the first to build permanent homesteads in the area in the first century AD.'' restored on Umm el-Jimal', 'f1978e0dd2d79719d814402f342292cfb69677ab4747e93dff153bf7f54296b8|3698cf00e0eaee32a4b9661868338e19407e914c45449d75dd1e7f2b22d4a34d|3698cf00e0eaee32a4b9661868338e19407e914c45449d75dd1e7f2b22d4a34d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "An ancient village lies amid modern Umm el-Jimal: 150 houses still standing, 15 churches from a sixth-century building boom, all deserted under the Abbasid Caliphs in the ninth century."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the ruins of an ancient village lie amid modern Umm el-Jimal [S1]; 150 houses are still standing [S5]; 15 churches can still be seen [S6]; the churches come from a sixth-century boom in church building [S6]; the site was deserted under the Abbasid Caliphs in the ninth century [S8]; the desertion was complete (all deserted) [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Umm el-Jimal is a village in northern Jordan with the ruins of an ancient town [SUPPORTED: https://en.wikipedia.org/wiki/Umm_el-Jimal]; The ruins of an ancient village lie amid the modern Umm el-Jimal [SUPPORTED: https://en.wikipedia.org/wiki/Umm_el-Jimal]; 150 houses are still standing [SUPPORTED: https://en.wikipedia.org/wiki/Umm_el-Jimal]; There was a boom of church construction in the sixth century [SUPPORTED: https://en.wikipedia.org/wiki/Umm_el-Jimal]; 15 of these churches can still be seen [SUPPORTED: https://en.wikipedia.org/wiki/Umm_el-Jimal]; The site was completely deserted under the Abbasid Caliphs [SUPPORTED: https://en.wikipedia.org/wiki/Umm_el-Jimal]; The desertion under the Abbasids happened in the ninth century [SUPPORTED: https://en.wikipedia.org/wiki/Umm_el-Jimal]"}]'::jsonb),
    ('c6d155e2-7202-4ee6-b29f-b3d9a440efae'::uuid, 'card_description', 'Near the village of Telheiro stand the Antas do Olival da Pêga, two megalithic tombs about 300 meters apart. Over one hundred people were buried in each; Anta 1 is among Portugal''s tallest.', 'The Antas do Olival da Pêga are 2 dolmens located near the village of Telheiro in Évora.', 'teaser-card-s015-rollback:c6d155e2-7202-4ee6-b29f-b3d9a440efae:card_description', 'rollback of teaser-card-s015: card_description ''The Antas do Olival da Pêga are 2 dolmens located near the village of Telheiro in Évora.'' restored on Antas do Olival da Pêga', 'bb3d342430d19f2f4786b8e2e6a72a26b0da5afbc9864b57871fc9452b6e4d61|f8bd72587b52b798298e5f574940ddd6448676d16b34b9ab30cf38bcc5f67246|f8bd72587b52b798298e5f574940ddd6448676d16b34b9ab30cf38bcc5f67246', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near the village of Telheiro stand the Antas do Olival da Pêga, two megalithic tombs about 300 meters apart. Over one hundred people were buried in each; Anta 1 is among Portugal''s tallest."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Antas do Olival da Pêga stand near the village of Telheiro [S1]; there are two of them, both megalithic tombs [S1, S2]; the two tombs are about 300 meters apart [S5]; over one hundred people were buried in each tomb [S6]; Anta 1 is among the tallest antas in Portugal [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Antas do Olival da Pêga are two megalithic tombs (dolmens) near the village of Telheiro, Portugal [SUPPORTED: https://en.wikipedia.org/