    ('c7a242e3-1638-4260-82da-ec130f9cc023'::uuid, 'card_description', 'South of the old city of Jalalpur Jattan lies Salamgarh, an old city itself, whose fort of Islamgarh remained under Aurangzeb Alamgir, Ahmed Shah Abdali and Ranjit Singh and their forces.', 'The fort of Islamgarh had remained under Aurangzeb Alamgir, Ahmed Shah Abdali, and Ranjit Singh and their forces.', 'teaser-card-s015-rollback:c7a242e3-1638-4260-82da-ec130f9cc023:card_description', 'rollback of teaser-card-s015: card_description ''The fort of Islamgarh had remained under Aurangzeb Alamgir, Ahmed Shah Abdali, and Ranjit Singh and their forces.'' restored on Salamgarh', '3a52fb2ad55c1b2a4b784aec3286048ac7d9f8ac4532356d4fbbddf34972b04a|6e3ff2d9ae526131883ab86a783edbc39e0ef64405f939629e9b26ea9cc47e3a|6e3ff2d9ae526131883ab86a783edbc39e0ef64405f939629e9b26ea9cc47e3a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "South of the old city of Jalalpur Jattan lies Salamgarh, an old city itself, whose fort of Islamgarh remained under Aurangzeb Alamgir, Ahmed Shah Abdali and Ranjit Singh and their forces."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Salamgarh lies south of the old city of Jalalpur Jattan [S2]; Salamgarh is an old city [S1]; Salamgarh has a fort called Islamgarh [S1, S3]; the fort remained under Aurangzeb Alamgir, Ahmed Shah Abdali and Ranjit Singh and their forces [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Salamgarh is an old city (now a neighbourhood) [SUPPORTED: https://en.wikipedia.org/wiki/Salamgarh]; Salamgarh is in Jalalpur Jattan, Punjab, Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Salamgarh]; Salamgarh lies south of the old city of Jalalpur Jattan [SUPPORTED: https://en.wikipedia.org/wiki/Salamgarh]; Salamgarh has a fort known as Islamgarh Fort [SUPPORTED: https://en.wikipedia.org/wiki/Salamgarh]; The fort of Islamgarh remained under Aurangzeb Alamgir and his forces [SUPPORTED: https://en.wikipedia.org/wiki/Salamgarh]; The fort of Islamgarh remained under Ahmed Shah Abdali and Ranjit Singh and their forces [SUPPORTED: https://en.wikipedia.org/wiki/Salamgarh]"}]'::jsonb),
    ('c85493c5-808e-4d63-b06a-a570a21af151'::uuid, 'card_description', 'On a ridge 609 m above sea level, near the sources of the Aufidus, the Hirpini city of Compsa was betrayed to Hannibal in 216 BC after the defeat of Cannae, then recaptured two years later.', 'A 2nd-century BC Hirpini city betrayed to Hannibal after Cannae in 216 BC. Two years later Rome recaptured it — and it kept changing hands for centuries.', 'teaser-card-s015-rollback:c85493c5-808e-4d63-b06a-a570a21af151:card_description', 'rollback of teaser-card-s015: card_description ''A 2nd-century BC Hirpini city betrayed to Hannibal after Cannae in 216 BC. Two years later Rome recaptured it — and it kept changing hands for centuries.'' restored on Compsa', '253c096e1021a15ee1780ebd871fe5c5c9d40469510a2e2f9ad0231e80411250|6d902fc734bef30b34d5e6a9053083244f4ed839a2844edacd41b46da3ed55c1|6d902fc734bef30b34d5e6a9053083244f4ed839a2844edacd41b46da3ed55c1', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a ridge 609 m above sea level, near the sources of the Aufidus, the Hirpini city of Compsa was betrayed to Hannibal in 216 BC after the defeat of Cannae, then recaptured two years later."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Compsa lies on a ridge 609 m above sea level [S1]; Compsa lies near the sources of the Aufidus [S1]; Compsa was a city of the Hirpini [S1]; Compsa was betrayed to Hannibal in 216 BC [S2]; the betrayal came after the defeat of Cannae [S2]; Compsa was recaptured two years later [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Compsa was an ancient city of the Hirpini [SUPPORTED: https://en.wikipedia.org/wiki/Compsa]; Compsa lay in what is now Conza della Campania in southern Italy [SUPPORTED: https://en.wikipedia.org/wiki/Conza_della_Campania]; Compsa lay near the sources of the Aufidus [SUPPORTED: https://en.wikipedia.org/wiki/Compsa]; Compsa stood on a ridge 609 m above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Compsa]; Compsa was betrayed to Hannibal [SUPPORTED: https://en.wikipedia.org/wiki/Compsa]; The betrayal happened in 216 BC after the defeat at Cannae [SUPPORTED: https://en.wikipedia.org/wiki/Compsa]; Compsa was recaptured two years later [SUPPORTED: https://en.wikipedia.org/wiki/Compsa]"}]'::jsonb),
    ('c8ec86a6-5e59-47c9-a1be-51db69a2f0d7'::uuid, 'card_description', 'On a hill east of Keswick, the volcanic boulders of Castlerigg Stone Circle, the heaviest estimated at around 16 tons, ring a flattened circle with a 3.3 metre gap, perhaps an entrance.', 'Castlerigg stone circle was one of the monuments included in the Ancient Monuments Protection Act 1882.', 'teaser-card-s015-rollback:c8ec86a6-5e59-47c9-a1be-51db69a2f0d7:card_description', 'rollback of teaser-card-s015: card_description ''Castlerigg stone circle was one of the monuments included in the Ancient Monuments Protection Act 1882.'' restored on Castlerigg Stone Circle', 'e0a963aa5f57214c2e500fd5af5bfc954dfa5e8f6dfab78a01bf579fc5c9f0f2|2b007d983be54041f2190cbe9bd312f9853dea82fe009a2cf3287cdcebb2fad4|2b007d983be54041f2190cbe9bd312f9853dea82fe009a2cf3287cdcebb2fad4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a hill east of Keswick, the volcanic boulders of Castlerigg Stone Circle, the heaviest estimated at around 16 tons, ring a flattened circle with a 3.3 metre gap, perhaps an entrance."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Castlerigg Stone Circle stands on a hill east of Keswick [S1]; the stones are volcanic boulders [S2]; the heaviest stone is estimated at around 16 tons [S5]; the stones form a flattened circle [S4]; there is a 3.3 metre gap in the circle [S6]; the gap may have been an entrance (hedged as perhaps) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Castlerigg Stone Circle is a stone circle on a hill east of Keswick, England [SUPPORTED: https://en.wikipedia.org/wiki/Castlerigg_stone_circle]; The stones are volcanic boulders [SUPPORTED: https://en.wikipedia.org/wiki/Castlerigg_stone_circle]; The heaviest stone is estimated at around 16 tons [SUPPORTED: https://en.wikipedia.org/wiki/Castlerigg_stone_circle]; The stones ring a flattened circle [SUPPORTED: https://en.wikipedia.org/wiki/Castlerigg_stone_circle]; The circle has a gap 3.3 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Castlerigg_stone_circle]; The gap was perhaps an entrance (its function is uncertain) [SUPPORTED: https://en.wikipedia.org/wiki/Castlerigg_stone_circle]"}]'::jsonb),
    ('c9645011-82ed-4818-b2fd-0b3632713d1c'::uuid, 'card_description', 'Above the Montpellier garrigue at 190m, the Oppidum d''Altimurium, founded in the 2nd century BC, was guarded by a wall almost 2 km long; its Roman heart held a square and probably a temple.', 'The site, which overlooks the Montpellier garrigue at 190m altitude and covers about 20 hectares, is one of the largest hill forts in the region.', 'teaser-card-s015-rollback:c9645011-82ed-4818-b2fd-0b3632713d1c:card_description', 'rollback of teaser-card-s015: card_description ''The site, which overlooks the Montpellier garrigue at 190m altitude and covers about 20 hectares, is one of the largest hill forts in the region.'' restored on Oppidum d''Altimurium', '0902403280a3d3effcd901c2f1f8b6e4327d4686f3c92c5a14a72b899dab4ad3|1571aca9fa7ac323393c8eb6c4c0996d7d7a1533487dc3bebb4afbe5e1b7011d|1571aca9fa7ac323393c8eb6c4c0996d7d7a1533487dc3bebb4afbe5e1b7011d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the Montpellier garrigue at 190m, the Oppidum d''Altimurium, founded in the 2nd century BC, was guarded by a wall almost 2 km long; its Roman heart held a square and probably a temple."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the oppidum overlooks the Montpellier garrigue at 190m [S2]; the oppidum was founded in the 2nd century BC [S3]; it was protected by a wall almost 2 km long [S3]; it had a Roman monumental area at the middle of the town, between the upper and lower town (its Roman heart) [S4, S5]; that area held a square [S5]; that area held a large building that was probably a temple (hedge kept) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Oppidum d''Altimurium is an ancient hill-town (oppidum) near Murviel-les-Montpellier, France [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_d%27Altimurium]; It overlooks the Montpellier garrigue at 190 m altitude [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_d%27Altimurium]; It was founded in the 2nd century BC [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_d%27Altimurium]; It was guarded by a wall almost 2 km long [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_d%27Altimurium]; Its Roman monumental area held a square [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_d%27Altimurium]; The Roman area held probably a temple [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_d%27Altimurium]"}]'::jsonb),
    ('c9ea41a4-53e0-481a-9e3c-d314cfa36c9e'::uuid, 'card_description', 'Above the mouth of the Miño, at 341 meters, the Castro of Santa Trega is a settlement of circular structures, lived in from 100 BC to 100 AD; in 1862 stonemasons found a bronze Hercules.', 'In 1862, the first recorded archaeological discovery was a bronze sculpture of Hercules found by stonemasons.', 'teaser-card-s015-rollback:c9ea41a4-53e0-481a-9e3c-d314cfa36c9e:card_description', 'rollback of teaser-card-s015: card_description ''In 1862, the first recorded archaeological discovery was a bronze sculpture of Hercules found by stonemasons.'' restored on Castro of Santa Trega', 'edb2836eea47b3d6ba4223891623b9078341e0a1684c3e7cb537d0c32555caa0|f53101bb047a065375c5d6263493d65f2523c75e87ec8e1e72d6defdff4a50b5|f53101bb047a065375c5d6263493d65f2523c75e87ec8e1e72d6defdff4a50b5', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the mouth of the Miño, at 341 meters, the Castro of Santa Trega is a settlement of circular structures, lived in from 100 BC to 100 AD; in 1862 stonemasons found a bronze Hercules."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the castro overlooks the mouth of the river Miño [S2]; the site lies at 341 meters above sea level [S2]; Castro of Santa Trega is a settlement [S3]; the settlement is built of circular structures [S6]; it was inhabited from 100 BC to 100 AD [S4]; in 1862 stonemasons found a bronze Hercules [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Castro of Santa Trega is a settlement (a castro, a fortified village of the Castro culture) in Galicia, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Santa_Trega]; It lies above the mouth of the Miño [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Santa_Trega]; It lies at 341 meters [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Santa_Trega]; The settlement is made of circular structures [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Santa_Trega]; It was lived in from 100 BC to 100 AD [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Santa_Trega]; In 1862 stonemasons found a bronze Hercules [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Santa_Trega]"}]'::jsonb),
    ('ca1f8a94-27e1-4318-b3d5-3db181795ffd'::uuid, 'card_description', 'In the suburbs of today''s capital lie the remains of Panamá Viejo, founded in 1519, once a base for gold and silver bound for Spain, destroyed in 1671 by the Welsh privateer Henry Morgan.', 'The first permanent European settlement on the Pacific coast, founded in 1519. It was destroyed in 1671 by the Welsh privateer Henry Morgan.', 'teaser-card-s015-rollback:ca1f8a94-27e1-4318-b3d5-3db181795ffd:card_description', 'rollback of teaser-card-s015: card_description ''The first permanent European settlement on the Pacific coast, founded in 1519. It was destroyed in 1671 by the Welsh privateer Henry Morgan.'' restored on Panamá Viejo', 'b65eafe3c900455e407ee6eb7fa42dd929474d09f6ff6daa4ff026f955d508de|884dd857f5bba549dbdc1b9c7d61fa04e6e90fe8919d7703ae89e19a63cc5b42|884dd857f5bba549dbdc1b9c7d61fa04e6e90fe8919d7703ae89e19a63cc5b42', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the suburbs of today''s capital lie the remains of Panamá Viejo, founded in 1519, once a base for gold and silver bound for Spain, destroyed in 1671 by the Welsh privateer Henry Morgan."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the remains of Panamá Viejo lie in the suburbs of today''s capital [S1, S2]; it was founded in 1519 [S3]; it was a base for gold and silver sent to Spain [S6]; it was destroyed in 1671 [S1]; the destroyer was the Welsh privateer Henry Morgan [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Panamá Viejo is the remaining part (the remains) of the original Panama City, the former capital [SUPPORTED: https://en.wikipedia.org/wiki/Panam%C3%A1_Viejo]; The remains lie in the suburbs of today''s capital [SUPPORTED: https://en.wikipedia.org/wiki/Panam%C3%A1_Viejo]; It was founded in 1519 [SUPPORTED: https://en.wikipedia.org/wiki/Panam%C3%A1_Viejo]; It was once a base for gold and silver bound for Spain [SUPPORTED: https://en.wikipedia.org/wiki/Panam%C3%A1_Viejo]; It was destroyed in 1671 by Henry Morgan [SUPPORTED: https://en.wikipedia.org/wiki/Panam%C3%A1_Viejo]; Henry Morgan was a Welsh privateer [SUPPORTED: https://en.wikipedia.org/wiki/Panam%C3%A1_Viejo]"}]'::jsonb),
    ('cab346d8-176c-429d-830c-2f1ac68e2eb9'::uuid, 'card_description', 'The Roman Thermae of Maximinus, public baths of Bracara Augusta, shrank at the end of the 3rd century; by the 4th century even the theatre fell silent, its stones used for the city walls.', 'A monumental Roman public bathhouse from the 1st century BC, part of the provincial capital''s urban renewal. The complex was enormous for its era.', 'teaser-card-s015-rollback:cab346d8-176c-429d-830c-2f1ac68e2eb9:card_description', 'rollback of teaser-card-s015: card_description "A monumental Roman public bathhouse from the 1st century BC, part of the provincial capital''s urban renewal. The complex was enormous for its era." restored on Roman Thermae of Maximinus', '0f0598c874896ed751dc55789f293615ecd4ad38012cda15a00b36e6e6cb25ab|768be40ce94371713cf08d7be8e2f5d49fb901ada7ec2aa09ff298417fd1bc19|768be40ce94371713cf08d7be8e2f5d49fb901ada7ec2aa09ff298417fd1bc19', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Thermae of Maximinus, public baths of Bracara Augusta, shrank at the end of the 3rd century; by the 4th century even the theatre fell silent, its stones used for the city walls."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Roman Thermae of Maximinus were public baths [S1]; the baths belonged to Bracara Augusta [S1]; the thermae shrank (their occupied area was substantially reduced) at the end of the 3rd century [S3]; by the 4th century even the theatre was deactivated (fell silent) [S4]; the theatre''s stones were used for the city walls [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Thermae of Maximinus are Roman public baths (thermae), the ruins of a monumental building with public baths [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Thermae_of_Maximinus]; The baths belonged to Bracara Augusta (later Braga, Portugal) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Thermae_of_Maximinus]; The baths shrank at the end of the 3rd century [SUPPORTED, no proving quote: https://imovel.patrimoniocultural.gov.pt/detalhes.php?code=69713]; A theatre was part of the same complex as the baths [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Thermae_of_Maximinus]; By the 4th century even the theatre was out of use (deactivated) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Thermae_of_Maximinus]; The theatre''s stones were used for the city walls [SUPPORTED: https://pt.wikipedia.org/wiki/Bracara_Augusta]"}]'::jsonb),
    ('cac95409-52f9-4a26-bf59-fd7af98d054e'::uuid, 'card_description', 'Hewn-stone walls up to circa 3.5 m, lintels over an eastern entrance, mosaic traces under a later floor: the Anim Synagogue, a basilical hall of the 4th to 7th centuries CE, later a mosque.', 'Hewn-stone walls still stand 3.5 metres high at this rectangular prayer hall oriented toward Jerusalem, built between the 4th and 7th centuries AD with lintels and mosaic floor evidence intact.', 'teaser-card-s015-rollback:cac95409-52f9-4a26-bf59-fd7af98d054e:card_description', 'rollback of teaser-card-s015: card_description ''Hewn-stone walls still stand 3.5 metres high at this rectangular prayer hall oriented toward Jerusalem, built between the 4th and 7th centuries AD with lintels and mosaic floor evidence intact.'' restored on Anim Synagogue', 'a24ff3dd2db9c9404cab4f8d2fce57fc5b3b9829be31b10f2af988bb41906066|4f6fe41aa4803f4bd6bc4b9ed0a1f0a7e6fdc62921bea6fbd5fd16e0210896ce|4f6fe41aa4803f4bd6bc4b9ed0a1f0a7e6fdc62921bea6fbd5fd16e0210896ce', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Hewn-stone walls up to circa 3.5 m, lintels over an eastern entrance, mosaic traces under a later floor: the Anim Synagogue, a basilical hall of the 4th to 7th centuries CE, later a mosque."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "hewn-stone walls stand up to circa 3.5 m [S3]; lintels survive over an eastern entrance [S3]; traces of a mosaic lie under a later floor [S3]; the Anim Synagogue is a basilical hall (rectangular basilical synagogue) [S2]; its main phase dates to the 4th to 7th centuries CE [S2]; it was later converted to a mosque [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Anim Synagogue is an ancient synagogue, a rectangular basilical hall (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Horvat_%27Anim]; The synagogue lies at Horvat Anim in the southern Hebron Hills, Israel [SUPPORTED: https://en.wikipedia.org/wiki/Horvat_%27Anim]; The synagogue dates to the 4th to 7th centuries CE [SUPPORTED: https://en.wikipedia.org/wiki/Horvat_%27Anim]; The synagogue was later a mosque [SUPPORTED: https://www.biblewalks.com/anim/]; Hewn-stone walls stand up to circa 3.5 m [SUPPORTED: https://en.wikipedia.org/wiki/Horvat_%27Anim]; Lintels survive over an eastern entrance [SUPPORTED: https://en.wikipedia.org/wiki/Horvat_%27Anim]; Traces of a mosaic lie under a later floor [SUPPORTED: https://en.wikipedia.org/wiki/Horvat_%27Anim]"}]'::jsonb),
    ('cc4c3c3a-1ada-47d8-93ea-2cbb7930f772'::uuid, 'card_description', 'Settled for at least 4,000 years, Castle Hill above Huddersfield carries an Iron Age hillfort from around 555 BC, a 12th-century motte-and-bailey castle and traces of a severe burning.', 'A hilltop settled for at least 4,000 years: a Bronze Age hillfort, an Iron Age multivallate fort, a Norman castle, and a deserted medieval village -- all on one summit.', 'teaser-card-s015-rollback:cc4c3c3a-1ada-47d8-93ea-2cbb7930f772:card_description', 'rollback of teaser-card-s015: card_description ''A hilltop settled for at least 4,000 years: a Bronze Age hillfort, an Iron Age multivallate fort, a Norman castle, and a deserted medieval village -- all on one summit.'' restored on Castle Hill, Huddersfield', 'a1c500d690cff16fd889f9c487345bb16a7f08c622b12af1de51261941c61a03|e20fb3195a7dbd0f4291aa9543d4242c30ad54539e5e1af474e33127edb144c2|e20fb3195a7dbd0f4291aa9543d4242c30ad54539e5e1af474e33127edb144c2', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Settled for at least 4,000 years, Castle Hill above Huddersfield carries an Iron Age hillfort from around 555 BC, a 12th-century motte-and-bailey castle and traces of a severe burning."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the hilltop has been settled for at least 4,000 years [S2]; Castle Hill lies above (overlooks) Huddersfield [S1]; it carries an Iron Age hillfort from around 555 BC [S4]; it carries a 12th-century motte-and-bailey castle [S3]; there are traces of a severe burning [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Castle Hill is a scheduled ancient monument (hillfort and castle site) above Huddersfield in West Yorkshire, England (central claim: the kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Hill,_Huddersfield]; The hilltop has been settled for at least 4,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Hill,_Huddersfield]; The hill carries an Iron Age hillfort from around 555 BC [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Hill,_Huddersfield]; The hill carries a 12th-century motte-and-bailey castle [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Hill,_Huddersfield]; The hillfort shows traces of a severe burning [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Hill,_Huddersfield]"}]'::jsonb),
    ('cc5fb86d-5a12-4ff9-85dc-5c02534e9d7a'::uuid, 'card_description', 'Once a considerable work, now a raised hedgerow or a mere cropmark, Wat''s Dyke runs 40 miles through the northern Welsh Marches beside Offa''s Dyke, and the date it was built is disputed.', 'A 64 km earthwork running parallel to the famous Offa''s Dyke, sometimes within yards of it. Its purpose and the relationship between the two dykes remains a puzzle.', 'teaser-card-s015-rollback:cc5fb86d-5a12-4ff9-85dc-5c02534e9d7a:card_description', 'rollback of teaser-card-s015: card_description "A 64 km earthwork running parallel to the famous Offa''s Dyke, sometimes within yards of it. Its purpose and the relationship between the two dykes remains a puzzle." restored on Wat''s Dyke', 'cf36abd8be92dd951c5ba0c0f96fd3fd4a07f9930f3dd96a7d5da7a60a6ea236|4bdd54d5897de4a0c8aa51ca0323466ffa8fabe1f8c85d187e38c636f7663d09|4bdd54d5897de4a0c8aa51ca0323466ffa8fabe1f8c85d187e38c636f7663d09', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Once a considerable work, now a raised hedgerow or a mere cropmark, Wat''s Dyke runs 40 miles through the northern Welsh Marches beside Offa''s Dyke, and the date it was built is disputed."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the dyke was once a considerable construction [S4]; it now shows in places as a raised hedgerow and in others as no more than a cropmark [S3]; Wat''s Dyke runs 40 miles [S1]; it runs through the northern Welsh Marches [S1]; it runs alongside (generally parallel to) Offa''s Dyke [S2]; the date it was built is disputed [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Wat''s Dyke is a linear earthwork (a dyke) running through the northern Welsh Marches (central claim: the kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Wat%27s_Dyke]; Wat''s Dyke runs 40 miles [SUPPORTED: https://en.wikipedia.org/wiki/Wat%27s_Dyke]; It runs beside Offa''s Dyke [SUPPORTED: https://en.wikipedia.org/wiki/Wat%27s_Dyke]; It now appears as a raised hedgerow in places and as a mere cropmark in others [SUPPORTED: https://en.wikipedia.org/wiki/Wat%27s_Dyke]; It was once a considerable work [SUPPORTED: https://en.wikipedia.org/wiki/Wat%27s_Dyke]; The date it was built is disputed [SUPPORTED: https://en.wikipedia.org/wiki/Wat%27s_Dyke]"}]'::jsonb),
    ('cd21e416-7458-42af-afa9-4141e9bca954'::uuid, 'card_description', 'Built in murus dacicus style against Roman conquest, the six Dacian Fortresses of the Orăştie Mountains guarded Decebalus; the capital, Sarmizegetusa Regia, crowned a 1,200 metres hill.', 'Six Dacian fortresses built in Murus Dacicus style — fusing local and classical military architecture. They were the last line of defense against Roman conquest.', 'teaser-card-s015-rollback:cd21e416-7458-42af-afa9-4141e9bca954:card_description', 'rollback of teaser-card-s015: card_description ''Six Dacian fortresses built in Murus Dacicus style — fusing local and classical military architecture. They were the last line of defense against Roman conquest.'' restored on Dacian Fortresses of the Orăştie Mountains', 'bae10ec769e6811a9acf62c664f140936be6b08eb7663e975c19240e93c01dca|a1994774375d53113ddd638c580f59b9cc578aa9f868e019aa130b7ba05f3d82|a1994774375d53113ddd638c580f59b9cc578aa9f868e019aa130b7ba05f3d82', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Built in murus dacicus style against Roman conquest, the six Dacian Fortresses of the Orăştie Mountains guarded Decebalus; the capital, Sarmizegetusa Regia, crowned a 1,200 metres hill."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the fortresses were built in murus dacicus style [S1]; they were built as protection against Roman conquest [S1]; there are six Dacian fortresses in the Orăştie Mountains [S1, S2]; the fortresses formed the defensive system of Decebalus (guarded Decebalus) [S2]; Sarmizegetusa Regia was the capital [S4]; Sarmizegetusa Regia stood at the top of a 1,200 metres hill [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Dacian Fortresses of the Orăştie Mountains are a group of Dacian hill fortresses in Romania (central claim: the kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Dacian_Fortresses_of_the_Or%C4%83%C8%99tie_Mountains]; There are six fortresses [SUPPORTED, no proving quote: https://whc.unesco.org/en/list/906]; They were built in murus dacicus style [SUPPORTED: https://en.wikipedia.org/wiki/Dacian_Fortresses_of_the_Or%C4%83%C8%99tie_Mountains]; They were built as protection against Roman conquest [SUPPORTED: https://en.wikipedia.org/wiki/Dacian_Fortresses_of_the_Or%C4%83%C8%99tie_Mountains]; The fortresses guarded Decebalus: they formed his defensive system [SUPPORTED: https://en.wikipedia.org/wiki/Dacian_Fortresses_of_the_Or%C4%83%C8%99tie_Mountains]; Sarmizegetusa Regia was the capital [SUPPORTED: https://en.wikipedia.org/wiki/Sarmizegetusa_Regia]; The capital crowned a 1,200 metres hill [SUPPORTED: https://en.wikipedia.org/wiki/Dacian_Fortresses_of_the_Or%C4%83%C8%99tie_Mountains]"}]'::jsonb),
    ('cd37791b-f83e-42ab-8cf4-94767b4b6571'::uuid, 'card_description', 'In the Graves of Sainte-Colombe-sur-Seine, burial mounds of the 6th century BC, a woman was laid to rest on an iron-clad funerary wagon, gold bracelets and earrings in her grave.', 'Iron Age burial mounds from the 6th century BC containing elite wagon burials with gold jewelry and imported Greek and Etruscan luxury goods.', 'teaser-card-s015-rollback:cd37791b-f83e-42ab-8cf4-94767b4b6571:card_description', 'rollback of teaser-card-s015: card_description ''Iron Age burial mounds from the 6th century BC containing elite wagon burials with gold jewelry and imported Greek and Etruscan luxury goods.'' restored on Graves of Sainte-Colombe-sur-Seine', '3f47d33b4acd2e3461fc008b51149fc765bad055f5e8957ec132ff8839909f92|062f26a031e9b3b2b39797d632b4302690cad33653659dbfcab0bed5d8a11d9f|062f26a031e9b3b2b39797d632b4302690cad33653659dbfcab0bed5d8a11d9f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the Graves of Sainte-Colombe-sur-Seine, burial mounds of the 6th century BC, a woman was laid to rest on an iron-clad funerary wagon, gold bracelets and earrings in her grave."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the graves are burial mounds [S1]; the burial mounds date from the 6th century BC [S1]; a woman was laid to rest in one of the graves [S5]; she lay on an iron-clad funerary wagon [S5]; gold bracelets and earrings were in her grave [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Graves of Sainte-Colombe-sur-Seine are burial mounds near Sainte-Colombe-sur-Seine in the Cote-d''Or, France (central claim: the kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Graves_of_Sainte-Colombe-sur-Seine]; The burial mounds date to the 6th century BC (La Butte wagon grave: second half of the 6th century BC) [SUPPORTED: https://www.persee.fr/doc/afeaf_1959-2248_2000_num_18_1_1666]; A woman was laid to rest in the grave on a funerary wagon [SUPPORTED: https://en.wikipedia.org/wiki/Graves_of_Sainte-Colombe-sur-Seine]; The funerary wagon was iron-clad [SUPPORTED: https://www.persee.fr/doc/afeaf_1959-2248_2000_num_18_1_1666]; Gold bracelets and earrings were in her grave [SUPPORTED: https://www.persee.fr/doc/afeaf_1959-2248_2000_num_18_1_1666]"}]'::jsonb),
    ('ce525bf9-3005-4e2b-9985-ae0037cff99f'::uuid, 'card_description', 'Steep cliffs guard two sides of Helsby Hill Fort, an Iron Age hillfort above the Cheshire Plain. Double ramparts shield its other flanks, and digs revealed a wall of sand and rubble.', 'An Iron Age cliff fort where natural sandstone cliffs form a semicircular defense on two sides. Double ramparts and a sand-and-rubble wall protected the rest.', 'teaser-card-s015-rollback:ce525bf9-3005-4e2b-9985-ae0037cff99f:card_description', 'rollback of teaser-card-s015: card_description ''An Iron Age cliff fort where natural sandstone cliffs form a semicircular defense on two sides. Double ramparts and a sand-and-rubble wall protected the rest.'' restored on Helsby Hill Fort', 'b3aa95a241fdda6ed6dd623678f62bbd84d7e3735e7aff5c2e02205c9a4da4ae|aa8dddd4e63cdb3c4c150abcbd07969f6e87d3a4fd3a4094cbbebca5bb36b755|aa8dddd4e63cdb3c4c150abcbd07969f6e87d3a4fd3a4094cbbebca5bb36b755', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Steep cliffs guard two sides of Helsby Hill Fort, an Iron Age hillfort above the Cheshire Plain. Double ramparts shield its other flanks, and digs revealed a wall of sand and rubble."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "steep cliffs guard two sides of the site [S2]; Helsby Hill Fort is an Iron Age hillfort [S1]; it lies above the Cheshire Plain [S6]; double ramparts protect the other flanks (south and east) [S3]; excavations revealed a wall of sand and rubble [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Helsby Hill Fort is an Iron Age hillfort in Cheshire, England (central claim: a hillfort) [SUPPORTED: https://en.wikipedia.org/wiki/Helsby_hill_fort]; The hill rises above the Cheshire Plain [SUPPORTED: https://en.wikipedia.org/wiki/Helsby_hill_fort]; Steep cliffs guard two sides of the fort (north and west) [SUPPORTED: https://en.wikipedia.org/wiki/Helsby_hill_fort]; Double ramparts protect its other flanks (south and east) [SUPPORTED: https://en.wikipedia.org/wiki/Helsby_hill_fort]; Excavations revealed a wall of sand and rubble [SUPPORTED: https://en.wikipedia.org/wiki/Helsby_hill_fort]"}]'::jsonb),
    ('cecf3b1e-4685-4c8b-acbd-f4e1be336f0b'::uuid, 'card_description', 'About 26 house ruins and several middens lie at Uummannaq, where whaling Captain George Comer dug in 1916. Comer''s Midden is the find after which the Thule culture was named.', 'The site shows signs of having been inhabited from the 14th to the 20th century although Holtved reports that the 17th and 18th centuries are poorly represented.', 'teaser-card-s015-rollback:cecf3b1e-4685-4c8b-acbd-f4e1be336f0b:card_description', 'rollback of teaser-card-s015: card_description ''The site shows signs of having been inhabited from the 14th to the 20th century although Holtved reports that the 17th and 18th centuries are poorly represented.'' restored on Comer''s Midden', 'f27c93858a3b0eb5df5e17477207232db4b066200ed2097344c687ecb59cac8a|b86226d8f7ee07edde39f52aa122a7c4e3433122bca7dc692106baf3644b9cc8|b86226d8f7ee07edde39f52aa122a7c4e3433122bca7dc692106baf3644b9cc8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "About 26 house ruins and several middens lie at Uummannaq, where whaling Captain George Comer dug in 1916. Comer''s Midden is the find after which the Thule culture was named."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site has about 26 house ruins [S6]; the site has several middens [S6]; the site lies at Uummannaq [S1]; whaling Captain George Comer dug there [S3]; Comer dug there in 1916 [S1, S3]; Comer''s Midden is the find after which the Thule culture was named [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Comer''s Midden is an archaeological excavation site (a settlement of house ruins and middens) (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Comer%27s_Midden]; The site lies at Uummannaq (Greenland) [SUPPORTED: https://en.wikipedia.org/wiki/Comer%27s_Midden]; About 26 house ruins lie at the site [SUPPORTED: https://en.wikipedia.org/wiki/Comer%27s_Midden]; Several middens lie at the site [SUPPORTED: https://en.wikipedia.org/wiki/Comer%27s_Midden]; George Comer was a whaling captain [SUPPORTED: https://en.wikipedia.org/wiki/Comer%27s_Midden]; Comer dug (excavated) at the site in 1916 [SUPPORTED: https://en.wikipedia.org/wiki/Comer%27s_Midden]; Comer''s Midden is the find after which the Thule culture was named [SUPPORTED: https://en.wikipedia.org/wiki/Comer%27s_Midden]"}]'::jsonb),
    ('cfe7373f-ccbd-42a0-88db-bc19fe33d950'::uuid, 'card_description', 'Petroglyphs are engraved on the Lapa de Gargantáns, a menhir in Moraña dated between 3000–2000 BC. Its exact function is unknown; some link it to burials, worship or old tribal boundaries.', 'The Lapa de Gargantáns is a menhir located in the Galician municipality of Moraña, dated between 3000–2000 BC and discovered in 1958.', 'teaser-card-s015-rollback:cfe7373f-ccbd-42a0-88db-bc19fe33d950:card_description', 'rollback of teaser-card-s015: card_description ''The Lapa de Gargantáns is a menhir located in the Galician municipality of Moraña, dated between 3000–2000 BC and discovered in 1958.'' restored on Lapa de Gargantáns', 'c075a5a6ba652086d63134baaeb4aa36d2ec1ce4097e46655db5ea1eb11936ad|63842096b0c564bfd705463cde516e46e34acf2a5573fba8b44af24a82bc012f|63842096b0c564bfd705463cde516e46e34acf2a5573fba8b44af24a82bc012f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Petroglyphs are engraved on the Lapa de Gargantáns, a menhir in Moraña dated between 3000–2000 BC. Its exact function is unknown; some link it to burials, worship or old tribal boundaries."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "petroglyphs are engraved on the Lapa de Gargantáns [S2]; it is a menhir [S1]; it is in Moraña [S1]; it is dated between 3000-2000 BC [S1]; its exact function is unknown [S3]; some archaeologists link it to funerary signs (burials) [S3]; some archaeologists link it to religious signs (worship) [S3]; some archaeologists link it to ancient territorial boundaries between tribes [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Lapa de Gargantáns is a menhir (central claim: a standing stone) [SUPPORTED: https://en.wikipedia.org/wiki/Lapa_de_Gargant%C3%A1ns]; It is located in Moraña (Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Lapa_de_Gargant%C3%A1ns]; It is dated between 3000-2000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Lapa_de_Gargant%C3%A1ns]; Petroglyphs are engraved on it [SUPPORTED: https://en.wikipedia.org/wiki/Lapa_de_Gargant%C3%A1ns]; Its exact function is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Lapa_de_Gargant%C3%A1ns]; Some link it to burials (funerary signs) [SUPPORTED: https://en.wikipedia.org/wiki/Lapa_de_Gargant%C3%A1ns]; Some link it to worship (religious signs) [SUPPORTED: https://en.wikipedia.org/wiki/Lapa_de_Gargant%C3%A1ns]; Some link it to old tribal boundaries [SUPPORTED: https://en.wikipedia.org/wiki/Lapa_de_Gargant%C3%A1ns]"}]'::jsonb),
    ('cff3c769-e793-40f3-897c-4b085cdf9b56'::uuid, 'card_description', 'Ali Murad Mound lies 20 miles southwest of Dadu. At its top, an ancient hamlet was found ringed by defensive walls of stone blocks, and N. G. Majumdar explored and named the site.', 'A Harappan-era mound from 3300-1300 BC with a hamlet surrounded by stone defensive walls. Pottery, copper objects, and figurines of bulls and birds were found inside.', 'teaser-card-s015-rollback:cff3c769-e793-40f3-897c-4b085cdf9b56:card_description', 'rollback of teaser-card-s015: card_description ''A Harappan-era mound from 3300-1300 BC with a hamlet surrounded by stone defensive walls. Pottery, copper objects, and figurines of bulls and birds were found inside.'' restored on Ali Murad Mound', '8032e297483bc2ef791b89be93380d8477e31fe5fa347f91acadd1db491d5ef9|5c73a216f6c6663bb1201bbae37803270a5a954989f25c50cb8178212e7fb4ed|5c73a216f6c6663bb1201bbae37803270a5a954989f25c50cb8178212e7fb4ed', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ali Murad Mound lies 20 miles southwest of Dadu. At its top, an ancient hamlet was found ringed by defensive walls of stone blocks, and N. G. Majumdar explored and named the site."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ali Murad Mound lies 20 miles from Dadu, to the southwest [S3]; an ancient hamlet was found at the top of the mound [S5]; the hamlet was surrounded (ringed) by defensive walls [S5]; the defensive walls were built of stone blocks [S5]; N. G. Majumdar explored the site [S2]; N. G. Majumdar named the site [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ali Murad Mound is an archaeological site (a mound) in Dadu District, Sindh, Pakistan (the kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Ali_Murad_Mound]; The mound lies 20 miles from Dadu [SUPPORTED: https://en.wikipedia.org/wiki/Ali_Murad_Mound]; The mound lies southwest of Dadu [SUPPORTED: https://en.wikipedia.org/wiki/Ali_Murad_Mound]; At the top of the mound an ancient hamlet was found [SUPPORTED: https://en.wikipedia.org/wiki/Ali_Murad_Mound]; The hamlet was ringed by defensive walls [SUPPORTED: https://en.wikipedia.org/wiki/Ali_Murad_Mound]; The defensive walls were built of stone blocks [SUPPORTED: https://en.wikipedia.org/wiki/Ali_Murad_Mound]; N. G. Majumdar explored the site [SUPPORTED: https://en.wikipedia.org/wiki/Ali_Murad_Mound]; N. G. Majumdar named the site [SUPPORTED: https://en.wikipedia.org/wiki/Ali_Murad_Mound]"}]'::jsonb),
    ('d0e007ba-24cd-4929-b135-0b907397e531'::uuid, 'card_description', 'Two round cairns joined by a bank form Long Low, a layout unique in England. In 1849 its limestone burial chamber gave up the bones of thirteen people and three leaf-shaped flint arrowheads.', 'The bones of thirteen individuals were recovered as well as three leaf-shaped flint arrowheads.', 'teaser-card-s015-rollback:d0e007ba-24cd-4929-b135-0b907397e531:card_description', 'rollback of teaser-card-s015: card_description ''The bones of thirteen individuals were recovered as well as three leaf-shaped flint arrowheads.'' restored on Long Low, Wetton', '3bc394c52ed7cf515983e1a62e7f2cdcd4051e460848a07b78e5455af75cb33a|7d89b5c3ce5a4a6d78dd4b86a26d02258846e97a25cbf41ad4c8dfb0ad7582a9|7d89b5c3ce5a4a6d78dd4b86a26d02258846e97a25cbf41ad4c8dfb0ad7582a9', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Two round cairns joined by a bank form Long Low, a layout unique in England. In 1849 its limestone burial chamber gave up the bones of thirteen people and three leaf-shaped flint arrowheads."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Long Low consists of two round cairns [S3]; the two cairns are joined by a bank [S3]; the layout is unique in England [S3]; the excavation took place in 1849 [S5]; the excavation found a limestone burial chamber [S6]; the bones of thirteen people were recovered [S7]; three leaf-shaped flint arrowheads were recovered [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Long Low, Wetton is a Neolithic and Bronze Age burial-cairn site in England (Staffordshire, near Wetton) (central claim: a cairn/barrow site) [SUPPORTED: https://en.wikipedia.org/wiki/Long_Low,_Wetton]; Long Low consists of two round cairns joined by a bank [SUPPORTED: https://en.wikipedia.org/wiki/Long_Low,_Wetton]; The layout is unique in England [SUPPORTED: https://en.wikipedia.org/wiki/Long_Low,_Wetton]; The site was excavated in 1849 [SUPPORTED: https://en.wikipedia.org/wiki/Long_Low,_Wetton]; It has a limestone burial chamber [SUPPORTED: https://en.wikipedia.org/wiki/Long_Low,_Wetton]; The chamber yielded the bones of thirteen people [SUPPORTED: https://en.wikipedia.org/wiki/Long_Low,_Wetton]; It also yielded three leaf-shaped flint arrowheads [SUPPORTED: https://en.wikipedia.org/wiki/Long_Low,_Wetton]"}]'::jsonb),
    ('d1a6a883-779d-47eb-8496-78fbb360ddd6'::uuid, 'card_description', 'In the Callejón de Huaylas valley, Guitarrero Cave held some of South America''s earliest cultivated plants, with evidence of human use around 8,000 BCE and possibly as early as 10,560 BCE.', 'Guitarrero Cave has evidence of human use around 8,000 BCE and possibly as early as 10,560 BCE.', 'teaser-card-s015-rollback:d1a6a883-779d-47eb-8496-78fbb360ddd6:card_description', 'rollback of teaser-card-s015: card_description ''Guitarrero Cave has evidence of human use around 8,000 BCE and possibly as early as 10,560 BCE.'' restored on Guitarrero Cave', 'c88c34f0d1fa9c52b826d976b1f9a6c828e84a4a20ec106d544aec4861d5e886|9743cf86b1cd190f8f02538c5a00a351018bd5d465df8f7652e2dde3f32ecc86|9743cf86b1cd190f8f02538c5a00a351018bd5d465df8f7652e2dde3f32ecc86', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the Callejón de Huaylas valley, Guitarrero Cave held some of South America''s earliest cultivated plants, with evidence of human use around 8,000 BCE and possibly as early as 10,560 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the cave lies in the Callejón de Huaylas valley [S1]; some of South America''s earliest cultivated plants were found in the cave [S3]; there is evidence of human use around 8,000 BCE [S2]; human use is possibly as early as 10,560 BCE [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Guitarrero Cave is a cave site in the Callejón de Huaylas valley, Peru (central claim: a cave, located in that valley) [SUPPORTED: https://en.wikipedia.org/wiki/Guitarrero_Cave]; Guitarrero Cave held some of South America''s earliest cultivated plants [SUPPORTED: https://en.wikipedia.org/wiki/Guitarrero_Cave]; Guitarrero Cave has evidence of human use around 8,000 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Guitarrero_Cave]; Evidence of human use at Guitarrero Cave is possibly as early as 10,560 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Guitarrero_Cave]"}]'::jsonb),
    ('d1bb188e-07a5-4b2d-9624-65a918e88435'::uuid, 'card_description', 'Built on the Stanegate before Hadrian''s Wall, the Roman fort of Magnis kept a 2-foot-long iron spearhead 36 feet down a well. It also gave up the modius, a bronze grain-measure.', 'A Roman fort predating Hadrian''s Wall itself, originally built for the Stanegate road. Unusually, the Wall''s defensive ditch curves around it rather than running through it.', 'teaser-card-s015-rollback:d1bb188e-07a5-4b2d-9624-65a918e88435:card_description', 'rollback of teaser-card-s015: card_description "A Roman fort predating Hadrian''s Wall itself, originally built for the Stanegate road. Unusually, the Wall''s defensive ditch curves around it rather than running through it." restored on Magnis, Carvoran', 'f8804107ab7eb45a598f43791b932e06872ecd7ab88808d13fc8018127ea5dc5|28e785544b266f776f7c108cb9bf99b880cf3e75e9c9169b38dce694f8a3fb54|28e785544b266f776f7c108cb9bf99b880cf3e75e9c9169b38dce694f8a3fb54', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Built on the Stanegate before Hadrian''s Wall, the Roman fort of Magnis kept a 2-foot-long iron spearhead 36 feet down a well. It also gave up the modius, a bronze grain-measure."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the fort was built on the Stanegate [S3]; it was built before Hadrian''s Wall [S3]; Magnis was a Roman fort [S1]; a 2-foot-long iron spearhead was found [S8]; the spearhead lay 36 feet down in a well [S8]; the modius, a bronze grain-measure, was recovered [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Magnis (Carvoran) is a Roman fort (central claim: a fort, at Carvoran, England) [SUPPORTED: https://en.wikipedia.org/wiki/Magnis_(Carvoran)]; The fort was built on the Stanegate [SUPPORTED: https://en.wikipedia.org/wiki/Magnis_(Carvoran)]; The fort was built before Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Magnis_(Carvoran)]; An iron spearhead was recovered at Magnis [SUPPORTED: https://en.wikipedia.org/wiki/Magnis_(Carvoran)]; The spearhead is 2 feet long [SUPPORTED: https://en.wikipedia.org/wiki/Magnis_(Carvoran)]; The spearhead was found 36 feet down in a well [SUPPORTED: https://en.wikipedia.org/wiki/Magnis_(Carvoran)]; Magnis also gave up the modius, a bronze grain-measure [SUPPORTED: https://en.wikipedia.org/wiki/Magnis_(Carvoran)]"}]'::jsonb),
    ('d2575f3f-5a83-4e7a-8e7c-d3325602aee5'::uuid, 'card_description', 'Maya builders laid mostly black slate blocks without mortar in the Lubaantun Archaeological Reserve. The city''s ancient name is unknown; its modern Maya name means place of fallen stones.', 'A Late Classic Maya city from 730-890 AD built entirely of dry-laid stone blocks with no mortar. Its unusual black slate construction sets it apart from every other Maya site.', 'teaser-card-s015-rollback:d2575f3f-5a83-4e7a-8e7c-d3325602aee5:card_description', 'rollback of teaser-card-s015: card_description ''A Late Classic Maya city from 730-890 AD built entirely of dry-laid stone blocks with no mortar. Its unusual black slate construction sets it apart from every other Maya site.'' restored on Lubaantun Archaeological Reserve', 'fa18fec694d0f39ea675913b40ead08a65eccb110d559480911e1d1bb58151c0|7b55d5f9165c89d5a0ec16b370d0a09fa0003b6ef4e6bc1a2a34c02737116d71|7b55d5f9165c89d5a0ec16b370d0a09fa0003b6ef4e6bc1a2a34c02737116d71', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Maya builders laid mostly black slate blocks without mortar in the Lubaantun Archaeological Reserve. The city''s ancient name is unknown; its modern Maya name means place of fallen stones."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the builders were Maya [S1]; the structures are mostly built of black slate blocks [S5]; the blocks are laid without mortar [S5]; the site is the Lubaantun Archaeological Reserve (site name) [S1]; the city''s ancient name is unknown [S6]; its modern Maya name means place of fallen stones [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Lubaantun is a Maya city (ruined city of the Maya civilization) in Belize (central claim: a Maya city, in southern Belize) [SUPPORTED: https://en.wikipedia.org/wiki/Lubaantun]; Lubaantun''s builders were Maya [SUPPORTED: https://en.wikipedia.org/wiki/Lubaantun]; Lubaantun''s structures are mostly built of black slate blocks [SUPPORTED: https://en.wikipedia.org/wiki/Lubaantun]; The blocks were laid without mortar [SUPPORTED: https://en.wikipedia.org/wiki/Lubaantun]; The city''s ancient name is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Lubaantun]; The modern Maya name Lubaantun means place of fallen stones [SUPPORTED: https://en.wikipedia.org/wiki/Lubaantun]; The site is an archaeological reserve (Lubaantun Archaeological Reserve) [SUPPORTED: https://en.wikipedia.org/wiki/List_of_protected_areas_of_Belize]"}]'::jsonb),
    ('d2cffaa4-e1cb-4b2e-9907-76abf47411d1'::uuid, 'card_description', 'Near Naga el-Ghoneimeya, the Edfu South Pyramid, a step pyramid now about 4.9 metres high, sits slightly off true north to run parallel to the Nile. Its builder and purpose are unknown.', '2670-2610 BC step pyramid south of Edfu, one of seven near-identical small pyramids built far from Egypt''s main centres. Builders and purpose remain essentially unknown.', 'teaser-card-s015-rollback:d2cffaa4-e1cb-4b2e-9907-76abf47411d1:card_description', 'rollback of teaser-card-s015: card_description "2670-2610 BC step pyramid south of Edfu, one of seven near-identical small pyramids built far from Egypt''s main centres. Builders and purpose remain essentially unknown." restored on Edfu South Pyramid', '0900e8fa27f0c3b93b7656492e34ccb19cc46f1ec43fe0e4261e1280052a4839|2b16e77a4d7a709c953bc1ddd93d3529461a1d952f0040deaa0e3c82c6ce38dd|2b16e77a4d7a709c953bc1ddd93d3529461a1d952f0040deaa0e3c82c6ce38dd', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Naga el-Ghoneimeya, the Edfu South Pyramid, a step pyramid now about 4.9 metres high, sits slightly off true north to run parallel to the Nile. Its builder and purpose are unknown."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the pyramid is near Naga el-Ghoneimeya [S2]; it is a step pyramid [S1]; it is now about 4.9 metres high [S4]; it is oriented slightly off true north [S6]; it is oriented parallel to the Nile [S6]; its builder is unknown [S7]; its purpose is unknown [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Edfu South Pyramid is a step pyramid (central claim: a pyramid, near Naga el-Ghoneimeya in Egypt) [SUPPORTED: https://en.wikipedia.org/wiki/Edfu_South_pyramid]; It is located near Naga el-Ghoneimeya [SUPPORTED: https://en.wikipedia.org/wiki/Edfu_South_pyramid]; The pyramid is now about 4.9 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Edfu_South_pyramid]; The pyramid sits slightly off true north [SUPPORTED: https://en.wikipedia.org/wiki/Edfu_South_pyramid]; It is oriented off true north in order to run parallel to the Nile [SUPPORTED: https://en.wikipedia.org/wiki/Edfu_South_pyramid]; The builder of the pyramid is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Edfu_South_pyramid]; The purpose of the pyramid is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Edfu_South_pyramid]"}]'::jsonb),
    ('d2dd6e95-7f9a-4d6c-bd8e-a00f39d1f1f5'::uuid, 'card_description', 'A belt of 36 carnelian beads and small terracotta jars brimming with gold and silver ornaments came from Allahdino, a Harappan village east of Karachi abandoned by circa 2000 BCE.', 'A tiny 1.4-hectare Harappan settlement from 3300-2000 BC, abandoned abruptly. Despite its small size, a treasure of gold and silver jewelry was found in one house.', 'teaser-card-s015-rollback:d2dd6e95-7f9a-4d6c-bd8e-a00f39d1f1f5:card_description', 'rollback of teaser-card-s015: card_description ''A tiny 1.4-hectare Harappan settlement from 3300-2000 BC, abandoned abruptly. Despite its small size, a treasure of gold and silver jewelry was found in one house.'' restored on Allahdino', 'be80747a323e156685b90d2361cf5215a416acca418660a6f39ba34973482d71|672b3395928bf57743750959d1106ecffd8b1a41505509b04144f01cf6d54395|672b3395928bf57743750959d1106ecffd8b1a41505509b04144f01cf6d54395', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "A belt of 36 carnelian beads and small terracotta jars brimming with gold and silver ornaments came from Allahdino, a Harappan village east of Karachi abandoned by circa 2000 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "a belt with 36 carnelian beads was found [S8]; small terracotta jars with profusions of gold and silver ornaments were found [S7]; the finds came from Allahdino [S7, S8]; Allahdino is a Harappan village [S1]; it lies east of Karachi [S1]; it was abandoned by circa 2000 BCE [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Allahdino is a Harappan village (central claim: a small village/settlement of the Harappan period) [SUPPORTED: https://en.wikipedia.org/wiki/Allahdino]; Allahdino lies east of Karachi [SUPPORTED: https://en.wikipedia.org/wiki/Allahdino]; Allahdino was abandoned by circa 2000 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Allahdino]; A belt of 36 carnelian beads came from Allahdino [SUPPORTED: https://en.wikipedia.org/wiki/Allahdino]; Small terracotta jars came from Allahdino, with profusions of gold and silver ornaments [SUPPORTED: https://en.wikipedia.org/wiki/Allahdino]; A jar from Allahdino held gold and silver ornaments [SUPPORTED: https://en.wikipedia.org/wiki/Allahdino]"}]'::jsonb),
    ('d34a4c75-f3e7-42e8-accb-1e2329dc27fa'::uuid, 'card_description', 'Over 9 kilometres of ditches and ramparts form the Stanwick Iron Age Fortifications, where Wheeler found an Iron Age sword in its ash wood scabbard and, nearby, the skull of a severed head.', 'Over 9 km of ditches and ramparts enclosing 300 hectares, built in the early Roman era. Venutius or Cartimandua — or both before their split after 51 AD — held this North Yorkshire stronghold.', 'teaser-card-s015-rollback:d34a4c75-f3e7-42e8-accb-1e2329dc27fa:card_description', 'rollback of teaser-card-s015: card_description ''Over 9 km of ditches and ramparts enclosing 300 hectares, built in the early Roman era. Venutius or Cartimandua — or both before their split after 51 AD — held this North Yorkshire stronghold.'' restored on Stanwick Iron Age Fortifications', '54785a97c45070d785c5cb4cc17b7b7b89db81bc47defa49f51e0d0e11c65db6|ddd23ca96cf90df64552d184cadb59fc485bf283fcd7322da674a609f7ad0079|ddd23ca96cf90df64552d184cadb59fc485bf283fcd7322da674a609f7ad0079', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Over 9 kilometres of ditches and ramparts form the Stanwick Iron Age Fortifications, where Wheeler found an Iron Age sword in its ash wood scabbard and, nearby, the skull of a severed head."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the fortifications comprise over 9 kilometres of ditches and ramparts [S1]; the site is the Stanwick Iron Age Fortifications [S1]; Wheeler found an Iron Age sword [S5, S6]; the sword was still in its ash wood scabbard [S6]; the skull of a severed head was found nearby [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Stanwick Iron Age Fortifications are a huge Iron Age hill fort (sometimes considered an oppidum) in Richmondshire, North Yorkshire, England - a fortified site [SUPPORTED: https://en.wikipedia.org/wiki/Stanwick_Iron_Age_Fortifications]; The fortifications consist of ditches and ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Stanwick_Iron_Age_Fortifications]; The ditches and ramparts measure over 9 kilometres [SUPPORTED: https://en.wikipedia.org/wiki/Stanwick_Iron_Age_Fortifications]; Wheeler (Sir Mortimer Wheeler, excavating 1951-52) found an Iron Age sword at Stanwick [SUPPORTED: https://en.wikipedia.org/wiki/Stanwick_Iron_Age_Fortifications]; The Iron Age sword was still in its ash wood scabbard [SUPPORTED: https://en.wikipedia.org/wiki/Stanwick_Iron_Age_Fortifications]; Wheeler also found, nearby, the skull of a severed head [SUPPORTED: https://en.wikipedia.org/wiki/Stanwick_Iron_Age_Fortifications]"}]'::jsonb),
    ('d56cc124-8502-45b8-8fc6-b7dc59d02e43'::uuid, 'card_description', 'On the western bank of the Mur, Vespasian made Flavia Solva a municipium around year 70. First destroyed in 166, it rose again under Commodus and a few decades later flourished once more.', 'The only Roman city in Styria, elevated to municipium status under Emperor Vespasian. It grew from a Celto-Roman settlement on the Mur river into a fully planned Roman town.', 'teaser-card-s015-rollback:d56cc124-8502-45b8-8fc6-b7dc59d02e43:card_description', 'rollback of teaser-card-s015: card_description ''The only Roman city in Styria, elevated to municipium status under Emperor Vespasian. It grew from a Celto-Roman settlement on the Mur river into a fully planned Roman town.'' restored on Flavia Solva', 'ed24ebe495774ae3d573538ddf0a813dd3cb24737bef6d587fc954c094a3808d|f79185d7f5ecb94417aa0f5f3d9ece5a71862cccb3ca032574213d60600c8f72|f79185d7f5ecb94417aa0f5f3d9ece5a71862cccb3ca032574213d60600c8f72', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the western bank of the Mur, Vespasian made Flavia Solva a municipium around year 70. First destroyed in 166, it rose again under Commodus and a few decades later flourished once more."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lay on the western bank of the Mur [S2]; Vespasian made Flavia Solva a municipium [S3]; this happened around year 70 [S3]; it was first destroyed in 166 [S4]; it was rebuilt under Commodus [S5]; a few decades later it flourished again [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Flavia Solva was a Roman municipium (town) in the province of Noricum, in Styria, Austria [SUPPORTED: https://en.wikipedia.org/wiki/Flavia_Solva]; Flavia Solva lay on the western bank of the Mur river [SUPPORTED: https://en.wikipedia.org/wiki/Flavia_Solva]; Vespasian made Flavia Solva a municipium (raised the settlement to a town named after the Flavian family) [SUPPORTED: https://de.wikipedia.org/wiki/Flavia_Solva]; The municipium was made around the year 70 [SUPPORTED: https://en.wikipedia.org/wiki/Flavia_Solva]; Flavia Solva was first destroyed in 166 [SUPPORTED: https://en.wikipedia.org/wiki/Flavia_Solva]; The city was rebuilt (rose again) under Commodus [SUPPORTED: https://en.wikipedia.org/wiki/Flavia_Solva]; A few decades after the rebuilding the city flourished once more [SUPPORTED: https://en.wikipedia.org/wiki/Flavia_Solva]"}]'::jsonb),
    ('d6665022-2763-44cd-8963-d6fb7d4cfc52'::uuid, 'card_description', 'Near Winchester, the Flowerdown Barrows keep a Bronze Age disc barrow 28 metres in diameter, described as the finest in Hampshire, a hollow at the heart of its larger central mound.', 'Three Bronze Age burial mounds including a disc barrow described as "the finest in Hampshire" — 28 metres across, containing two smaller mounds within its perimeter ditch.', 'teaser-card-s015-rollback:d6665022-2763-44cd-8963-d6fb7d4cfc52:card_description', 'rollback of teaser-card-s015: card_description ''Three Bronze Age burial mounds including a disc barrow described as "the finest in Hampshire" — 28 metres across, containing two smaller mounds within its perimeter ditch.'' restored on Flowerdown Barrows', '87ba237119f082011878dd3684abe1da61b17dd188c164c9bb72818ef975b0c9|2094c3b27b08703db2a676f0fabccc2821beb478ef68c4031e25e66a1202ef0b|2094c3b27b08703db2a676f0fabccc2821beb478ef68c4031e25e66a1202ef0b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Winchester, the Flowerdown Barrows keep a Bronze Age disc barrow 28 metres in diameter, described as the finest in Hampshire, a hollow at the heart of its larger central mound."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is near Winchester [S1]; it has a Bronze Age disc barrow [S2]; the disc barrow is 28 metres in diameter [S3]; the disc barrow has been described as the finest in Hampshire [S2]; its larger mound is centrally positioned [S4]; that larger mound has a central hollow [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Flowerdown Barrows are a barrow (burial mound) site near Winchester, Hampshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Flowerdown_Barrows]; The barrows date to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Flowerdown_Barrows]; The site keeps a disc barrow [SUPPORTED: https://en.wikipedia.org/wiki/Flowerdown_Barrows]; The disc barrow is described as the finest in Hampshire [SUPPORTED: https://en.wikipedia.org/wiki/Flowerdown_Barrows]; The disc barrow is 28 metres in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Flowerdown_Barrows]; The disc barrow contains two circular mounds [SUPPORTED: https://en.wikipedia.org/wiki/Flowerdown_Barrows]; The larger of the two mounds is centrally positioned in the disc barrow [SUPPORTED: https://en.wikipedia.org/wiki/Flowerdown_Barrows]; The larger central mound has a hollow at its heart [SUPPORTED: https://en.wikipedia.org/wiki/Flowerdown_Barrows]"}]'::jsonb),
    ('d6ea97bd-2ddb-4065-961a-1e2c8d6a2a3b'::uuid, 'card_description', 'Beside the Nakhchivanchay river, Kultepe-2 rests on an Early Bronze Age layer 7–10 m thick. Remains of circular brick buildings, large painted containers and bronze tools were found.', 'A Kura-Araxes settlement from 3500-2400 BC with circular brick buildings. Cultural layers reach 7-10 metres deep -- evidence of long continuous habitation.', 'teaser-card-s015-rollback:d6ea97bd-2ddb-4065-961a-1e2c8d6a2a3b:card_description', 'rollback of teaser-card-s015: card_description ''A Kura-Araxes settlement from 3500-2400 BC with circular brick buildings. Cultural layers reach 7-10 metres deep -- evidence of long continuous habitation.'' restored on Kultepe-2', '6710d2ffd98e7d04370c3109a5550db70f342304a2c17c7c678ddc1dc175e4b8|4222a055cae07a11ce6fd4be9b4bcca9757f034a0a2328911a82571d16f65e60|4222a055cae07a11ce6fd4be9b4bcca9757f034a0a2328911a82571d16f65e60', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Beside the Nakhchivanchay river, Kultepe-2 rests on an Early Bronze Age layer 7–10 m thick. Remains of circular brick buildings, large painted containers and bronze tools were found."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kultepe-2 lies beside the Nakhchivanchay river [S2]; its earliest layer dates to the Early Bronze Age [S3]; that layer is 7-10 m thick [S3]; remains of circular brick buildings were found [S4]; large painted containers were found [S8]; bronze tools were found [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kultepe-2 is an ancient (Bronze Age) settlement in Nakhchivan, Azerbaijan [SUPPORTED: https://en.wikipedia.org/wiki/Kultepe-2]; Kultepe-2 lies beside the Nakhchivanchay river (on its west bank) [SUPPORTED: https://en.wikipedia.org/wiki/Kultepe-2]; The site rests on an Early Bronze Age layer [SUPPORTED: https://en.wikipedia.org/wiki/Kultepe-2]; That Early Bronze Age layer is 7-10 m thick [SUPPORTED: https://en.wikipedia.org/wiki/Kultepe-2]; Remains of circular brick buildings were found (in that earliest, Early Bronze Age layer) [SUPPORTED: https://en.wikipedia.org/wiki/Kultepe-2]; Large painted containers were found at Kultepe-2 (Wikipedia assigns them to the second, 2nd-millennium layer, not to the Early Bronze Age layer; the card text does not say which layer) [SUPPORTED: https://en.wikipedia.org/wiki/Kultepe-2]; Bronze tools were found at Kultepe-2 (Wikipedia assigns them to the second, 2nd-millennium layer, not to the Early Bronze Age layer; the card text does not say which layer) [SUPPORTED: https://en.wikipedia.org/wiki/Kultepe-2]"}]'::jsonb),
    ('d7e1cd9a-7861-459a-8454-5631dbbadf8b'::uuid, 'card_description', 'Slim passages lead through the Grotte de Gabillou to more than 200 ornaments, among them The Sorcerer: a horned and bearded man-like figure with a leg and foot like a human''s.', 'A cave containing 12,000-year-old Paleolithic engravings, accessible only through a basement room. The entrance is not disclosed to the public — it remains on private land.', 'teaser-card-s015-rollback:d7e1cd9a-7861-459a-8454-5631dbbadf8b:card_description', 'rollback of teaser-card-s015: card_description ''A cave containing 12,000-year-old Paleolithic engravings, accessible only through a basement room. The entrance is not disclosed to the public — it remains on private land.'' restored on Grotte de Gabillou', '5fe23651946434d092955ad446bd5845bf07cd81ebd3bfdb29bc28eff56cb440|f56e301ceee5c6c7a2504de5097864539fd951f6692870bac76dd523336c455b|f56e301ceee5c6c7a2504de5097864539fd951f6692870bac76dd523336c455b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Slim passages lead through the Grotte de Gabillou to more than 200 ornaments, among them The Sorcerer: a horned and bearded man-like figure with a leg and foot like a human''s."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the cave has slim passages [S6]; the cave contains more than 200 ornaments [S7]; one of them is known as The Sorcerer [S8]; The Sorcerer is a horned and bearded man-like figure [S8]; it has a leg and foot like a human''s [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Grotte de Gabillou is a cave in France (Sourzac, Dordogne) with prehistoric (Palaeolithic) ornaments, i.e. an engraved cave [SUPPORTED: https://en.wikipedia.org/wiki/Grotte_de_Gabillou]; The cave has slim passages (50 to 60 cm wide) [SUPPORTED: https://en.wikipedia.org/wiki/Grotte_de_Gabillou]; The cave holds more than 200 ornaments (the ''ornaments'' are engravings: French Wikipedia says more than 200 engravings) [SUPPORTED: https://fr.wikipedia.org/wiki/Grotte_de_Gabillou]; Among the ornaments is one known as The Sorcerer [SUPPORTED: https://en.wikipedia.org/wiki/Grotte_de_Gabillou]; The Sorcerer is a horned and bearded man-like figure [SUPPORTED: https://en.wikipedia.org/wiki/Grotte_de_Gabillou]; The Sorcerer has a leg and foot like a human''s [SUPPORTED: https://en.wikipedia.org/wiki/Grotte_de_Gabillou]"}]'::jsonb),
    ('d8256f75-7b93-49b5-8910-801bd1591397'::uuid, 'card_description', 'On a grave mound above the Valdres valley, the Einang Stone bears Elder Futhark runes dated to the 4th century, the oldest runestone still standing at its original location.', 'A 4th-century Elder Futhark runestone stands on a grave mound above the Valdres valley, protected under glass. Nearby cairns form the broader Gardberg burial complex.', 'teaser-card-s015-rollback:d8256f75-7b93-49b5-8910-801bd1591397:card_description', 'rollback of teaser-card-s015: card_description ''A 4th-century Elder Futhark runestone stands on a grave mound above the Valdres valley, protected under glass. Nearby cairns form the broader Gardberg burial complex.'' restored on Einang Stone', '90e6f03c0622b707d0b2634466505e8934f8869316c49202a623bf78106d4596|e96aa00d681c382aabec764f761b22d00fe2220be5d7f7dc0b710f25c6bbff85|e96aa00d681c382aabec764f761b22d00fe2220be5d7f7dc0b710f25c6bbff85', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a grave mound above the Valdres valley, the Einang Stone bears Elder Futhark runes dated to the 4th century, the oldest runestone still standing at its original location."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the stone stands on a grave mound [S4]; the mound lies above (overlooking) the Valdres valley [S4]; the Einang Stone bears Elder Futhark runes [S5]; the inscription is dated to the 4th century [S5]; it is the oldest runestone still standing at its original location [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Einang Stone is a runestone [SUPPORTED: https://en.wikipedia.org/wiki/Einang_stone]; The stone stands on a grave mound [SUPPORTED: https://en.wikipedia.org/wiki/Einang_stone]; The grave mound lies above (overlooks) the Valdres valley [SUPPORTED: https://en.wikipedia.org/wiki/Einang_stone]; The stone bears Elder Futhark runes [SUPPORTED: https://en.wikipedia.org/wiki/Einang_stone]; The runic inscription is dated to the 4th century [SUPPORTED: https://en.wikipedia.org/wiki/Einang_stone]; It is the oldest runestone still standing at its original location [SUPPORTED: https://en.wikipedia.org/wiki/Einang_stone]"}]'::jsonb),
    ('d8cae4fd-fcca-4187-9194-e89fa474bb49'::uuid, 'card_description', 'Near Valldemossa, on Mallorca''s north-west facing coast, Son Oleza keeps a nearly complete prehistoric village: houses, a Beaker culture dolmen and even a water supply system.', '2500-1300 BC Beaker culture dolmen and associated settlement on the north-west facing coast near Valldemossa. Excavations by Professor Bill Waldren revealed a nearly complete prehistoric settlement.', 'teaser-card-s015-rollback:d8cae4fd-fcca-4187-9194-e89fa474bb49:card_description', 'rollback of teaser-card-s015: card_description ''2500-1300 BC Beaker culture dolmen and associated settlement on the north-west facing coast near Valldemossa. Excavations by Professor Bill Waldren revealed a nearly complete prehistoric settlement.'' restored on Son Oleza', 'd9c6bb9531437c9e0edf080e96ea97db0935903e3454a20996ecd96e076ce516|fbf5631c29ef3b3bafe3720a2cb50d771f2c96e0774b34b80bdad6e30de776a8|fbf5631c29ef3b3bafe3720a2cb50d771f2c96e0774b34b80bdad6e30de776a8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Valldemossa, on Mallorca''s north-west facing coast, Son Oleza keeps a nearly complete prehistoric village: houses, a Beaker culture dolmen and even a water supply system."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is near Valldemossa [S2]; it lies on Mallorca''s north-west facing coast [S1, S2]; it holds a nearly complete village [S4]; the village is prehistoric [S1]; it has houses [S5]; it has a dolmen of the Beaker culture [S1, S5]; it has a water supply system [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Son Oleza is a prehistoric settlement site with a dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]; The site is on the island of Mallorca [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]; It lies near the village of Valldemossa [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]; It lies on Mallorca''s north-west facing coast [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]; The site is a nearly complete prehistoric village [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]; The site has houses [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]; The site has a dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]; The dolmen belongs to the Beaker culture [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]; The site has a water supply system [SUPPORTED: https://en.wikipedia.org/wiki/Son_Oleza]"}]'::jsonb),
    ('d9d26446-9348-4f16-b5e4-c4c11e8ccffb'::uuid, 'card_description', 'Above Creiro Beach in the Arrábida Natural Park, the Roman Ruins of Creiro keep baths and a fish-salting factory, its salted fish and fish sauces exported throughout the Empire in amphorae.', 'Ruins of a Roman fish-salting factory and baths from the 1st century AD. Garum production was big business — the Roman appetite for fish sauce was enormous.', 'teaser-card-s015-rollback:d9d26446-9348-4f16-b5e4-c4c11e8ccffb:card_description', 'rollback of teaser-card-s015: card_description ''Ruins of a Roman fish-salting factory and baths from the 1st century AD. Garum production was big business — the Roman appetite for fish sauce was enormous.'' restored on Roman Ruins of Creiro', '0d9d6712357d93f222c965c9d96a0836142b230ffa701fbe1be422789706eecc|ae4ccb6f03bbed8bfd15e367c2e81ad6be109a1fa94a9cc8c1da3b6a3e6c8918|ae4ccb6f03bbed8bfd15e367c2e81ad6be109a1fa94a9cc8c1da3b6a3e6c8918', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above Creiro Beach in the Arrábida Natural Park, the Roman Ruins of Creiro keep baths and a fish-salting factory, its salted fish and fish sauces exported throughout the Empire in amphorae."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the ruins lie above Creiro Beach [S1]; they lie in the Arrábida Natural Park [S1]; the ruins include baths [S2]; the ruins include a fish-salting factory [S2]; the factory produced salted fish and fish sauces [S3]; such salted fish and fish sauces were exported throughout the Empire [S3]; they were exported in amphorae [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Ruins of Creiro are the ruins of a Roman fish-salting site with baths [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]; The ruins lie above Creiro Beach [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]; The ruins lie in the Arrábida Natural Park (Portugal) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]; The site keeps Roman baths [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]; The site keeps a fish-salting factory [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]; The factory produced salted fish [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]; The factory produced fish sauces [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]; Its salted fish and fish sauces were exported throughout the Roman Empire [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]; The exports were shipped in amphorae [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Creiro]"}]'::jsonb),
    ('d9d2906b-4528-42af-9796-678ddf7ed30e'::uuid, 'card_description', 'On Anglesey, a grassy bank still some 1.5 metres high rings a level area some 54 metres in diameter: Castell Bryn Gwyn, White Hill Castle, maybe a Neolithic henge, walled in the Iron Age.', NULL, 'teaser-card-s015-rollback:d9d2906b-4528-42af-9796-678ddf7ed30e:card_description', 'rollback of teaser-card-s015: card_description None restored on Castell Bryn Gwyn', 'c3cf0e6c70bb2dc4a83213775d726db9925df12fb73853cad4230a6beae1b605|2c94c93de6876678485fece508af2413f233fe77ba48c5a29f5956bda27596a9|2c94c93de6876678485fece508af2413f233fe77ba48c5a29f5956bda27596a9', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Anglesey, a grassy bank still some 1.5 metres high rings a level area some 54 metres in diameter: Castell Bryn Gwyn, White Hill Castle, maybe a Neolithic henge, walled in the Iron Age."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is on Anglesey [S1]; a grass-covered bank [S2]; the bank is still some 1.5 metres high [S2]; the bank rings a level area some 54 metres in diameter [S2]; the name means White Hill Castle [S3]; it may have been a Neolithic henge [S4]; it was walled in the Iron Age [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Castell Bryn Gwyn is a prehistoric site (a circular bank enclosure) on Anglesey [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Bryn_Gwyn]; The bank is covered with grass [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Bryn_Gwyn]; The bank is still some 1.5 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Bryn_Gwyn]; The bank rings a level area [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Bryn_Gwyn]; The level area is some 54 metres in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Bryn_Gwyn]; The name Castell Bryn Gwyn means White Hill Castle [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Bryn_Gwyn]; The site may have been a Neolithic henge [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Bryn_Gwyn]; The site was walled in the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Bryn_Gwyn]"}]'::jsonb),
    ('dac7cdd2-495d-4410-b711-9d633c27c090'::uuid, 'card_description', 'Mostly of brick, the Caños de Carmona once ran 17.5 kilometres from a spring to Roman Hispalis, today Seville, and flowed until its demolition in 1912. Some sections still stand.', 'The aqueduct was constructed approximately between 68 and 65 BC, the same period as the construction of the Walls of Seville and during Julius Caesar''s term as quaestor.', 'teaser-card-s015-rollback:dac7cdd2-495d-4410-b711-9d633c27c090:card_description', 'rollback of teaser-card-s015: card_description "The aqueduct was constructed approximately between 68 and 65 BC, the same period as the construction of the Walls of Seville and during Julius Caesar''s term as quaestor." restored on Caños de Carmona', '4e19f408d68cfebeba742d5069aba6458c0ce06e508f171e998013dd6de0a616|6219acd58c84550518fd53e35419c3d6bfb856d415bc575bb115af4e83a51f78|6219acd58c84550518fd53e35419c3d6bfb856d415bc575bb115af4e83a51f78', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Mostly of brick, the Caños de Carmona once ran 17.5 kilometres from a spring to Roman Hispalis, today Seville, and flowed until its demolition in 1912. Some sections still stand."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the aqueduct was mostly of brick [S4]; it once ran 17.5 kilometres [S4]; it ran from a spring [S1]; it supplied Roman Hispalis, today Seville [S1]; it flowed (was operational) until its demolition in 1912 [S2]; some sections still stand [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Caños de Carmona is a Roman aqueduct [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1os_de_Carmona]; It was mostly built of brick [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1os_de_Carmona]; It was 17.5 kilometres long [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1os_de_Carmona]; It supplied water from a spring [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1os_de_Carmona]; It ran to Roman Hispalis, today Seville [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1os_de_Carmona]; It flowed until its demolition in 1912 [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1os_de_Carmona]; Some sections still stand [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1os_de_Carmona]"}]'::jsonb),
    ('dadbf949-f5cc-4313-9111-20224ebf9f43'::uuid, 'card_description', 'Ancient Greeks named it Pausílypon, respite from worry. On Posillipo the villa of Vedius Pollio keeps a 2000-seat theatre, and a 770 metre-long cave passes beneath the hill.', 'A Roman vacation district where elite villas lined the coast from the 1st century BC. An imperial pleasure villa and the Tunnel of Sejanus can still be visited today.', 'teaser-card-s015-rollback:dadbf949-f5cc-4313-9111-20224ebf9f43:card_description', 'rollback of teaser-card-s015: card_description ''A Roman vacation district where elite villas lined the coast from the 1st century BC. An imperial pleasure villa and the Tunnel of Sejanus can still be visited today.'' restored on Posillipo', '3f4f7c355057158faf8b9f692c774533521d74cc75a2c274f9f749f21fed9790|36f842897dbc80427163d57983ff0df45e5fb3245f7d8280029965fcc282e0e4|36f842897dbc80427163d57983ff0df45e5fb3245f7d8280029965fcc282e0e4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ancient Greeks named it Pausílypon, respite from worry. On Posillipo the villa of Vedius Pollio keeps a 2000-seat theatre, and a 770 metre-long cave passes beneath the hill."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the ancient Greeks named it Pausílypon [S3]; the name means respite from worry [S3]; the villa of Vedius Pollio lies on Posillipo [S4, S5]; the villa has a 2000-seat theatre [S5]; a 770 metre-long cave passes beneath the hill [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Posillipo is a place on the Bay of Naples, Italy, whose ancient remains are the Roman villa of Vedius Pollio (the Imperial Villa, Pausilypon) [SUPPORTED: https://en.wikipedia.org/wiki/Posillipo]; Posillipo lies at Naples in Italy [SUPPORTED: https://en.wikipedia.org/wiki/Posillipo]; Ancient Greeks named it Pausilypon, meaning respite from worry [SUPPORTED: https://en.wikipedia.org/wiki/Posillipo]; The villa of Vedius Pollio on Posillipo has a 2000-seat theatre [SUPPORTED: https://en.wikipedia.org/wiki/Posillipo]; A 770 metre-long cave passes beneath the Posillipo hill [SUPPORTED: https://en.wikipedia.org/wiki/Posillipo]"}]'::jsonb),
    ('dae23b93-8b4c-4e7c-961b-ca9bd54c4871'::uuid, 'card_description', 'On Trevelgue Head, three massive banks and ditches lie just before a gap crossed by a modern bridge. Over 4,000 shards of pottery and objects of tin, copper, iron and glass were found.', 'A headland near Newquay whose cliffs defend three sides naturally, with ramparts crossing the landward approach. Two Bronze Age round barrows predate the Iron Age fortifications here.', 'teaser-card-s015-rollback:dae23b93-8b4c-4e7c-961b-ca9bd54c4871:card_description', 'rollback of teaser-card-s015: card_description ''A headland near Newquay whose cliffs defend three sides naturally, with ramparts crossing the landward approach. Two Bronze Age round barrows predate the Iron Age fortifications here.'' restored on Trevelgue Head', '99c6de81cdecaa91750908a5a7dd62f7b141286378df917baff2bca9356bad2c|681787a17ebc32aa3e3c5015b153a688c0ce278c64da450e714dd77522ac9ba2|681787a17ebc32aa3e3c5015b153a688c0ce278c64da450e714dd77522ac9ba2', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Trevelgue Head, three massive banks and ditches lie just before a gap crossed by a modern bridge. Over 4,000 shards of pottery and objects of tin, copper, iron and glass were found."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "there are three massive banks and ditches on Trevelgue Head [S7]; the three banks and ditches lie immediately before a gap in the peninsula [S7]; the gap is crossed by a modern bridge [S7]; over 4,000 shards of pottery were found [S8]; objects of tin were found [S8]; objects of copper were found [S8]; objects of iron were found [S8]; objects of glass were found [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Trevelgue Head is the site of an Iron Age promontory fort with defensive banks and ditches (ramparts) [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; Trevelgue Head is a headland in England (Cornwall) [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; There is a gap in the headland crossed by a modern bridge [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; There are three massive banks and ditches [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; The three banks and ditches lie just before the gap [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; Over 4,000 shards of pottery were found [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; Objects of tin were found [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; Objects of copper were found [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; Objects of iron were found [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]; Objects of glass were found [SUPPORTED: https://en.wikipedia.org/wiki/Trevelgue_Head]"}]'::jsonb),
    ('dc789e55-ef9b-4d3e-8a82-075427def6ea'::uuid, 'card_description', 'About 20 kilometers from Ronda lie the ruins of Acinipo, a city believed to have been founded by retired soldiers of the Roman legions more than 2,000 years ago. Its theater is still in use.', 'Acinipo was a city about 20 kilometers from Ronda believed to have been founded by retired soldiers from the Roman legions more than 2,000 years ago.', 'teaser-card-s015-rollback:dc789e55-ef9b-4d3e-8a82-075427def6ea:card_description', 'rollback of teaser-card-s015: card_description ''Acinipo was a city about 20 kilometers from Ronda believed to have been founded by retired soldiers from the Roman legions more than 2,000 years ago.'' restored on Acinipo', 'f311911c750b5338bbd10320ffbe36c17a7f00b8cda1e30a22445baf42f981d0|d31df29eac8f19453684a0cfbf5a671b2e9081faf2d203a72efa1f8a2c0fa189|d31df29eac8f19453684a0cfbf5a671b2e9081faf2d203a72efa1f8a2c0fa189', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "About 20 kilometers from Ronda lie the ruins of Acinipo, a city believed to have been founded by retired soldiers of the Roman legions more than 2,000 years ago. Its theater is still in use."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is about 20 kilometers from Ronda [S1]; ruins of Acinipo remain [S2]; Acinipo was a city [S1]; it is believed to have been founded by retired soldiers of the Roman legions [S1]; the founding was more than 2,000 years ago [S1]; its theater is still in use [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Acinipo is the site of an ancient city (a ruined Roman city) in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Acinipo]; Ruins of Acinipo survive [SUPPORTED: https://en.wikipedia.org/wiki/Acinipo]; The ruins of Acinipo lie about 20 kilometers from Ronda [SUPPORTED: https://www.surinenglish.com/malaga/ronda/roman-theatre-acinipo-removed-from-risk-list-20230629151338-nt.html]; Acinipo is believed to have been founded by retired soldiers [SUPPORTED: https://en.wikipedia.org/wiki/Acinipo]; The soldiers were of the Roman legions [SUPPORTED: https://en.wikipedia.org/wiki/Acinipo]; The city was founded more than 2,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Acinipo]; The founding of Acinipo is not certain (the text says only ''believed'') [SUPPORTED: https://de.wikipedia.org/wiki/Acinipo]; The Roman theater at Acinipo is still in use [SUPPORTED: https://en.wikipedia.org/wiki/Acinipo]"}]'::jsonb),
    ('dc951bdb-a70d-4346-9e7d-fdc0d908d4c5'::uuid, 'card_description', 'On the south-west slope of Blackpatch Hill lie more than 64 infilled shafts of a Neolithic flint mine, galleries once reaching up to 8.5 metres along a single seam of flint.', 'The flint mine, which was levelled about 1950, is on the south-west slope of Blackpatch Hill.', 'teaser-card-s015-rollback:dc951bdb-a70d-4346-9e7d-fdc0d908d4c5:card_description', 'rollback of teaser-card-s015: card_description ''The flint mine, which was levelled about 1950, is on the south-west slope of Blackpatch Hill.'' restored on Blackpatch', 'bc239b3a026113d20e6f20fa0b8849ae0417441734bae8c35a2afc03e2973ef8|f76ae9a0f823a11366b0a8d9e151df9647498ecb5238503ea112d023e96df199|f76ae9a0f823a11366b0a8d9e151df9647498ecb5238503ea112d023e96df199', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the south-west slope of Blackpatch Hill lie more than 64 infilled shafts of a Neolithic flint mine, galleries once reaching up to 8.5 metres along a single seam of flint."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is on the south-west slope of Blackpatch Hill [S3]; there are more than 64 infilled shafts [S4]; the shafts belong to a Neolithic flint mine [S2, S3, S4]; galleries reached up to 8.5 metres [S7]; the galleries followed a single seam of flint [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Blackpatch is the site of a Neolithic flint mine [SUPPORTED: https://en.wikipedia.org/wiki/Blackpatch]; Blackpatch is an archaeological site in England (West Sussex) [SUPPORTED: https://en.wikipedia.org/wiki/Blackpatch]; The mine lies on the south-west slope of Blackpatch Hill [SUPPORTED: https://en.wikipedia.org/wiki/Blackpatch]; There are more than 64 shafts [SUPPORTED: https://en.wikipedia.org/wiki/Blackpatch]; The shafts are infilled [SUPPORTED: https://en.wikipedia.org/wiki/Blackpatch]; Galleries from the shafts extended up to 8.5 metres [SUPPORTED: https://en.wikipedia.org/wiki/Blackpatch]; The galleries followed a single seam of flint [SUPPORTED: https://en.wikipedia.org/wiki/Blackpatch]"}]'::jsonb),
    ('dd0f3348-710e-4e66-b50e-45bd71b61e12'::uuid, 'card_description', 'Badbury Hill looks over the Vale of White Horse and the Thames Valley. On its summit lies Badbury Camp, a roughly circular Iron Age hill fort, most of it levelled early in the 19th century.', 'A single rampart and ditch crown this 90-metre hill above the Vale of White Horse — proposed as the 5th-century Battle of Mons Badonicus site, now wooded and known as Badbury Clump.', 'teaser-card-s015-rollback:dd0f3348-710e-4e66-b50e-45bd71b61e12:card_description', 'rollback of teaser-card-s015: card_description ''A single rampart and ditch crown this 90-metre hill above the Vale of White Horse — proposed as the 5th-century Battle of Mons Badonicus site, now wooded and known as Badbury Clump.'' restored on Badbury Hill', '8907d7e52b2a83866189f989f518f0fe1f1377b9db53b704bb5cb1c7b94c94be|26daef24182170ee485c7085c4b8c466de2dd83cf3b072740bf3aded2866809a|26daef24182170ee485c7085c4b8c466de2dd83cf3b072740bf3aded2866809a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Badbury Hill looks over the Vale of White Horse and the Thames Valley. On its summit lies Badbury Camp, a roughly circular Iron Age hill fort, most of it levelled early in the 19th century."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Badbury Hill looks over the Vale of White Horse [S5]; Badbury Hill looks over the Thames Valley [S5]; Badbury Camp lies on its summit [S2]; Badbury Camp is an Iron Age hill fort [S2]; it is roughly circular [S3]; most of it was levelled early in the 19th century [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the summit of Badbury Hill lies Badbury Camp, an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Hill]; Badbury Hill is a hill in England (Oxfordshire) near Faringdon [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Hill]; Badbury Hill looks over the Vale of White Horse and the Thames Valley [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Hill]; The hill fort is roughly circular [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Hill]; Most of the hill fort was levelled early in the 19th century [SUPPORTED: https://en.wikipedia.org/wiki/Badbury_Hill]; The fort dates to the Iron Age [SUPPORTED: https://www.oxfordmail.co.uk/news/17612863.bluebells-badbury-clump-near-faringdon/]"}]'::jsonb),
    ('dd8e1148-5057-4496-a859-5f28c798a3f6'::uuid, 'card_description', 'Across the neck of its peninsula on Lake Petexbatún, the Maya site of Punta de Chimino dug three moats, one 12 metres deep, each topped by a palisaded wall, with box gardens between.', 'Maya site active 250–950 AD in the Petexbatún region. Three groups — north, east, and west — share a main plaza and acropolis, arranged across a defended peninsula.', 'teaser-card-s015-rollback:dd8e1148-5057-4496-a859-5f28c798a3f6:card_description', 'rollback of teaser-card-s015: card_description ''Maya site active 250–950 AD in the Petexbatún region. Three groups — north, east, and west — share a main plaza and acropolis, arranged across a defended peninsula.'' restored on Punta de Chimino', '8d3ff0e205e683177532b93c6964a1bcd53e5f4a973f09ee77c29ce64c491f5a|680c419f345d0fff781979b11991c0d2e421d64b816a233715d074ee38e87466|680c419f345d0fff781979b11991c0d2e421d64b816a233715d074ee38e87466', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Across the neck of its peninsula on Lake Petexbatún, the Maya site of Punta de Chimino dug three moats, one 12 metres deep, each topped by a palisaded wall, with box gardens between."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Punta de Chimino is a Maya site [S1]; it lies on a peninsula on Lake Petexbatún [S3]; three moats were made across the neck of the peninsula [S4, S6]; one moat was 12 metres deep [S6]; each moat was topped by a palisaded wall [S6]; box gardens lay between the moats [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Punta de Chimino is a Maya archaeological site in Guatemala (a fortified settlement site) [SUPPORTED: https://en.wikipedia.org/wiki/Punta_de_Chimino]; The site lies on a peninsula on Lake Petexbatún [SUPPORTED: https://en.wikipedia.org/wiki/Punta_de_Chimino]; The neck of the peninsula was fortified with three moats [SUPPORTED: https://en.wikipedia.org/wiki/Punta_de_Chimino]; The moats were dug (excavated from the limestone bedrock) [SUPPORTED: https://en.wikipedia.org/wiki/Punta_de_Chimino]; One of the three moats was 12 metres deep [SUPPORTED: https://en.wikipedia.org/wiki/Punta_de_Chimino]; Each moat was topped by a palisaded wall [SUPPORTED: https://en.wikipedia.org/wiki/Punta_de_Chimino]; Box gardens lay between the moats [SUPPORTED: https://en.wikipedia.org/wiki/Punta_de_Chimino]"}]'::jsonb),
    ('de3c2d9b-b7df-40c5-bfce-3f8521d9ad8f'::uuid, 'card_description', 'Beside the modern road bridge, Pont Vell crosses the only river on Ibiza. Once the only way into Santa Eulària from the west, it is probably built on the foundations of a Roman bridge.', 'Crossing Ibiza''s only river, Pont Vell was the sole western approach into Santa Eularia des Riu until modern times. The bridge served as a military crossing before being restricted to pedestrians.', 'teaser-card-s015-rollback:de3c2d9b-b7df-40c5-bfce-3f8521d9ad8f:card_description', 'rollback of teaser-card-s015: card_description "Crossing Ibiza''s only river, Pont Vell was the sole western approach into Santa Eularia des Riu until modern times. The bridge served as a military crossing before being restricted to pedestrians." restored on Pont Vell, Santa Eulària des Riu', '776ef321d99bdf28c65ba45f88b3b763d51263dba12c582797e5e11e1243c7e8|ea6d1e846784dd6ec10fccaa4479ff8bad61c785e4a7157274d583a871e006b9|ea6d1e846784dd6ec10fccaa4479ff8bad61c785e4a7157274d583a871e006b9', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Beside the modern road bridge, Pont Vell crosses the only river on Ibiza. Once the only way into Santa Eulària from the west, it is probably built on the foundations of a Roman bridge."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Pont Vell stands beside the modern road bridge [S2]; it crosses the only river on Ibiza [S1]; it was once the only way into Santa Eulària from the west [S3]; it is probably built on the foundations of a Roman bridge [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Pont Vell is a (historic) bridge at Santa Eulària des Riu on the island of Ibiza, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Vell,_Santa_Eul%C3%A0ria_des_Riu]; Pont Vell crosses the only river on Ibiza [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Vell,_Santa_Eul%C3%A0ria_des_Riu]; The bridge stands beside the modern road bridge [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Pont_Vell,_Santa_Eul%C3%A0ria_des_Riu]; Pont Vell was once the only way into Santa Eulària from the west [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Vell,_Santa_Eul%C3%A0ria_des_Riu]; The present bridge is probably built on the foundations of a Roman bridge [SUPPORTED: https://en.wikipedia.org/wiki/Pont_Vell,_Santa_Eul%C3%A0ria_des_Riu]"}]'::jsonb),
    ('df304236-53ea-44a0-8c2c-ef6a4b459728'::uuid, 'card_description', 'In Colliton Park, a steel and glass cover perched on the original foundations shelters the mosaic-floored West Range of the Roman Town House, Dorchester, built around 307 AD.', 'Built around 307 AD and extended in 341 AD, the Town House has two principal ranges of rooms.', 'teaser-card-s015-rollback:df304236-53ea-44a0-8c2c-ef6a4b459728:card_description', 'rollback of teaser-card-s015: card_description ''Built around 307 AD and extended in 341 AD, the Town House has two principal ranges of rooms.'' restored on Roman Town House, Dorchester', '6a8fb03f300e68edbf180056b3b80f384b084a1963e6f956f79fe4d749460185|d1407e17fcd632cf726f40cb075a7b43d4a250520571be98c51e166c0e31be10|d1407e17fcd632cf726f40cb075a7b43d4a250520571be98c51e166c0e31be10', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In Colliton Park, a steel and glass cover perched on the original foundations shelters the mosaic-floored West Range of the Roman Town House, Dorchester, built around 307 AD."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is in Colliton Park [S1]; a steel and glass cover building stands on the original foundations [S8]; the cover shelters the West Range [S8]; the West Range was mosaic-floored [S7]; the Town House was built around 307 AD [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Town House is a Roman ruin in Colliton Park, Dorchester, England [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Town_House,_Dorchester]; The Town House was built around 307 AD [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Town_House,_Dorchester]; The West Range of the Town House was mosaic floored [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Town_House,_Dorchester]; A steel and glass cover building shelters the West Range [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Town_House,_Dorchester]; The cover building is perched on the original foundations [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Town_House,_Dorchester]"}]'::jsonb),
    ('dfed1a81-7d54-4f3b-b1ab-e2be649acc2f'::uuid, 'card_description', 'Above Heidelberg, the wooded Heiligenberg hides a Celtic double-walled hill fort and, in the nave of a ruined medieval basilica, the foundations of a Roman temple to Mercury.', 'A double-walled Celtic hill fort from the 4th century BC, reused as a Roman sacred precinct and medieval monastery. Four thousand years of continuous ritual use.', 'teaser-card-s015-rollback:dfed1a81-7d54-4f3b-b1ab-e2be649acc2f:card_description', 'rollback of teaser-card-s015: card_description ''A double-walled Celtic hill fort from the 4th century BC, reused as a Roman sacred precinct and medieval monastery. Four thousand years of continuous ritual use.'' restored on Heiligenberg, Heidelberg', 'e00a1aec80cf44428e569fdfa16192ebdcbcec5d924614553cb36adbf7d82774|0b1a0c68f28b5ef36b91e50245dc54f228970341a261441c504f9b6a53fad2a9|0b1a0c68f28b5ef36b91e50245dc54f228970341a261441c504f9b6a53fad2a9', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above Heidelberg, the wooded Heiligenberg hides a Celtic double-walled hill fort and, in the nave of a ruined medieval basilica, the foundations of a Roman temple to Mercury."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Heiligenberg lies above Heidelberg [S1]; the hill is wooded [S1]; it holds a Celtic double-walled hill fort [S3]; it holds the foundations of a Roman temple to Mercury [S6]; the foundations lie in the nave of a ruined medieval basilica [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Heiligenberg is a hill with a Celtic hill fort and a Roman temple site on it, a multi-period archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Heiligenberg_(Heidelberg)]; The Heiligenberg is a wooded hill above Heidelberg, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Heiligenberg_(Heidelberg)]; The hill has a Celtic hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Heiligenberg_(Heidelberg)]; The Celtic hill fort is double-walled [SUPPORTED: https://en.wikipedia.org/wiki/Heiligenberg_(Heidelberg)]; A ruined medieval basilica stands on the hill (basilica church of the Monastery of St. Michael) [SUPPORTED: https://en.wikipedia.org/wiki/Heiligenberg_(Heidelberg)]; The foundations of a Roman temple to Mercury lie in the nave of the ruined basilica [SUPPORTED: https://en.wikipedia.org/wiki/Heiligenberg_(Heidelberg)]"}]'::jsonb),
    ('e0b78f4e-90c0-43a9-9f62-ac25c334fdff'::uuid, 'card_description', 'Over the Teign valley in Devon, Cranbrook Castle holds a commanding hilltop 337 metres above sea level: an Iron Age hill fort 2 kilometres from Prestonbury Castle, 3 from Wooston Castle.', 'At 337 meters above sea level, this Devon hillfort commands the Teign valley from the south. Two kilometers separate it from Prestonbury Castle, with Wooston Castle a kilometer farther west.', 'teaser-card-s015-rollback:e0b78f4e-90c0-43a9-9f62-ac25c334fdff:card_description', 'rollback of teaser-card-s015: card_description ''At 337 meters above sea level, this Devon hillfort commands the Teign valley from the south. Two kilometers separate it from Prestonbury Castle, with Wooston Castle a kilometer farther west.'' restored on Cranbrook Castle', '25be3b409113cf4f841b095a9aef5aff2bd27affecd5c5a4ab4ab60306a63705|f2c3118c537651d227a42122fa4cc16a2b6125d9e42ae833b2933e5fd8a2af13|f2c3118c537651d227a42122fa4cc16a2b6125d9e42ae833b2933e5fd8a2af13', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Over the Teign valley in Devon, Cranbrook Castle holds a commanding hilltop 337 metres above sea level: an Iron Age hill fort 2 kilometres from Prestonbury Castle, 3 from Wooston Castle."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is over the Teign valley in Devon [S1]; it occupies a commanding hilltop [S1]; the hilltop is 337 metres above sea level [S2]; it is an Iron Age hill fort [S1]; it is 2 kilometres from Prestonbury Castle [S2]; it is 3 kilometres from Wooston Castle [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cranbrook Castle is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Cranbrook_Castle]; It lies in Devon, over the Teign valley [SUPPORTED: https://en.wikipedia.org/wiki/Cranbrook_Castle]; It holds a commanding hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Cranbrook_Castle]; The hilltop is 337 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Cranbrook_Castle]; Cranbrook Castle is 2 kilometres from Prestonbury Castle [SUPPORTED: https://en.wikipedia.org/wiki/Cranbrook_Castle]; Cranbrook Castle is 3 kilometres from Wooston Castle [SUPPORTED: https://en.wikipedia.org/wiki/Cranbrook_Castle]"}]'::jsonb),
    ('e116ffe7-981d-4944-b04d-b54fd896ba7d'::uuid, 'card_description', 'A ring of 36 stones once stood inside the Late Neolithic henge of the Devil''s Quoits, south of Stanton Harcourt. Most were gone by the end of the Medieval period; new stones now stand.', 'Restored between 2002 and 2008, this Oxfordshire henge and stone circle owes its name to a legend: the Devil played quoits with a beggar for his soul and hurled these great stones.', 'teaser-card-s015-rollback:e116ffe7-981d-4944-b04d-b54fd896ba7d:card_description', 'rollback of teaser-card-s015: card_description ''Restored between 2002 and 2008, this Oxfordshire henge and stone circle owes its name to a legend: the Devil played quoits with a beggar for his soul and hurled these great stones.'' restored on Devil''s Quoits', 'f3994d5991b3ea6b48a9c9344a4c9c7d58e6b08c5d75c338da587bd14ba3649c|bf133a3669376befb059120025a1b5a0fb5d7139758cd0fac4521f66be43cfa8|bf133a3669376befb059120025a1b5a0fb5d7139758cd0fac4521f66be43cfa8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "A ring of 36 stones once stood inside the Late Neolithic henge of the Devil''s Quoits, south of Stanton Harcourt. Most were gone by the end of the Medieval period; new stones now stand."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "a ring of 36 stones once stood (the stone circle originally featured 36 stones) [S8]; the stone ring stood inside the henge [S6]; the henge is of Late Neolithic date [S3]; the site is the Devil''s Quoits [S1]; it lies south of Stanton Harcourt [S1]; most of the stones were gone by the end of the Medieval period [S8]; new stones now stand (restored with new stones added) [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Devil''s Quoits is a henge (with a stone circle) in Oxfordshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Quoits]; The site lies south of Stanton Harcourt [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Quoits]; The henge is Late Neolithic in date [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Quoits]; The ring of stones (stone circle) stood inside the henge [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Quoits]; The stone circle originally had 36 stones [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Quoits]; Most of the stones were gone (removed) by the end of the Medieval period [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Quoits]; New stones were added and now stand at the site (restored 2002-2008) [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Quoits]; The Quoits were restored with new stones added [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Quoits]"}]'::jsonb),
    ('e17ba5d6-296f-4441-85cb-8bff98ef2f7e'::uuid, 'card_description', 'Above the river Segre in the Pyrenees foothills, Roca dels Bous held flint and quartzite artifacts of Neanderthals who lived here approximately 50,000 years ago, and bones from their meals.', 'Neanderthals sheltered at "Bull''s Rock" in the Catalan Pyrenees around 50,000 years ago. Since 1988, researchers here have used a unique digital system to document the fossil sequence.', 'teaser-card-s015-rollback:e17ba5d6-296f-4441-85cb-8bff98ef2f7e:card_description', 'rollback of teaser-card-s015: card_description ''Neanderthals sheltered at "Bull\''s Rock" in the Catalan Pyrenees around 50,000 years ago. Since 1988, researchers here have used a unique digital system to document the fossil sequence.'' restored on Roca dels Bous - Archaeological Site', '0445aaa5d69ea38d80dcfb27ddaa5a3dcfb9d2c0a92f1c649153ab8637d32600|79e380b94e53d9cae894a0bf833aa59b5cd3791eeb3283fd869dc1e010bcef0f|79e380b94e53d9cae894a0bf833aa59b5cd3791eeb3283fd869dc1e010bcef0f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the river Segre in the Pyrenees foothills, Roca dels Bous held flint and quartzite artifacts of Neanderthals who lived here approximately 50,000 years ago, and bones from their meals."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies above the river Segre [S4]; the site lies in the Pyrenees foothills [S4]; Roca dels Bous held flint and quartzite artifacts [S5]; the artifacts are of Neanderthals (typical of Middle Paleolithic Neanderthals) [S2, S5]; the Neanderthals lived in the area approximately 50,000 years ago [S2]; the site held animal bones that were part of the Neanderthals'' diet [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Roca dels Bous is a Middle Paleolithic archaeological site (Neanderthal site) in the Catalan Pyrenees, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Roca_dels_Bous]; The site lies above the river Segre [SUPPORTED: https://en.wikipedia.org/wiki/Roca_dels_Bous]; The site lies in the Pyrenees foothills [SUPPORTED: https://en.wikipedia.org/wiki/Roca_dels_Bous]; The site held flint and quartzite artifacts [SUPPORTED: https://en.wikipedia.org/wiki/Roca_dels_Bous]; The artifacts are those of Neanderthals who lived here [SUPPORTED: https://en.wikipedia.org/wiki/Roca_dels_Bous]; The Neanderthals lived here approximately 50,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Roca_dels_Bous]; The site held animal bones [SUPPORTED: https://en.wikipedia.org/wiki/Roca_dels_Bous]; The bones were from the Neanderthals'' meals (their diet) [SUPPORTED: https://en.wikipedia.org/wiki/Roca_dels_Bous]"}]'::jsonb),
    ('e2030e0e-b33e-410c-b8df-8ccd76b8af03'::uuid, 'card_description', 'Khortytsia, the largest island on the Dnieper River, has been continuously inhabited for the last five millennia and played an important role in the history of the Zaporozhian Cossacks.', 'Khortytsia is the largest island on the Dnieper River, and is 12.5 km long and up to 2.5 km wide.', 'teaser-card-s015-rollback:e2030e0e-b33e-410c-b8df-8ccd76b8af03:card_description', 'rollback of teaser-card-s015: card_description ''Khortytsia is the largest island on the Dnieper River, and is 12.5 km long and up to 2.5 km wide.'' restored on Khortytsia', 'b6dbd1fa57416c67e3ce2c22ff2509385058594e9fda7afd51c6a674eb54ad0d|f2042a382209cbecb87f0f8a7d821004430fd0d291b288c2611fb59b9818667b|f2042a382209cbecb87f0f8a7d821004430fd0d291b288c2611fb59b9818667b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Khortytsia, the largest island on the Dnieper River, has been continuously inhabited for the last five millennia and played an important role in the history of the Zaporozhian Cossacks."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Khortytsia is the largest island on the Dnieper River [S1]; it has been continuously inhabited for the last five millennia [S5]; it played an important role in the history of the Zaporozhian Cossacks [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Khortytsia is an island (a historic site) on the Dnieper River, in Zaporizhzhia, Ukraine [SUPPORTED: https://en.wikipedia.org/wiki/Khortytsia]; Khortytsia is the largest island on the Dnieper River [SUPPORTED: https://en.wikipedia.org/wiki/Khortytsia]; Khortytsia has been continuously inhabited for the last five millennia [SUPPORTED: https://en.wikipedia.org/wiki/Khortytsia]; The island played an important role in the history of the Zaporozhian Cossacks [SUPPORTED: https://en.wikipedia.org/wiki/Khortytsia]"}]'::jsonb),
    ('e244d46c-a958-4c42-a154-5ed1ae613600'::uuid, 'card_description', 'On the Temenite hill, the Greek Theatre of Syracuse originally had 67 rows of seats, mostly cut into rock, in a theatron 138.6 metres across, one of the largest in the Greek world.', 'A 5th-century BC Greek theatre whose stone was quarried by the Spanish under Charles V to build fortifications. Centuries of reuse slowly dismantled the original structure.', 'teaser-card-s015-rollback:e244d46c-a958-4c42-a154-5ed1ae613600:card_description', 'rollback of teaser-card-s015: card_description ''A 5th-century BC Greek theatre whose stone was quarried by the Spanish under Charles V to build fortifications. Centuries of reuse slowly dismantled the original structure.'' restored on Greek Theatre of Syracuse', 'fb40536ff80c0ae96ead79caed2dc60496b5fe933c8032ae847151870cf79309|6a77a7147413fda610e5672f523390102f2b7138e8351fb239ee5fea8c82dee8|6a77a7147413fda610e5672f523390102f2b7138e8351fb239ee5fea8c82dee8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the Temenite hill, the Greek Theatre of Syracuse originally had 67 rows of seats, mostly cut into rock, in a theatron 138.6 metres across, one of the largest in the Greek world."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the theatre stands on the Temenite hill [S1]; the Greek Theatre of Syracuse originally had 67 rows of seats [S2]; the seating was mostly cut into rock [S2]; the theatron is 138.6 metres across (in diameter) [S2]; it is one of the largest theatres in the Greek world [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Greek Theatre of Syracuse is an ancient theatre on the Temenite hill in Syracuse, Sicily, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Greek_Theatre_of_Syracuse]; The theatre originally had 67 rows of seats [SUPPORTED: https://en.wikipedia.org/wiki/Greek_Theatre_of_Syracuse]; The seating rows were mostly cut into rock [SUPPORTED: https://en.wikipedia.org/wiki/Greek_Theatre_of_Syracuse]; The theatron was 138.6 metres across (in diameter) [SUPPORTED: https://en.wikipedia.org/wiki/Greek_Theatre_of_Syracuse]; The theatron was one of the largest in the Greek world [SUPPORTED: https://en.wikipedia.org/wiki/Greek_Theatre_of_Syracuse]"}]'::jsonb),
    ('e256cfc9-63fe-4f27-b7e9-6778a8317eb7'::uuid, 'card_description', 'Around 70 meters from the Lion Gate, the Tomb of Aegisthus held a burial chamber once around 13 meters tall under a corbelled dome. The dome collapsed; only about 8m of height remains.', 'A Mycenaean tholos tomb from 1510–1450 BC, the third largest at Mycenae. Its architecture bridges the oldest and newest tomb styles at the site.', 'teaser-card-s015-rollback:e256cfc9-63fe-4f27-b7e9-6778a8317eb7:card_description', 'rollback of teaser-card-s015: card_description ''A Mycenaean tholos tomb from 1510–1450 BC, the third largest at Mycenae. Its architecture bridges the oldest and newest tomb styles at the site.'' restored on Tomb of Aegisthus', 'a006191482300b956649fa85404b3639e7aeb1423cee800b22fc2a902af54aa1|68f348c0cd219d068d2c72508194bb14b82e310850f4ed20905b1c2662d47970|68f348c0cd219d068d2c72508194bb14b82e310850f4ed20905b1c2662d47970', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Around 70 meters from the Lion Gate, the Tomb of Aegisthus held a burial chamber once around 13 meters tall under a corbelled dome. The dome collapsed; only about 8m of height remains."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Tomb of Aegisthus lies around 70 meters from the Lion Gate [S4]; the tomb has a burial chamber [S5]; the burial chamber was once around 13 meters tall [S6, S7]; the chamber is under a corbelled dome [S5]; the dome collapsed [S7]; only about 8m of height remains [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Tomb of Aegisthus is a Mycenaean tholos tomb near the citadel of Mycenae, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Aegisthus]; The tomb is around 70 meters from the Lion Gate [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Aegisthus]; The tomb had a burial chamber under a corbelled dome [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Aegisthus]; The burial chamber was originally around 13 meters tall [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Aegisthus]; The dome collapsed [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Aegisthus]; Only about 8 m of height remains [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Aegisthus]"}]'::jsonb),
    ('e2a04b44-a3e7-47fc-a217-0689fab93524'::uuid, 'card_description', 'Built in Naples in the first century BC, the Villa of Lucullus had piers stretching into the sea. Its remains are visible at several places, and Roman columns still stand in a castle cellar.', 'A Roman villa with piers stretching into the sea, fish ponds, moray eel farms, and a rich library. Consul Lucullus was famous for his legendary feasts.', 'teaser-card-s015-rollback:e2a04b44-a3e7-47fc-a217-0689fab93524:card_description', 'rollback of teaser-card-s015: card_description ''A Roman villa with piers stretching into the sea, fish ponds, moray eel farms, and a rich library. Consul Lucullus was famous for his legendary feasts.'' restored on Villa of Lucullus', 'a18f8df68e07a7e124706d72196c7a45349c1ac94a417e292538b78edf9dbdf5|6560eba306db7f41b7ea7f84c0d390602192ecf7ac5f48732a8846444d8a9d67|6560eba306db7f41b7ea7f84c0d390602192ecf7ac5f48732a8846444d8a9d67', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Built in Naples in the first century BC, the Villa of Lucullus had piers stretching into the sea. Its remains are visible at several places, and Roman columns still stand in a castle cellar."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Villa of Lucullus was built in Naples [S1]; it was built in the first century BC [S1]; the villa had piers stretching out into the sea [S2]; its remains are visible at several places [S4]; Roman columns still stand [S5]; the standing columns are in the cellar of a castle (Castel dell''Ovo) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Villa of Lucullus was an ancient Roman villa in Naples, Italy (central claim: what kind of place it is and where) [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Lucullus]; It was built in the first century BC [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Lucullus]; The villa had piers stretching into the sea [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Lucullus]; Its remains are visible at several places [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Lucullus]; The remains lie in the cellar of a castle (the Castel dell''Ovo) [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Lucullus]; Roman columns still stand there [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Lucullus]"}]'::jsonb),
    ('e2aa3754-8d32-4455-bf6d-9077f18d50d2'::uuid, 'card_description', 'On the slopes of Mount Parnassus, Ancient Lilaia is named in Homer''s Iliad. Destroyed by Philip II of Macedon in 346 BCE, it was rebuilt; Pausanias later saw its theatre, agora and baths.', 'From the 3rd millennium to the 1st century BC, Lilaia controlled the Cephissus headwaters. Its walls, gates, and a temple at the sacred springs are still visible east of the modern village.', 'teaser-card-s015-rollback:e2aa3754-8d32-4455-bf6d-9077f18d50d2:card_description', 'rollback of teaser-card-s015: card_description ''From the 3rd millennium to the 1st century BC, Lilaia controlled the Cephissus headwaters. Its walls, gates, and a temple at the sacred springs are still visible east of the modern village.'' restored on Ancient Lilaia', 'cbb3102b4d14887cf97cfa6655d98b095a06ad8ea3e3d93c0f9243fff22b079c|21a2ec53a8721816d40913501fb70881111b91911beeb0ecd2063609830b210a|21a2ec53a8721816d40913501fb70881111b91911beeb0ecd2063609830b210a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the slopes of Mount Parnassus, Ancient Lilaia is named in Homer''s Iliad. Destroyed by Philip II of Macedon in 346 BCE, it was rebuilt; Pausanias later saw its theatre, agora and baths."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ancient Lilaia lies on the slopes of Mount Parnassus [S1]; it is named in Homer''s Iliad [S2]; it was destroyed by Philip II of Macedon [S4]; the destruction happened in 346 BCE [S4]; it was rebuilt [S4]; Pausanias later saw its theatre, agora and baths [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ancient Lilaia was one of the most important ancient Phocian towns, a polis (city-state) (central claim: an ancient city in Phocis, Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Lilaea_(ancient_city)]; Lilaia was built on the slopes of Mount Parnassus [SUPPORTED: https://en.wikipedia.org/wiki/Lilaea_(ancient_city)]; Lilaia is named in Homer''s Iliad [SUPPORTED: https://en.wikipedia.org/wiki/Lilaea_(ancient_city)]; Lilaia was destroyed by Philip II of Macedon in 346 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Lilaea_(ancient_city)]; Lilaia was rebuilt after its destruction [SUPPORTED: https://en.wikipedia.org/wiki/Lilaea_(ancient_city)]; Pausanias later saw its theatre, agora and baths [SUPPORTED: https://en.wikipedia.org/wiki/Lilaea_(ancient_city)]"}]'::jsonb),
    ('e2bb7b81-bdd5-4713-893f-3c2c516a3d7a'::uuid, 'card_description', 'Where Vienna now stands lay Vindobona, a Roman camp fed by a 17 km water pipeline. Aurelius Victor recounts that emperor Marcus Aurelius died here on 17 March 180 of an unknown illness.', 'Legio X Gemina from Aquincum arrived in 114 AD and remained in Vindobona until the 5th century.', 'teaser-card-s015-rollback:e2bb7b81-bdd5-4713-893f-3c2c516a3d7a:card_description', 'rollback of teaser-card-s015: card_description ''Legio X Gemina from Aquincum arrived in 114 AD and remained in Vindobona until the 5th century.'' restored on Vindobona', 'bea86f5b123b2e8f26d15e7bc091de23d6ed411d14012feace2fd1a484c7a92c|1d912b0e8ccf978a9b9c8be0ba47fb3917096b46bef2ee1391bd339e3494fe82|1d912b0e8ccf978a9b9c8be0ba47fb3917096b46bef2ee1391bd339e3494fe82', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Where Vienna now stands lay Vindobona, a Roman camp fed by a 17 km water pipeline. Aurelius Victor recounts that emperor Marcus Aurelius died here on 17 March 180 of an unknown illness."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vindobona lay where Vienna now stands [S1]; Vindobona was a Roman camp [S1]; it was supplied through a 17 km water pipeline [S7]; Aurelius Victor recounts the death of emperor Marcus Aurelius [S2]; Marcus Aurelius died in Vindobona [S2]; he died on 17 March 180 [S2]; he died of an unknown illness [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vindobona was a Roman military camp (central claim: a Roman camp / castra) [SUPPORTED: https://en.wikipedia.org/wiki/Vindobona]; Vindobona lay where Vienna (Austria) now stands [SUPPORTED: https://en.wikipedia.org/wiki/Vindobona]; Vindobona was supplied with water by a pipeline 17 km long [SUPPORTED: https://en.wikipedia.org/wiki/Vindobona]; Aurelius Victor recounts (attributed statement) that the emperor Marcus Aurelius died in Vindobona (Tertullian''s Apologeticum places the death at Sirmium instead) [SUPPORTED: https://en.wikipedia.org/wiki/Vindobona]; Marcus Aurelius died on 17 March [SUPPORTED: https://en.wikipedia.org/wiki/Vindobona]; Marcus Aurelius died in the year 180 [SUPPORTED: https://en.wikipedia.org/wiki/Vindobona]; The illness of which Marcus Aurelius died is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Vindobona]"}]'::jsonb),
    ('e3330c2d-88f8-4101-88f0-4b174cb1bbf8'::uuid, 'card_description', 'Near the banks of the Carrión, La Olmeda Roman Villa set twenty-seven rooms, twelve with mosaic floors, around a patio crossed by geometric mosaic paths and ringed by a wide peristyle.', 'A palatial Roman villa expanded over four centuries, from the 1st to the 5th century AD. Its mosaic floors depict Achilles and Odysseus in vivid polychrome detail.', 'teaser-card-s015-rollback:e3330c2d-88f8-4101-88f0-4b174cb1bbf8:card_description', 'rollback of teaser-card-s015: card_description ''A palatial Roman villa expanded over four centuries, from the 1st to the 5th century AD. Its mosaic floors depict Achilles and Odysseus in vivid polychrome detail.'' restored on La Olmeda Roman Villa', 'b2c9a785603c5b95e5c40eb2e4012537a2678954b9e9dba95eadc063bc129b31|ad6de7fa55816989a7c6ee9dab1af0e66fbcd673af262e43fabb0759f2ee9d87|ad6de7fa55816989a7c6ee9dab1af0e66fbcd673af262e43fabb0759f2ee9d87', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near the banks of the Carrión, La Olmeda Roman Villa set twenty-seven rooms, twelve with mosaic floors, around a patio crossed by geometric mosaic paths and ringed by a wide peristyle."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the villa lies near the banks of the Carrión [S1]; the villa had twenty-seven rooms [S3]; twelve of the rooms had mosaic floors [S3]; the rooms are set around a patio [S3]; the patio is crossed by mosaic paths [S3]; the mosaic paths are in geometric patterns [S3]; a wide peristyle rings the patio [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "La Olmeda is a Roman villa (central claim: a Roman villa, near the banks of the Carrion in Spain) [SUPPORTED: https://en.wikipedia.org/wiki/La_Olmeda]; The villa lies near the banks of the Carrion [SUPPORTED: https://en.wikipedia.org/wiki/La_Olmeda]; The villa has twenty-seven rooms [SUPPORTED: https://en.wikipedia.org/wiki/La_Olmeda]; Twelve of the rooms have mosaic floors [SUPPORTED: https://en.wikipedia.org/wiki/La_Olmeda]; The rooms are arranged around a central patio [SUPPORTED: https://en.wikipedia.org/wiki/La_Olmeda]; The patio is crossed by mosaic paths in geometric patterns [SUPPORTED: https://en.wikipedia.org/wiki/La_Olmeda]; The patio is ringed by a wide peristyle [SUPPORTED: https://en.wikipedia.org/wiki/La_Olmeda]"}]'::jsonb),
    ('e3357e9e-c79f-43db-bfb5-7e62ba21daff'::uuid, 'card_description', 'On the granite summit of Chapel Carn Brea lies a late Neolithic entrance grave 9 metres across, its entrance facing south. Of eleven barrows once on the hill, only seven now remain.', 'A Neolithic hilltop with an entrance tomb from around 3300 BC. The tor that crowns it has been a landmark for thousands of years across the surrounding lowlands.', 'teaser-card-s015-rollback:e3357e9e-c79f-43db-bfb5-7e62ba21daff:card_description', 'rollback of teaser-card-s015: card_description ''A Neolithic hilltop with an entrance tomb from around 3300 BC. The tor that crowns it has been a landmark for thousands of years across the surrounding lowlands.'' restored on Chapel Carn Brea', '647f6132adfe29e158f14060fb3b10c68906b283425ff402c5c5142a02e4011b|a08e56dc89ae8f9faeab86d96423847c5a0775d10c6d6edfe4d24fb0878ca745|a08e56dc89ae8f9faeab86d96423847c5a0775d10c6d6edfe4d24fb0878ca745', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the granite summit of Chapel Carn Brea lies a late Neolithic entrance grave 9 metres across, its entrance facing south. Of eleven barrows once on the hill, only seven now remain."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies on the granite summit of Chapel Carn Brea [S1, S4]; there is an entrance grave on the summit [S4]; the entrance grave is late Neolithic [S4]; the entrance grave is 9 metres across [S4]; its entrance faces south [S4]; there were once eleven barrows on the hill [S3]; only seven barrows now remain [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Chapel Carn Brea is a granite hill (outcrop) in Cornwall, England, with an entrance grave on its summit (central claim: a hilltop prehistoric burial site on a granite hill in England) [SUPPORTED: https://en.wikipedia.org/wiki/Chapel_Carn_Brea]; Chapel Carn Brea is in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Chapel_Carn_Brea]; On the summit lies an entrance grave [SUPPORTED: https://en.wikipedia.org/wiki/Chapel_Carn_Brea]; The entrance grave was built in the late Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Chapel_Carn_Brea]; The entrance grave is 9 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Chapel_Carn_Brea]; The entrance of the grave faces south [SUPPORTED: https://en.wikipedia.org/wiki/Chapel_Carn_Brea]; There were once eleven barrows on the hill [SUPPORTED: https://en.wikipedia.org/wiki/Chapel_Carn_Brea]; Only seven of the eleven barrows now remain [SUPPORTED: https://en.wikipedia.org/wiki/Chapel_Carn_Brea]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s015-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s015-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s015-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('afac29e1-ce20-4266-8f23-7bb05390ac64'::uuid, 'card_description', 'Nearly a kilometre through the tuff of Monte Grillo runs the Grotta di Cocceio, a Roman tunnel of 38-36 BC wide enough for two wagons, its Avernus entrance once lined with statues in niches.'), ('b048a095-8e3e-41af-a715-e785e3a1a51d'::uuid, 'card_description', 'Drovers, merchants and travellers used the Roman Road from Silchester to Bath, from Calleva Atrebatum to Aquae Sulis. In places it survives; elsewhere no apparent trace remains in view.'), ('b04ee52d-6549-4877-8131-2475c9989299'::uuid, 'card_description', 'On the banks of the Garonne, the Roman Villa of Chiragan grew from a modest villa with thermal baths and a peristyle to cover an area equal to one third of the Villa Hadriana in Tivoli.'), ('b065a36f-0e01-4de3-9100-409a15eeb532'::uuid, 'card_description', 'Dewerstone is a rocky promontory above the River Plym with hill fort ramparts. Dartmoor tradition says the Devil''s phantom black hounds chase the weary or foolish over it to their deaths.'), ('b07c4d65-158e-4e9d-9817-f39161b7516d'::uuid, 'card_description', 'Of soft pink sandstone, the Duddo Five Stones look out over the Cheviot and Lammermuir Hills. Known as the Four Stones until 1903, when the fifth was re-erected to improve the skyline.'), ('b0b4e4d6-ef79-4b2d-ad6b-62532b5ba54d'::uuid, 'card_description', 'Near Chan Chan, dragon figures are carved into the adobe walls of the Huaca del Dragón beside reliefs of a rainbow. Ramps climb to a level of pits possibly used to store food.'), ('b10227e6-8a83-4290-8503-ec037e4bc3c3'::uuid, 'card_description', 'On the South Downs, five large bell barrows stand in a line aligned with sunset on Midsummer Day: the Devil''s Jumps, considered the best preserved Bronze Age barrow group in Sussex.'), ('b13caf27-5754-44a2-b13d-ec8824ac95f4'::uuid, 'card_description', 'High masonry barriers once closed the gaps between the Doric columns of Temple F, Selinus, perhaps to make a cultic area. In 1823 excavators found two half metopes of Dionysus and Athena.'), ('b1410fda-e006-411f-a8ce-64513976d158'::uuid, 'card_description', 'On Eyam Moor, with clear views of the River Derwent valley, Wet Withens is the largest embanked stone circle in Derbyshire. Its Chair Stone has a ledge cut out of its face, like a seat.'), ('b1e4d609-9b3a-4b93-8ad0-e890a880a5dc'::uuid, 'card_description', 'The first substantial villa found south of the Purbeck Hills, Bucknowle Roman Villa began in the late 1st century AD with an aisled hall and grew to three large buildings and a bath house.'), ('b300f71d-88f7-4a2a-bdf0-b9bb33a53c73'::uuid, 'card_description', 'On a low hill in Dorset, a single bank rings Banbury Hill, an Iron Age hillfort entered by a passage at one point down to about 2 metres wide. Inside, there are no traces of remains.'), ('b39a1e3a-d7fa-473f-aad8-0aea535c4802'::uuid, 'card_description', 'Under Naples lie the Catacombs of Saint Gaudiosus, paleo-Christian burials of the 4th–5th century AD, where an arcosolium at the entrance guards his tomb with a sixth-century mosaic.'), ('b3aacfb1-87e7-448e-b6a3-1c394670aad3'::uuid, 'card_description', 'About 40 metres above the river Poričnica, the hill fort of Pod yielded the stratified materials that defined the Central Bosnian cultural group of the late Bronze Age.'), ('b40d492a-193f-422b-bd42-559624dd2079'::uuid, 'card_description', 'On a hill and glade in Turku lies Virnamäki, an Iron Age monument area and dwelling site, where cremation cemeteries rest under level ground and multiple stones bear cup marks.'), ('b4990b79-a0d1-45e7-9d03-635362c0b2cf'::uuid, 'card_description', 'Built in the 1st century AD, the Roman Provincial Forum of Emerita Augusta was a large square with a monumental portico and a large temple at its centre, reached through the Arch of Trajan.'), ('b5541bbe-346c-4b3a-831c-21d6aa994adc'::uuid, 'card_description', 'Aldgate once pierced the defensive wall around the City of London. In 1377, fearing a French attack, it was fortified with portcullises and chains; its defences were tested twice.'), ('b587a652-f222-47e6-adc9-b6ba1fa62722'::uuid, 'card_description', 'Above the Avon Valley, on the edge of the New Forest, Frankenbury Camp encloses approximately 11 acres: an Iron Age hillfort held by steep slopes to west and south and a rampart and ditch.'), ('b5e251e7-b1d1-46d4-8bba-b02956ff13c9'::uuid, 'card_description', 'Five friends slipped through a narrow sinkhole into the Caves of Nerja, whose walls bear Paleolithic paintings and where humans and cave hyenas took seasonal turns from about 25,000 BC.'), ('b622ebae-c26d-4aef-a028-15edc1596f02'::uuid, 'card_description', 'By the lower Motagua River, Quirigua raised the tallest stele in the Maya world, among unusually large stelae carved from single blocks of red sandstone hauled from 5 kilometres away.'), ('b6945bd6-a99e-4034-b451-2f6c7faec322'::uuid, 'card_description', 'On Akeman Street, the trade route linking London to South West England, Aylesbury grew into a market town where pilgrims sought the shrine of Saint Osgyth. In 1086 it was a royal manor.'), ('b719c2bb-3424-4eab-8648-9e72bf83bdac'::uuid, 'card_description', 'On Bratton Down, the two ramparts of Bratton Castle, an Iron Age hill fort, enclose a pentagon of 9.3 hectares, dug before 1775 in what is thought one of Wiltshire''s earliest excavations.'), ('b7f23683-db44-409d-8326-78af49f5b8a1'::uuid, 'card_description', 'On a low gravel-capped plateau east of Lockerley, the ploughed-down earthworks of Lockerley Camp, an Iron Age hillfort of approximately 5 acres, still show in a small coppice to the north.'), ('b96aa592-779d-4d93-a16f-7b09496b1139'::uuid, 'card_description', 'In Riclones, the small Cave of Chufín holds subtle engravings and schematic paintings of red deer, goats and cattle, and many symbols. Its oldest occupation level is around 20000 years old.'), ('b97f1e4c-09df-4190-aed5-22bfeb4a45cc'::uuid, 'card_description', 'Near Ballinagree in County Cork, Carrigagulla gathers a circle of 16 standing stones around a central slab, and a stone row where four of five stones have been moved and now serve as gates.'), ('ba0ce1ee-9848-4de1-9884-0e0bb37e2abd'::uuid, 'card_description', 'Near Niederstotzingen, a Celtic four-sided earthwork and a Roman villa rustica were found. In 1962, construction uncovered an Alamannian cemetery of nobles with their animals and valuables.'), ('ba1d0bf4-260a-467e-adaa-2a53d13745aa'::uuid, 'card_description', 'Near the temple of Apollo at Delphi lay the Halos, a round open space whose name means threshing floor, where once every eight years the Septerion re-enacted Apollo''s killing of Python.'), ('ba33abc5-f266-4b9c-85f1-cd691699b271'::uuid, 'card_description', 'Near Aylesford in Kent, three stones still carry the capstone of Kit''s Coty House, a long barrow built circa 4000 BCE, its mound largely ploughed flat yet visible from aerial photographs.'), ('baf89ae1-61ca-47d4-a5ee-9e4a02362803'::uuid, 'card_description', 'West of Apollo''s sacred precinct at Delphi, the Portico of the Aetolians runs 72.60 metres behind a double colonnade, 29 columns outside and 15 within, one of Delphi''s largest buildings.'), ('bc4228ff-3afd-4efa-a458-65d0636135df'::uuid, 'card_description', 'Among the oldest structures in Scotland, the Grey Cairns of Camster date to around 3,000 BC: a horned long cairn 60 m long and a round one, each hiding burial chambers down narrow passages.'), ('bc55dd6f-a972-4caa-af6a-e4e96f65d0f5'::uuid, 'card_description', 'Opened in 1837, the Rillaton Barrow on Bodmin Moor hid a burial in a stone cist, laid with a bronze dagger, beads and a gold cup around 9 cm high, its handle fixed with rivets.'), ('bdba33af-64d6-4a74-90f3-4ecf9e512c83'::uuid, 'card_description', 'In the upper reaches of Gleann Beag stands Dun Grugaig, a D-shaped fort of a type commonly regarded as a prototype broch, sharing its valley with the brochs of Dun Telve and Dun Troddan.'), ('bdd92d68-2715-4dfe-a956-e2f3a5b77465'::uuid, 'card_description', 'Amid farming terraces in northwest Belize lies La Milpa, a Maya city whose Main Plaza alone covers 18,000 square meters. In the mid-8th century, its monuments and stelae multiplied.'), ('be53cb70-c063-415a-a127-4997d12c405e'::uuid, 'card_description', 'First seen in aerial photos in 1930, Nakbe is one of the largest early Maya sites, linked by a causeway to El Mirador, its limestone quarries a key to building large temples.'), ('bf30fac5-d015-46c4-b340-74e5614ce274'::uuid, 'card_description', 'Beside a pyramid-hill in Veracruz, El Azuzul kept two pairs of Olmec sculptures intact and apparently undisturbed since Pre-Classic times, among them two nearly identical seated figures.'), ('bf538bd9-912c-471a-964a-f94842e17491'::uuid, 'card_description', 'At Cyrene rose the Temple of Zeus, one of the largest Greek temples ever built, ringed by fluted columns. Damaged in 115 AD and partly rebuilt, it fell to an earthquake in 365 AD.'), ('c078b659-9020-4254-84f5-bd19690dea97'::uuid, 'card_description', 'On a knoll near where the Rivers Eamont and Lowther meet, the circular bank of Mayburgh Henge, up to 15 feet high and possibly of river cobbles, encloses a single monolith 9 feet high.'), ('c0d65355-96d2-407f-bda3-b4e63897266d'::uuid, 'card_description', 'Found in 1973 as irrigation water ate into it, Bandurria was an early coastal fishing settlement with a sunken circular plaza and the first evidence of ceremonial stone architecture.'), ('c17fcb7a-b41f-406c-9799-e42fa9443371'::uuid, 'card_description', 'On high land above the cliff over Manorbier bay, King''s Quoit rests a capstone 4 metres by 2.5 metres on two upright stones and the rising ground, its Neolithic chamber partly below ground.'), ('c22fa6c5-6691-4f76-a6fe-83ee0b7e0dbf'::uuid, 'card_description', 'Near Penzance, Boskednan Stone Circle, the Nine Maidens, may once have held as many as 22 stones. Ten survive, and nearby lay a cist and a funerary urn from the early Bronze Age.'), ('c30712db-a675-4203-a442-cb3f9b1c5848'::uuid, 'card_description', 'At 2100 m above sea level, near a pass south of the Caucasus range, Tsona Cave is one of the highest archaeological cave sites in Georgia, where Lower and Middle Paleolithic remains lay.'), ('c3517388-2457-42fd-9cf8-f6a043021b1e'::uuid, 'card_description', 'Petrovaradin''s region fell to Celts in the 4th century BC and to Romans in the 1st century BC. Under Roman administration a fortress named Cusum rose here, part of Roman Pannonia.'), ('c3b60256-57d1-4b74-80f0-1a2536795a20'::uuid, 'card_description', 'The oldest known village in the Bannu region, Sheri Khan Tarakai was home to perhaps a few hundred people in mud-walled houses, some on stone foundations under flat roofs of wattle and daub.'), ('c4bfc499-08d9-4cd2-ac3f-91ddaa743710'::uuid, 'card_description', 'In the chalk of Norfolk, the Neolithic miners of Grime''s Graves sank at least 433 shafts, digging with red deer antler picks through topstone and wallstone toward the floorstone flint.'), ('c5761cbc-32e4-48b1-97de-a33bca256831'::uuid, 'card_description', 'On a peak of the Sierra de Tepoztlan, the small temple of El Tepozteco honoured Tepoztecatl, the Aztec god of pulque, and drew pilgrims from as far away as Guatemala.'), ('c5f853ae-ee16-4da1-9f17-f3ff66205f61'::uuid, 'card_description', 'At the eastern end of the Dundry Down ridge, south of Bristol, stands Maes Knoll, an Iron Age hill fort whose name joins a Brythonic word for flat top with an Old English word for hill.'), ('c5f8bd3a-c334-453c-b99b-9509aac6ea90'::uuid, 'card_description', 'In a hillside cave by the Meuse, Scladina yielded the nearly complete jaw of a Neanderthal child, dated to around 127,000 years, its DNA one of the oldest drawn from a Neanderthal fossil.'), ('c68b5a7f-8fb5-426e-b73e-7743264afc87'::uuid, 'card_description', 'An ancient village lies amid modern Umm el-Jimal: 150 houses still standing, 15 churches from a sixth-century building boom, all deserted under the Abbasid Caliphs in the ninth century.'), ('c6d155e2-7202-4ee6-b29f-b3d9a440efae'::uuid, 'card_description', 'Near the village of Telheiro stand the Antas do Olival da Pêga, two megalithic tombs about 300 meters apart. Over one hundred people were buried in each; Anta 1 is among Portugal''s tallest.'), ('c7a242e3-1638-4260-82da-ec130f9cc023'::uuid, 'card_description', 'South of the old city of Jalalpur Jattan lies Salamgarh, an old city itself, whose fort of Islamgarh remained under Aurangzeb Alamgir, Ahmed Shah Abdali and Ranjit Singh and their forces.'), ('c85493c5-808e-4d63-b06a-a570a21af151'::uuid, 'card_description', 'On a ridge 609 m above sea level, near the sources of the Aufidus, the Hirpini city of Compsa was betrayed to Hannibal in 216 BC after the defeat of Cannae, then recaptured two years later.'), ('c8ec86a6-5e59-47c9-a1be-51db69a2f0d7'::uuid, 'card_description', 'On a hill east of Keswick, the volcanic boulders of Castlerigg Stone Circle, the heaviest estimated at around 16 tons, ring a flattened circle with a 3.3 metre gap, perhaps an entrance.'), ('c9645011-82ed-4818-b2fd-0b3632713d1c'::uuid, 'card_description', 'Above the Montpellier garrigue at 190m, the Oppidum d''Altimurium, founded in the 2nd century BC, was guarded by a wall almost 2 km long; its Roman heart held a square and probably a temple.'), ('c9ea41a4-53e0-481a-9e3c-d314cfa36c9e'::uuid, 'card_description', 'Above the mouth of the Miño, at 341 meters, the Castro of Santa Trega is a settlement of circular structures, lived in from 100 BC to 100 AD; in 1862 stonemasons found a bronze Hercules.'), ('ca1f8a94-27e1-4318-b3d5-3db181795ffd'::uuid, 'card_description', 'In the suburbs of today''s capital lie the remains of Panamá Viejo, founded in 1519, once a base for gold and silver bound for Spain, destroyed in 1671 by the Welsh privateer Henry Morgan.'), ('cab346d8-176c-429d-830c-2f1ac68e2eb9'::uuid, 'card_description', 'The Roman Thermae of Maximinus, public baths of Bracara Augusta, shrank at the end of the 3rd century; by the 4th century even the theatre fell silent, its stones used for the city walls.'), ('cac95409-52f9-4a26-bf59-fd7af98d054e'::uuid, 'card_description', 'Hewn-stone walls up to circa 3.5 m, lintels over an eastern entrance, mosaic traces under a later floor: the Anim Synagogue, a basilical hall of the 4th to 7th centuries CE, later a mosque.'), ('cc4c3c3a-1ada-47d8-93ea-2cbb7930f772'::uuid, 'card_description', 'Settled for at least 4,000 years, Castle Hill above Huddersfield carries an Iron Age hillfort from around 555 BC, a 12th-century motte-and-bailey castle and traces of a severe burning.'), ('cc5fb86d-5a12-4ff9-85dc-5c02534e9d7a'::uuid, 'card_description', 'Once a considerable work, now a raised hedgerow or a mere cropmark, Wat''s Dyke runs 40 miles through the northern Welsh Marches beside Offa''s Dyke, and the date it was built is disputed.'), ('cd21e416-7458-42af-afa9-4141e9bca954'::uuid, 'card_description', 'Built in murus dacicus style against Roman conquest, the six Dacian Fortresses of the Orăştie Mountains guarded Decebalus; the capital, Sarmizegetusa Regia, crowned a 1,200 metres hill.'), ('cd37791b-f83e-42ab-8cf4-94767b4b6571'::uuid, 'card_description', 'In the Graves of Sainte-Colombe-sur-Seine, burial mounds of the 6th century BC, a woman was laid to rest on an iron-clad funerary wagon, gold bracelets and earrings in her grave.'), ('ce525bf9-3005-4e2b-9985-ae0037cff99f'::uuid, 'card_description', 'Steep cliffs guard two sides of Helsby Hill Fort, an Iron Age hillfort above the Cheshire Plain. Double ramparts shield its other flanks, and digs revealed a wall of sand and rubble.'), ('cecf3b1e-4685-4c8b-acbd-f4e1be336f0b'::uuid, 'card_description', 'About 26 house ruins and several middens lie at Uummannaq, where whaling Captain George Comer dug in 1916. Comer''s Midden is the find after which the Thule culture was named.'), ('cfe7373f-ccbd-42a0-88db-bc19fe33d950'::uuid, 'card_description', 'Petroglyphs are engraved on the Lapa de Gargantáns, a menhir in Moraña dated between 3000–2000 BC. Its exact function is unknown; some link it to burials, worship or old tribal boundaries.'), ('cff3c769-e793-40f3-897c-4b085cdf9b56'::uuid, 'card_description', 'Ali Murad Mound lies 20 miles southwest of Dadu. At its top, an ancient hamlet was found ringed by defensive walls of stone blocks, and N. G. Majumdar explored and named the site.'), ('d0e007ba-24cd-4929-b135-0b907397e531'::uuid, 'card_description', 'Two round cairns joined by a bank form Long Low, a layout unique in England. In 1849 its limestone burial chamber gave up the bones of thirteen people and three leaf-shaped flint arrowheads.'), ('d1a6a883-779d-47eb-8496-78fbb360ddd6'::uuid, 'card_description', 'In the Callejón de Huaylas valley, Guitarrero Cave held some of South America''s earliest cultivated plants, with evidence of human use around 8,000 BCE and possibly as early as 10,560 BCE.'), ('d1bb188e-07a5-4b2d-9624-65a918e88435'::uuid, 'card_description', 'Built on the Stanegate before Hadrian''s Wall, the Roman fort of Magnis kept a 2-foot-long iron spearhead 36 feet down a well. It also gave up the modius, a bronze grain-measure.'), ('d2575f3f-5a83-4e7a-8e7c-d3325602aee5'::uuid, 'card_description', 'Maya builders laid mostly black slate blocks without mortar in the Lubaantun Archaeological Reserve. The city''s ancient name is unknown; its modern Maya name means place of fallen stones.'), ('d2cffaa4-e1cb-4b2e-9907-76abf47411d1'::uuid, 'card_description', 'Near Naga el-Ghoneimeya, the Edfu South Pyramid, a step pyramid now about 4.9 metres high, sits slightly off true north to run parallel to the Nile. Its builder and purpose are unknown.'), ('d2dd6e95-7f9a-4d6c-bd8e-a00f39d1f1f5'::uuid, 'card_description', 'A belt of 36 carnelian beads and small terracotta jars brimming with gold and silver ornaments came from Allahdino, a Harappan village east of Karachi abandoned by circa 2000 BCE.'), ('d34a4c75-f3e7-42e8-accb-1e2329dc27fa'::uuid, 'card_description', 'Over 9 kilometres of ditches and ramparts form the Stanwick Iron Age Fortifications, where Wheeler found an Iron Age sword in its ash wood scabbard and, nearby, the skull of a severed head.'), ('d56cc124-8502-45b8-8fc6-b7dc59d02e43'::uuid, 'card_description', 'On the western bank of the Mur, Vespasian made Flavia Solva a municipium around year 70. First destroyed in 166, it rose again under Commodus and a few decades later flourished once more.'), ('d6665022-2763-44cd-8963-d6fb7d4cfc52'::uuid, 'card_description', 'Near Winchester, the Flowerdown Barrows keep a Bronze Age disc barrow 28 metres in diameter, described as the finest in Hampshire, a hollow at the heart of its larger central mound.'), ('d6ea97bd-2ddb-4065-961a-1e2c8d6a2a3b'::uuid, 'card_description', 'Beside the Nakhchivanchay river, Kultepe-2 rests on an Early Bronze Age layer 7–10 m thick. Remains of circular brick buildings, large painted containers and bronze tools were found.'), ('d7e1cd9a-7861-459a-8454-5631dbbadf8b'::uuid, 'card_description', 'Slim passages lead through the Grotte de Gabillou to more than 200 ornaments, among them The Sorcerer: a horned and bearded man-like figure with a leg and foot like a human''s.'), ('d8256f75-7b93-49b5-8910-801bd1591397'::uuid, 'card_description', 'On a grave mound above the Valdres valley, the Einang Stone bears Elder Futhark runes dated to the 4th century, the oldest runestone still standing at its original location.'), ('d8cae4fd-fcca-4187-9194-e89fa474bb49'::uuid, 'card_description', 'Near Valldemossa, on Mallorca''s north-west facing coast, Son Oleza keeps a nearly complete prehistoric village: houses, a Beaker culture dolmen and even a water supply system.'), ('d9d26446-9348-4f16-b5e4-c4c11e8ccffb'::uuid, 'card_description', 'Above Creiro Beach in the Arrábida Natural Park, the Roman Ruins of Creiro keep baths and a fish-salting factory, its salted fish and fish sauces exported throughout the Empire in amphorae.'), ('d9d2906b-4528-42af-9796-678ddf7ed30e'::uuid, 'card_description', 'On Anglesey, a grassy bank still some 1.5 metres high rings a level area some 54 metres in diameter: Castell Bryn Gwyn, White Hill Castle, maybe a Neolithic henge, walled in the Iron Age.'), ('dac7cdd2-495d-4410-b711-9d633c27c090'::uuid, 'card_description', 'Mostly of brick, the Caños de Carmona once ran 17.5 kilometres from a spring to Roman Hispalis, today Seville, and flowed until its demolition in 1912. Some sections still stand.'), ('dadbf949-f5cc-4313-9111-20224ebf9f43'::uuid, 'card_description', 'Ancient Greeks named it Pausílypon, respite from worry. On Posillipo the villa of Vedius Pollio keeps a 2000-seat theatre, and a 770 metre-long cave passes beneath the hill.'), ('dae23b93-8b4c-4e7c-961b-ca9bd54c4871'::uuid, 'card_description', 'On Trevelgue Head, three massive banks and ditches lie just before a gap crossed by a modern bridge. Over 4,000 shards of pottery and objects of tin, copper, iron and glass were found.'), ('dc789e55-ef9b-4d3e-8a82-075427def6ea'::uuid, 'card_description', 'About 20 kilometers from Ronda lie the ruins of Acinipo, a city believed to have been founded by retired soldiers of the Roman legions more than 2,000 years ago. Its theater is still in use.'), ('dc951bdb-a70d-4346-9e7d-fdc0d908d4c5'::uuid, 'card_description', 'On the south-west slope of Blackpatch Hill lie more than 64 infilled shafts of a Neolithic flint mine, galleries once reaching up to 8.5 metres along a single seam of flint.'), ('dd0f3348-710e-4e66-b50e-45bd71b61e12'::uuid, 'card_description', 'Badbury Hill looks over the Vale of White Horse and the Thames Valley. On its summit lies Badbury Camp, a roughly circular Iron Age hill fort, most of it levelled early in the 19th century.'), ('dd8e1148-5057-4496-a859-5f28c798a3f6'::uuid, 'card_description', 'Across the neck of its peninsula on Lake Petexbatún, the Maya site of Punta de Chimino dug three moats, one 12 metres deep, each topped by a palisaded wall, with box gardens between.'), ('de3c2d9b-b7df-40c5-bfce-3f8521d9ad8f'::uuid, 'card_description', 'Beside the modern road bridge, Pont Vell crosses the only river on Ibiza. Once the only way into Santa Eulària from the west, it is probably built on the foundations of a Roman bridge.'), ('df304236-53ea-44a0-8c2c-ef6a4b459728'::uuid, 'card_description', 'In Colliton Park, a steel and glass cover perched on the original foundations shelters the mosaic-floored West Range of the Roman Town House, Dorchester, built around 307 AD.'), ('dfed1a81-7d54-4f3b-b1ab-e2be649acc2f'::uuid, 'card_description', 'Above Heidelberg, the wooded Heiligenberg hides a Celtic double-walled hill fort and, in the nave of a ruined medieval basilica, the foundations of a Roman temple to Mercury.'), ('e0b78f4e-90c0-43a9-9f62-ac25c334fdff'::uuid, 'card_description', 'Over the Teign valley in Devon, Cranbrook Castle holds a commanding hilltop 337 metres above sea level: an Iron Age hill fort 2 kilometres from Prestonbury Castle, 3 from Wooston Castle.'), ('e116ffe7-981d-4944-b04d-b54fd896ba7d'::uuid, 'card_description', 'A ring of 36 stones once stood inside the Late Neolithic henge of the Devil''s Quoits, south of Stanton Harcourt. Most were gone by the end of the Medieval period; new stones now stand.'), ('e17ba5d6-296f-4441-85cb-8bff98ef2f7e'::uuid, 'card_description', 'Above the river Segre in the Pyrenees foothills, Roca dels Bous held flint and quartzite artifacts of Neanderthals who lived here approximately 50,000 years ago, and bones from their meals.'), ('e2030e0e-b33e-410c-b8df-8ccd76b8af03'::uuid, 'card_description', 'Khortytsia, the largest island on the Dnieper River, has been continuously inhabited for the last five millennia and played an important role in the history of the Zaporozhian Cossacks.'), ('e244d46c-a958-4c42-a154-5ed1ae613600'::uuid, 'card_description', 'On the Temenite hill, the Greek Theatre of Syracuse originally had 67 rows of seats, mostly cut into rock, in a theatron 138.6 metres across, one of the largest in the Greek world.'), ('e256cfc9-63fe-4f27-b7e9-6778a8317eb7'::uuid, 'card_description', 'Around 70 meters from the Lion Gate, the Tomb of Aegisthus held a burial chamber once around 13 meters tall under a corbelled dome. The dome collapsed; only about 8m of height remains.'), ('e2a04b44-a3e7-47fc-a217-0689fab93524'::uuid, 'card_description', 'Built in Naples in the first century BC, the Villa of Lucullus had piers stretching into the sea. Its remains are visible at several places, and Roman columns still stand in a castle cellar.'), ('e2aa3754-8d32-4455-bf6d-9077f18d50d2'::uuid, 'card_description', 'On the slopes of Mount Parnassus, Ancient Lilaia is named in Homer''s Iliad. Destroyed by Philip II of Macedon in 346 BCE, it was rebuilt; Pausanias later saw its theatre, agora and baths.'), ('e2bb7b81-bdd5-4713-893f-3c2c516a3d7a'::uuid, 'card_description', 'Where Vienna now stands lay Vindobona, a Roman camp fed by a 17 km water pipeline. Aurelius Victor recounts that emperor Marcus Aurelius died here on 17 March 180 of an unknown illness.'), ('e3330c2d-88f8-4101-88f0-4b174cb1bbf8'::uuid, 'card_description', 'Near the banks of the Carrión, La Olmeda Roman Villa set twenty-seven rooms, twelve with mosaic floors, around a patio crossed by geometric mosaic paths and ringed by a wide peristyle.'), ('e3357e9e-c79f-43db-bfb5-7e62ba21daff'::uuid, 'card_description', 'On the granite summit of Chapel Carn Brea lies a late Neolithic entrance grave 9 metres across, its entrance facing south. Of eleven barrows once on the hill, only seven now remain.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s015-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
